(window.TNQ=window.TNQ||[]).push({"terms":{"관습법":{"d":"사회에서 오랫동안 반복된 관행에 법적 확신이 더해져 법규범으로 승인된 것이다.","r":[]},"신의칙":{"d":"권리를 행사하고 의무를 이행할 때 상대방의 신뢰를 저버리지 않고 성실해야 한다는 민법의 원칙이다.","r":[]},"사정변경의 원칙":{"d":"계약의 기초가 된 사정이 당사자가 예견할 수 없게 현저히 바뀐 때 계약 내용의 변경이나 해제를 인정하는 원칙이다.","r":[]},"형성권":{"d":"권리자의 일방적 의사표시만으로 법률관계를 발생, 변경, 소멸시키는 권리이다.","r":[]},"항변권":{"d":"상대방의 청구에 대하여 이행을 거절할 수 있는 권리이다.","r":[]},"의사능력":{"d":"자신의 행위의 의미와 결과를 판단할 수 있는 정신 능력이다.","r":[]},"성년후견":{"d":"정신적 제약으로 사무처리 능력이 지속적으로 없는 사람을 보호하려고 가정법원이 하는 심판.","r":["한정후견","특정후견"]},"한정후견":{"d":"사무처리 능력이 부족한 사람을 보호하려고 가정법원이 하는 심판.","r":["성년후견","특정후견"]},"특정후견":{"d":"일시적이거나 특정 사무에 한하여 후원이 필요한 사람을 위해 하는 후견이다.","r":[]},"실종선고":{"d":"부재자의 생사가 일정 기간 분명하지 않을 때 법원이 사망으로 보게 하는 선고이다.","r":[]},"부재자":{"d":"종래의 주소나 거소를 떠나 돌아올 가능성이 불분명한 사람이다.","r":[]},"공시최고":{"d":"법원이 일정 기간 공고해 권리 신고나 생사 신고를 촉구하는 절차.","r":[]},"비영리법인":{"d":"영리 아닌 사업을 목적으로 하며 주무관청의 허가를 받아 성립하는 사단 또는 재단.","r":[]},"청산인":{"d":"법인이 해산한 뒤 재산 정리 등 청산 사무를 맡아 처리하는 사람이다.","r":[]},"총유":{"d":"법인 아닌 사단의 사원이 집합체로서 물건을 소유하는 형태이다.","r":[]},"합유":{"d":"조합체로서 수인이 물건을 소유하는 공동소유로 처분·변경에 전원 동의가 필요하다.","r":["총유"]},"종물":{"d":"주물의 상용에 이바지하도록 같은 소유자의 다른 물건에 부속시킨 독립된 물건이다.","r":[]},"법정과실":{"d":"물건을 사용한 대가로 받는 금전이나 물건으로, 이자나 임대료가 해당한다.","r":[]},"처분행위":{"d":"권리의 변동을 직접 일으키는 법률행위이다.","r":[]},"통정허위표시":{"d":"상대방과 통정하여 하는 허위의 의사표시이다.","r":[]},"표현대리":{"d":"대리권이 없는데도 대리권이 있는 것 같은 외관이 있고 본인에게 책임이 있어 본인이 책임지는 제도이다.","r":[]},"무권대리":{"d":"대리권 없이 대리인으로 행동하는 것이다. 본인이 추인하지 않으면 본인에게 효력이 없다.","r":[]},"복대리인":{"d":"대리인이 자기 이름으로 선임한 본인의 대리인이다. 선임한 대리인을 통해 본인을 대리한다.","r":[]},"법정추인":{"d":"취소할 수 있는 행위를 추인한 것으로 보는 법정 사유로, 전부나 일부의 이행 등이 있다.","r":[]},"정지조건":{"d":"법률행위의 효력 발생을 장래의 불확실한 사실에 걸어 둔 조건이다. 조건이 성취된 때 효력이 생긴다.","r":[]},"해제조건":{"d":"이미 생긴 법률행위의 효력을 장래의 불확실한 사실이 성취되면 잃게 하는 조건이다.","r":[]},"소멸시효":{"d":"권리를 행사할 수 있는데도 일정 기간 행사하지 않으면 그 권리가 소멸하는 제도이다.","r":[]},"선의취득":{"d":"평온·공연하게 동산을 선의·무과실로 양수한 자가 양도인이 무권리자여도 소유권을 취득하는 제도.","r":[]},"혼동":{"d":"소유권과 다른 물권 또는 채권과 채무가 한 사람에게 귀속해 권리가 소멸하는 것.","r":[]},"원시취득":{"d":"다른 사람의 권리에 의존하지 않고 새로 권리를 취득하는 것.","r":[]},"가등기":{"d":"장래의 본등기를 위해 순위를 미리 보전해 두는 예비 등기이다.","r":[]},"명의신탁":{"d":"실제 소유자가 자기 재산의 등기 명의를 타인에게 맡겨 두는 약정이다.","r":[]},"점유취득시효":{"d":"타인의 부동산을 일정 기간 소유의 의사로 평온하고 공연하게 점유하여 소유권을 취득하는 제도이다.","r":[]},"자주점유":{"d":"소유자와 같은 지배를 하려는 의사를 가진 점유이다.","r":[]},"지상권":{"d":"타인의 토지에 건물이나 수목을 소유하기 위해 그 토지를 사용하는 물권이다.","r":[]},"지역권":{"d":"자기 토지의 편익을 위해 타인의 토지를 이용하는 물권이다. 편익을 얻는 토지가 요역지이다.","r":[]},"전세권":{"d":"전세금을 지급하고 타인의 부동산을 사용하고 수익하며 반환 시 우선변제를 받는 물권이다.","r":[]},"유치권":{"d":"타인의 물건을 점유한 사람이 그 물건에 관하여 생긴 채권을 변제받을 때까지 점유를 계속하는 담보물권이다.","r":[]},"근저당":{"d":"채무의 최고액만 정하고 채무 확정을 장래에 두고 설정하는 저당권.","r":[]},"선택채권":{"d":"채권의 목적이 여러 행위 중 선택으로 확정되는 채권.","r":[]},"과실상계":{"d":"손해 발생에 피해자의 과실이 있을 때 이를 참작하여 배상액을 줄이는 제도이다.","r":[]},"채권자대위권":{"d":"채권자가 자기 채권을 보전하려고 채무자의 권리를 대신 행사하는 권리.","r":["채권자취소권"]},"채권자취소권":{"d":"채무자가 채권자를 해치는 법률행위를 한 때 채권자가 법원에 그 취소를 청구하는 권리이다.","r":[]},"불가분채무":{"d":"채무의 성질상 나눌 수 없어 여러 채무자가 연대하여 이행하는 채무.","r":["연대채무"]},"연대채무":{"d":"여러 채무자가 각자 채무 전부를 이행할 의무가 있고 한 사람의 이행으로 모두 면책되는 채무.","r":["불가분채무"]},"최고":{"d":"상대방에게 일정한 행위를 하라고 촉구하는 통지이다. 무권대리에서는 추인 여부의 확답을 촉구하는 데 쓴다.","r":[]},"상계":{"d":"서로 같은 종류의 채권을 가진 당사자가 의사표시로 대등액에서 채권을 소멸시키는 것이다.","r":[]},"경개":{"d":"채무의 중요한 부분을 변경하는 계약으로 구채무를 소멸시키고 신채무를 성립시키는 것.","r":[]},"동시이행의 항변권":{"d":"쌍무계약에서 상대방이 이행을 제공할 때까지 자기 채무의 이행을 거절할 수 있는 권리.","r":[]},"예약완결권":{"d":"매매의 예약에서 한쪽이 의사표시만으로 본계약을 성립시킬 수 있는 권리이다.","r":[]},"환매":{"d":"매도인이 매매와 동시에 권리를 보류해 대금과 비용을 돌려주고 목적물을 되사는 것.","r":[]},"담보책임":{"d":"매매 목적물에 권리나 물건의 하자가 있을 때 매도인이 지는 책임.","r":[]},"부속물매수청구권":{"d":"건물 임차인이 임대인의 동의를 얻어 부속시킨 물건을 임대인에게 매수하라고 청구하는 권리이다.","r":[]},"사무관리":{"d":"법률상 의무 없이 타인을 위해 사무를 관리하는 것.","r":[]},"부당이득":{"d":"법률상 원인 없이 타인의 재산이나 노무로 이익을 얻고 그 때문에 타인에게 손해를 입히는 것이다.","r":[]},"불법원인급여":{"d":"불법한 원인으로 재산을 준 경우 그 반환을 청구하지 못하는 제도이다.","r":[]},"공동불법행위":{"d":"여럿이 공동으로 불법행위를 하여 연대하여 배상책임을 지는 경우.","r":[]},"부진정연대":{"d":"공동불법행위자들의 연대처럼 채무자들이 각자 전부 이행 의무를 지지만 절대적 효력이 제한되는 연대.","r":["연대채무"]},"위자료":{"d":"재산 이외의 정신상 고통에 대한 손해배상.","r":[]},"사실인 관습":{"d":"법적 확신 없이 사회에서 반복되는 관행으로, 법률행위 당사자의 의사를 보충하는 데 그치며 법규범은 아니다.","r":[]},"조리":{"d":"사물의 이치나 도리로, 법률과 관습법이 없을 때 재판의 기준이 되는 법원이다.","r":[]},"집행명령":{"d":"법률의 규정을 집행하기 위해 필요한 세칙을 정하는 명령이다.","r":[]},"실효의 원칙":{"d":"권리자가 오랫동안 권리를 행사하지 않아 상대방이 더는 행사하지 않으리라고 믿게 된 경우 권리 행사를 막는 신의칙의 파생 원칙이다.","r":[]},"일방예약완결권":{"d":"예약상의 권리자가 일방적 의사표시로 매매 본계약을 성립시킬 수 있는 권리로 형성권이다.","r":[]},"지상물매수청구권":{"d":"지상권자나 토지임차인이 계약이 끝날 때 지상 건물의 매수를 토지 소유자에게 청구하는 권리이다.","r":[]},"유익비상환청구권":{"d":"물건의 가치를 늘리려고 쓴 비용을 가치 증가가 남아 있을 때 돌려받을 수 있는 권리이다.","r":[]},"일신전속권":{"d":"특정인에게만 속하여 양도나 상속이 되지 않는 권리이다.","r":[]},"연기적 항변권":{"d":"청구권의 존재는 인정하되 행사를 일시적으로 막는 항변권으로 동시이행의 항변권이 있다.","r":[]},"최고ㆍ검색의 항변권":{"d":"보증인이 채권자에게 먼저 주채무자에게 청구하고 재산을 집행하라고 요구할 수 있는 권리이다.","r":[]},"상린관계":{"d":"인접한 토지의 소유자 사이에 서로 이용을 조절하는 법률관계이다.","r":[]},"수인한도":{"d":"이웃에게 끼친 피해가 사회생활상 참고 견뎌야 하는 범위이다.","r":[]},"천연과실":{"d":"물건의 용법에 따라 얻는 산출물로, 과일이나 새끼 가축 같은 것이다.","r":[]},"입목":{"d":"토지에 자라는 수목의 집단으로, 입목에 관한 법률에 따라 등기하면 토지와 별개의 부동산으로 다뤄진다.","r":[]},"명인방법":{"d":"수목의 집단이나 미분리 과실 등의 소유권을 제3자가 알 수 있게 표시하는 관습법상의 공시 방법이다.","r":[]},"타주점유":{"d":"소유의 의사 없이 타인의 소유를 인정하면서 하는 점유이다.","r":[]},"취득시효":{"d":"일정 기간 물건을 점유하거나 권리를 행사하면 권리를 취득하는 제도이다.","r":[]},"시효이익의 포기":{"d":"시효가 완성된 뒤에 그로 인한 이익을 받지 않겠다고 하는 의사표시이다.","r":[]},"공유":{"d":"여러 사람이 하나의 물건을 지분을 가지고 소유하는 형태이다.","r":[]},"구분소유적 공유":{"d":"한 필지를 위치를 정해 나누어 소유하면서 등기만 지분으로 공유 형식을 취한 관계이다.","r":[]},"가분채권":{"d":"급부를 나누어도 성질이나 가치가 줄지 않는 채권이다.","r":[]},"불가분채권":{"d":"급부의 성질상 나눌 수 없어 채권자가 여럿이면 각자 전부를 청구할 수 있는 채권이다.","r":[]},"방해배제청구":{"d":"소유권 행사를 방해하는 자에게 방해를 없애 달라고 청구하는 권리이다.","r":[]},"재산관리인":{"d":"부재자의 재산을 관리하도록 법원이 선임하는 사람이다.","r":[]},"인정사망":{"d":"수해나 화재 등으로 사망이 확실하지만 시체를 확인하지 못할 때 관공서의 보고로 사망을 인정하는 제도이다.","r":[]},"권리능력":{"d":"권리와 의무의 주체가 될 수 있는 법적 자격이다.","r":[]},"제한능력자":{"d":"단독으로 완전한 법률행위를 할 수 없어 보호받는 사람이다. 미성년자, 피성년후견인, 피한정후견인이 있다.","r":[]},"피성년후견인":{"d":"정신적 제약으로 사무를 처리할 능력이 지속적으로 결여되어 가정법원의 성년후견개시 심판을 받은 사람이다.","r":[]},"피한정후견인":{"d":"정신적 제약으로 사무 처리 능력이 부족하여 한정후견개시 심판을 받은 사람이다.","r":[]},"확답을 촉구":{"d":"제한능력자의 상대방이 법정대리인 등에게 일정 기간 안에 추인 여부를 확답하라고 요구하는 것이다.","r":[]},"대습상속":{"d":"상속인이 될 직계비속이나 형제자매가 먼저 사망하거나 결격되었을 때 그 직계비속이 대신 상속하는 제도이다.","r":[]},"청산법인":{"d":"해산 후 청산 절차가 진행 중인 법인이다.","r":[]},"재단법인":{"d":"일정한 목적에 바쳐진 재산을 중심으로 설립되는 법인이다.","r":[]},"사단법인":{"d":"일정한 목적을 위해 모인 사람의 결합체를 기초로 설립되는 법인이다.","r":[]},"주무관청":{"d":"법인의 설립 허가와 감독을 맡은 행정기관이다.","r":[]},"정관":{"d":"법인의 조직과 활동에 관한 근본 규칙 또는 그것을 적은 문서이다.","r":[]},"필요적 기재사항":{"d":"정관에 반드시 기재해야 하며, 빠지면 정관이 효력을 갖지 못하는 사항이다.","r":[]},"임의적 기재사항":{"d":"정관에 기재해도 되고 하지 않아도 되는 사항이다.","r":[]},"사원총회":{"d":"사단법인의 사원 전원으로 구성된 최고 의사결정 기관이다.","r":[]},"통상총회":{"d":"사단법인에서 매년 한 번 이상 정기적으로 소집하는 사원총회이다.","r":[]},"임시이사":{"d":"이사가 없거나 결원이 생겨 손해가 날 염려가 있을 때 법원이 선임하는 이사이다.","r":[]},"대표권":{"d":"법인을 대표하여 법률행위를 할 수 있는 권한이다.","r":[]},"기본재산":{"d":"재단법인의 목적 사업을 위한 핵심 재산이다.","r":[]},"비법인 사단":{"d":"단체로서 실체는 있으나 법인 등기를 하지 않은 사단이다.","r":[]},"종중":{"d":"공동 선조의 분묘 수호와 제사, 종원 간 친목 도모를 목적으로 하는 자연 발생적 종족 집단이다.","r":[]},"준법률행위":{"d":"의사표시가 아니면서 법률이 일정한 효과를 부여하는 행위로, 최고, 승인, 통지 등이 해당한다.","r":[]},"준물권행위":{"d":"물권 외의 권리의 변동을 직접 일으키는 행위로 채권양도가 해당한다.","r":[]},"반사회질서의 법률행위":{"d":"선량한 풍속이나 그 밖의 사회질서에 반하여 무효가 되는 법률행위이다.","r":[]},"불공정한 법률행위":{"d":"상대방의 궁박, 경솔, 무경험을 이용해 현저히 균형을 잃은 이익을 얻는 법률행위로 무효이다.","r":[]},"궁박":{"d":"급박한 곤궁으로, 경제적 원인뿐 아니라 정신적, 심리적 원인에 의한 것도 포함한다.","r":[]},"규범적 해석":{"d":"표시행위를 상대방의 입장에서 객관적으로 이해되는 의미대로 해석하는 방법이다.","r":[]},"자연적 해석":{"d":"표의자의 진정한 내심의 의사를 밝혀 해석하는 방법으로, 당사자 쌍방의 의사가 일치하면 이를 따른다.","r":[]},"보충적 해석":{"d":"당사자가 정하지 않은 사항에 대해 계약의 취지에 맞게 빈틈을 메우는 해석이다.","r":[]},"무효행위의 전환":{"d":"무효인 법률행위가 다른 법률행위의 요건을 갖추면 그 효력을 인정하는 것이다.","r":[]},"허위표시":{"d":"상대방과 짜고 진의와 다르게 하는 의사표시로, 당사자 사이에서는 무효이다.","r":[]},"진의 아닌 의사표시":{"d":"표의자가 진의와 다르다는 것을 스스로 알면서 하는 의사표시로, 원칙적으로 유효하다.","r":[]},"착오":{"d":"표의자가 내심의 효과의사와 표시가 일치하지 않음을 모르고 하는 의사표시이다.","r":[]},"중요부분의 착오":{"d":"착오가 없었다면 의사표시를 하지 않았을 정도로 법률행위 내용의 중요한 부분에 관한 착오이다.","r":[]},"기망행위":{"d":"사실을 속이는 행위로, 사기에 의한 의사표시의 요건이다.","r":[]},"강박":{"d":"해악을 알려 공포심을 일으켜 의사표시를 하게 하는 것이다.","r":[]},"공시송달":{"d":"상대방의 소재를 알 수 없을 때 법원 게시 등으로 의사표시가 도달한 것으로 보는 제도이다.","r":[]},"토지거래허가구역":{"d":"투기를 막으려고 토지 거래에 관할관청의 허가를 받도록 지정한 구역이다. 허가 없이 한 매매계약은 효력이 생기지 않는다.","r":[]},"유동적 무효":{"d":"허가를 받으면 소급하여 유효가 되고 받지 못하면 무효로 확정되는 불안정한 상태이다. 토지거래허가를 받기 전 계약이 이에 해당한다.","r":[]},"허가신청협력의무":{"d":"토지거래허가를 받기 위해 상대방과 함께 허가 신청 절차에 협력해야 하는 계약상 의무이다.","r":[]},"비진의 의사표시":{"d":"표의자가 진의 아님을 알고 하는 의사표시이다. 상대방이 진의 아님을 알았거나 알 수 있었다면 무효이다.","r":[]},"선의":{"d":"법률에서 어떤 사정을 알지 못하는 것을 말한다. 도덕적으로 착하다는 뜻이 아니다.","r":[]},"악의":{"d":"법률에서 어떤 사정을 알고 있는 것을 말한다. 해칠 의도를 뜻하지 않는다.","r":[]},"추인":{"d":"효력이 확정되지 않았거나 취소할 수 있는 법률행위를 사후에 확정적으로 유효로 하는 의사표시이다.","r":[]},"취소권자":{"d":"취소할 수 있는 법률행위를 취소할 권리를 가진 사람이다. 제한능력자 본인과 대리인, 착오나 사기를 당한 표의자 등이다.","r":[]},"유권대리":{"d":"정당한 대리권을 가진 대리인이 한 대리행위이다. 그 효과가 본인에게 귀속된다.","r":[]},"강행법규":{"d":"당사자의 합의로 배제할 수 없는 법규이다. 이를 위반한 법률행위는 원칙적으로 무효이다.","r":[]},"유추적용":{"d":"법에 직접 규정이 없는 사안에 비슷한 사안의 규정을 가져다 적용하는 것이다.","r":[]},"일상가사대리권":{"d":"부부가 일상의 가사에 관하여 서로 대리할 수 있는 권한이다.","r":[]},"기본대리권":{"d":"권한을 넘은 표현대리가 성립하려면 먼저 존재해야 하는 대리인의 대리권이다.","r":[]},"임의대리":{"d":"본인이 대리권을 수여하여 생기는 대리이다. 법률 규정으로 생기는 법정대리와 구분한다.","r":[]},"법정대리":{"d":"법률의 규정이나 법원의 선임 등으로 대리권이 생기는 대리이다. 친권자와 후견인이 대표적이다.","r":[]},"특별수권":{"d":"처분행위처럼 대리인의 통상 권한을 넘는 행위를 하려면 본인이 따로 주는 권한이다.","r":[]},"철회":{"d":"아직 효력을 발생시키지 않은 의사표시나 법률행위를 거두어들이는 것이다. 무권대리의 상대방이 계약을 철회할 수 있다.","r":[]},"기한의 이익":{"d":"기한이 아직 도래하지 않음으로써 당사자가 받는 이익이다. 기한이익 상실의 특약이 있으면 이를 잃을 수 있다.","r":[]},"기한이익 상실의 특약":{"d":"채무자가 일정한 사유를 일으키면 기한의 이익을 잃고 즉시 이행해야 한다고 정한 약정이다.","r":[]},"시효중단":{"d":"시효 진행 중 일정한 사유가 생기면 그때까지 지난 기간을 없애고 다시 처음부터 진행하게 하는 것이다.","r":[]},"승인":{"d":"소멸시효의 중단사유로서 채무자가 채무가 있음을 인정하는 행위이다. 묵시적으로도 할 수 있다.","r":[]},"재판상의 청구":{"d":"소 제기와 같이 법원에 권리를 주장하는 재판상 청구이다. 소멸시효 중단사유이다.","r":[]},"가압류":{"d":"금전채권을 보전하기 위해 채무자의 재산을 미리 묶어 두는 임시 조치이다. 소멸시효의 중단사유이다.","r":[]},"제척기간":{"d":"권리가 존속할 수 있는 법정 기간이다. 시효와 달리 중단이 없고 법원이 직권으로 조사한다.","r":[]},"관념의 통지":{"d":"어떤 사실을 알리는 행위로, 법률이 효과를 부여하는 것이다. 의사표시와 달리 효과를 바라는 의사를 요소로 하지 않는다.","r":[]},"담보가등기":{"d":"채권을 담보하기 위해 마치는 가등기이다. 채권자가 담보 목적으로 이를 설정한다.","r":[]},"나대지":{"d":"건물 등이 없는 대지이다. 저당권 설정 시 담보가치를 유지하기 위한 지상권 설정이 문제 된다.","r":[]},"관습상 법정지상권":{"d":"토지와 건물이 같은 소유자였다가 소유자가 달라질 때 건물 소유자에게 관습법상 인정되는 지상권이다.","r":[]},"용익물권":{"d":"타인의 물건을 사용하고 수익하는 것을 내용으로 하는 물권이다. 지상권, 지역권, 전세권이 있다.","r":[]},"담보물권":{"d":"채권의 담보를 목적으로 하여 채무자 물건에 대한 우선변제권을 갖는 물권이다. 저당권, 질권, 유치권이 있다.","r":[]},"분묘기지권":{"d":"타인의 토지에 분묘를 설치한 사람이 분묘를 소유하기 위해 그 기지를 사용하는 관습법상 권리이다.","r":[]},"시효취득":{"d":"일정 기간 점유 등의 사실이 계속된 때 권리를 취득하는 제도이다.","r":[]},"물권법정주의":{"d":"물권의 종류와 내용은 법률이나 관습법으로만 정할 수 있다는 원칙이다.","r":[]},"일물일권주의":{"d":"하나의 물건 위에는 하나의 물권만 성립한다는 원칙이다. 독립한 물건이어야 물권의 객체가 된다.","r":[]},"양도담보권":{"d":"채권 담보를 위해 소유권 등을 채권자에게 이전하는 형식의 담보이다.","r":[]},"물권적 청구권":{"d":"물권의 내용 실현이 방해될 때 방해자에게 이를 제거하라고 청구하는 권리이다. 반환, 방해제거, 방해예방 청구권이 있다.","r":[]},"중간생략등기":{"d":"부동산이 순차로 거래되었을 때 중간자를 건너뛰고 최초 매도인에서 최종 매수인에게 직접 하는 소유권이전등기이다.","r":[]},"합의해제":{"d":"계약 당사자가 합의하여 계약을 소멸시키는 것이다. 법정해제에 관한 규정이 원칙적으로 적용되지 않는다.","r":[]},"점유물방해제거청구권":{"d":"점유자가 점유를 방해당했을 때 방해의 제거를 청구하는 권리이다.","r":[]},"물상대위성":{"d":"담보물이 멸실, 훼손되었을 때 그 담보물이 변하여 생긴 금전 등에 담보물권의 효력이 미치는 성질이다.","r":[]},"간이변제충당":{"d":"질권자나 유치권자가 법원의 허가를 받아 감정 가액으로 변제에 충당하는 것이다.","r":[]},"불가분성":{"d":"유치권자가 채권 전부를 변제받을 때까지 유치물 전부에 대해 권리를 행사할 수 있는 성질이다.","r":[]},"피담보채권":{"d":"담보물권으로 담보되는 채권이다. 이 채권이 소멸하면 담보물권도 소멸한다.","r":[]},"제3취득자":{"d":"저당권이 설정된 부동산의 소유권이나 지상권 등을 나중에 취득한 사람이다.","r":[]},"전형계약":{"d":"민법이 유형별로 규정한 계약이다. 증여, 매매, 도급, 위임 등 열다섯 가지이다.","r":[]},"수급인":{"d":"도급계약에서 일을 완성할 의무를 지는 사람이다.","r":[]},"도급인":{"d":"도급계약에서 일의 결과에 대한 보수를 지급할 의무를 지는 사람이다.","r":[]},"지체상금":{"d":"수급인이 정한 기한 안에 일을 완성하지 못했을 때 도급인에게 지급하기로 한 지연배상금이다.","r":[]},"편무예약":{"d":"예약 당사자 한쪽만 예약완결권을 가지는 예약이다.","r":[]},"하자담보책임":{"d":"매매나 도급의 목적물에 하자가 있을 때 매도인이나 수급인이 지는 법정 책임이다.","r":[]},"전차인":{"d":"임차인으로부터 다시 목적물을 빌린 사람이다.","r":[]},"전대차":{"d":"임차인이 임차물을 다시 제3자에게 빌려주는 계약이다.","r":[]},"건물매수청구권":{"d":"토지 임차인이 임대차가 끝날 때 지상 건물의 매수를 임대인에게 청구하는 권리이다.","r":[]},"이행불능":{"d":"채무 이행이 불가능하게 된 상태이다. 채무자의 귀책사유가 있으면 손해배상 책임이 생긴다.","r":[]},"채권양도":{"d":"채권의 동일성을 유지하면서 계약으로 채권을 제3자에게 이전하는 것이다.","r":[]},"변제충당":{"d":"채무자의 변제가 채무 전부를 소멸시키기에 모자랄 때 어느 채무에 충당할지를 정하는 것이다.","r":[]},"보증채무":{"d":"주채무자가 이행하지 않을 때 보증인이 대신 이행해야 하는 부종성을 가진 채무이다.","r":[]},"구상권":{"d":"다른 사람을 위해 채무를 변제한 사람이 그 사람에게 상환을 청구하는 권리이다.","r":[]},"상당인과관계":{"d":"어떤 행위가 있으면 통상 그 결과가 생기리라고 인정되는 관계로 손해배상의 범위를 정하는 기준이다.","r":[]},"명의신탁약정":{"d":"부동산 소유자 명의를 실제 소유자 아닌 사람 이름으로 등기하기로 하는 약정이다.","r":[]}},"notes":{"10년간 소유의 의사로 평온ㆍ공연하게 점유하면 소유권 취득. 선의이며 과실 없이 개시한 경우 5년":"동산은 10년간 소유 의사로 평온·공연하게 점유하면 취득하고 선의·무과실로 개시하면 5년입니다.","10년을 넘지 못한다(10년 초과 약정은 10년으로 단축). 건물에 대한 전세권을 1년 미만으로 정하면 1년. 갱신할 수 있고 갱신 기간도 갱신한 날로부터 10년을 넘지 못한다":"전세권의 존속기간은 10년을 넘지 못하고 건물 전세권을 1년 미만으로 정하면 1년이 되며 갱신 기간도 10년을 넘지 못합니다.","12세 미성년자 가해자의 학교 선생님은 법정감독의무자가 아니다(법정감독의무자는 친권자 등). 대리감독자일 뿐이다":"12세 가해자의 학교 선생님은 법정감독의무자가 아니라 대리감독자일 뿐이고 법정감독의무자는 친권자 등이에요.","1인의 설립자에 의한 재단법인 설립행위, 유언, 소유권의 포기":"1인 설립자의 재단법인 설립행위, 유언, 소유권 포기는 상대방 없는 단독행위입니다.","1필의 토지의 일부에 대한 시효취득도 인정될 수 있다. 성명불상자의 소유물에 대해서도 시효취득이 인정된다":"1필 토지의 일부나 성명불상자의 소유물에 대해서도 시효취득이 인정될 수 있어요.","1필의 토지의 일부에 대해서도 지역권을 설정할 수 있다":"땅 전체가 아닌 일부분에도 지역권을 설정하는 것이 가능합니다.","1필의 토지의 일부에도 전세권ㆍ지역권을 설정할 수 있다. 1필 토지의 일부에 대한 시효취득도 인정될 수 있다(분필 후 등기)":"1필 토지의 일부에도 전세권이나 지역권을 설정할 수 있고 일부의 시효취득도 인정될 수 있어요.","20년간 행사하지 않으면 소멸한다. 요역지 공유자 1인에 의한 소멸시효의 중단ㆍ정지는 다른 공유자를 위하여 효력이 있다":"지역권은 20년간 행사하지 않으면 소멸하고 요역지 공유자 한 명의 중단·정지는 다른 공유자에게도 효력이 있어요.","2인 이상이 동일한 위난으로 사망한 경우에는 동시에 사망한 것으로 추정한다(간주 아님)":"둘 이상이 같은 위난으로 숨지면 동시에 사망한 것으로 추정하며, 간주가 아니라 반증이 가능합니다.","X토지에 관하여 계약이 성립한다(오표시 무해의 원칙)":"이때는 오표시 무해의 원칙에 따라 X토지에 대해 계약이 성립합니다.","① 20년간 소유의 의사로 평온ㆍ공연하게 부동산을 점유하는 자는 등기함으로써 소유권을 취득한다. ② 부동산 소유자로 등기한 자가 10년간 소유의 의사로 평온ㆍ공연하게 선의이며 과실 없이 점유한 때 소유권을 취득한다(등기부취득시효)":"20년간 소유 의사로 평온·공연하게 점유하면 등기로 소유권을 취득하고, 등기부취득시효는 10년에 선의·무과실이 필요해요.","① 과실 없이 채권자에게 변제할 재판을 받은 때 ② 주채무자가 파산선고를 받은 경우 채권자가 파산재단에 가입하지 않은 때 ③ 채무의 이행기가 확정되지 않고 최장기도 확정할 수 없는 경우 보증계약 후 5년을 경과한 때 ④ 채무의 이행기가 도래한 때. 제4호의 경우 보증계약 후 채권자가 주채무자에게 허여한 기한으로 보증인에게 대항하지 못한다":"수탁보증인은 변제 재판을 받은 때, 파산선고 후 채권자 미가입, 이행기 불확정으로 5년 경과, 이행기 도래 때 사전구상권이 있어요.","① 보존행위 ② 대리의 목적인 물건이나 권리의 성질을 변하지 아니하는 범위에서 이용 또는 개량하는 행위":"권한을 정하지 않은 대리인은 보존행위와 성질을 변하지 않는 범위의 이용·개량행위만 할 수 있어요.","① 본인의 사망 ② 대리인의 사망, 성년후견의 개시 또는 파산":"본인이 죽거나 대리인이 죽거나 성년후견이 시작되거나 파산하면 대리권이 사라집니다.","① 석조ㆍ석회조ㆍ연와조 또는 이와 유사한 견고한 건물이나 수목의 소유 목적 30년 ② 그 외 건물 소유 목적 15년 ③ 건물 이외의 공작물 소유 목적 5년. 더 짧게 정하면 위 기간까지 연장된다":"견고한 건물이나 수목은 30년, 그 밖의 건물은 15년, 건물 이외의 공작물은 5년이 최단기간이고 더 짧게 정하면 그 기간으로 늘어납니다.","① 여관ㆍ음식점ㆍ대석ㆍ오락장의 숙박료, 음식료, 대석료, 입장료, 소비물의 대가 및 체당금 ② 의복ㆍ침구ㆍ장구 기타 동산의 사용료 ③ 노역인ㆍ연예인의 임금 및 공급한 물건의 대금 ④ 학생 및 수업자의 교육ㆍ의식ㆍ유숙에 관한 교주ㆍ숙주ㆍ교사의 채권":"숙박료·음식료, 동산 사용료, 임금, 학생 교육 채권 등은 더 짧은 단기소멸시효가 적용되는 채권입니다.","① 이자, 부양료, 급료, 사용료 기타 1년 이내의 기간으로 정한 금전 또는 물건의 지급을 목적으로 한 채권 ② 의사ㆍ조산사ㆍ간호사ㆍ약사의 치료ㆍ근로ㆍ조제에 관한 채권 ③ 도급받은 자ㆍ기사 기타 공사의 설계 또는 감독에 종사하는 자의 공사에 관한 채권 ④ 변호사ㆍ변리사ㆍ공증인ㆍ공인회계사ㆍ법무사에 대한 직무상 보관한 서류의 반환을 청구하는 채권 ⑤ 변호사 등의 직무에 관한 채권 ⑥ 생산자 및 상인이 판매한 생산물 및 상품의 대가 ⑦ 수공업자 및 제조자의 업무에 관한 채권":"이자·급료 채권, 의료·약사 채권, 설계 감독 채권, 상품 대가 등은 단기소멸시효가 적용되는 채권으로 열거됩니다.","① 전부나 일부의 이행 ② 이행의 청구 ③ 경개 ④ 담보의 제공 ⑤ 취소할 수 있는 행위로 취득한 권리의 전부나 일부의 양도 ⑥ 강제집행. 추인할 수 있는 후에 해야 하며 이의를 보류하면 추인한 것으로 보지 않는다":"이행, 이행청구, 경개, 담보제공, 권리양도, 강제집행이 법정추인 사유이며 추인할 수 있는 후에 이의 보류 없이 해야 합니다.","① 증여자 또는 그 배우자나 직계혈족에 대한 범죄행위 ② 증여자에 대하여 부양의무 있는데 이행하지 않은 때. 해제권은 해제원인 있음을 안 날부터 6월이 경과하거나 증여자가 용서의 의사를 표시한 때 소멸한다":"수증자가 증여자에게 범죄행위를 하거나 부양의무를 이행하지 않으면 해제할 수 있고 해제권은 안 날부터 6월이 지나거나 용서하면 소멸합니다.","① 청구 ② 압류 또는 가압류ㆍ가처분 ③ 승인":"시효중단 사유는 청구, 압류·가압류·가처분, 승인 세 가지입니다.","① 확정기한 있는 채무는 기한이 도래한 때부터 ② 불확정기한 있는 채무는 채무자가 기한이 도래함을 안 때부터 ③ 기한이 없는 채무는 이행청구를 받은 때부터 지체책임이 있다":"지체책임은 확정기한이면 기한 도래 때, 불확정기한이면 도래를 안 때, 기한이 없으면 이행청구를 받은 때부터 생깁니다.","「입목에 관한 법률」상 입목(소유권보존등기한 수목의 집단)은 토지와 별개의 부동산으로 보며 토지와 분리하여 저당권의 목적이 될 수 있다. 별도의 공시방법을 갖추면 토지와 독립하여 거래의 객체가 될 수 있다":"입목법상 입목은 토지와 별개의 부동산이어서 토지와 따로 저당권의 목적이 되고 독립하여 거래될 수 있습니다.","가등기가 있다고 해서 소유권이전등기를 청구할 어떤 법률관계가 있다고 추정되지 않는다":"가등기가 있다고 해서 이전등기를 청구할 법률관계가 있는 것으로 추정되지는 않습니다.","가등기권리자는 가등기에 기하여 무효인 중복된 소유권보존등기의 말소를 구할 수 없다":"가등기권리자는 가등기만을 근거로 중복된 무효 보존등기의 말소를 요구할 수 없습니다.","가등기담보법상 채권자가 담보권을 실행하여 소유권을 취득하려면 채권의 변제기 후에 청산금 평가액을 채무자등에게 통지하고, 통지가 도달한 날부터 2개월(청산기간)이 지나야 한다. 청산금이 없다고 인정되는 경우에도 그 뜻을 통지하여야 한다":"담보권 실행으로 소유권을 얻으려면 변제기 후 청산금 평가액을 통지하고 도달일부터 2개월이 지나야 하며 청산금이 없어도 그 뜻을 통지해야 합니다.","가등기된 소유권이전등기청구권은 타인에게 양도할 수 있다(양도하려면 부기등기)":"가등기된 소유권이전등기청구권은 부기등기를 해서 타인에게 양도할 수 있어요.","가등기 효력: 본등기의 순위 보전 효력만 있다. 본등기가 마쳐져도 물권변동의 효력은 본등기 시에 발생하며 가등기한 때로 소급하지 않는다":"가등기는 본등기의 순위를 보전하는 효력만 있고 물권변동은 본등기 때 생길 뿐 가등기 때로 소급하지 않아요.","가등기 후 제3자에게 소유권이전등기가 이루어진 경우 가등기권리자는 가등기 당시의 소유명의인에게 본등기를 청구하고 현재 소유명의인에게는 본등기 승낙을 구한다":"가등기 후 제3자에게 이전되면 가등기 당시 소유명의인에게 본등기를 청구하고 현재 명의인에게는 승낙을 구합니다.","가분적인 법률행위의 일부에만 취소사유가 있고 나머지를 유지하려는 당사자의 가정적 의사가 있는 경우 일부만의 취소도 가능하다":"가분적 행위의 일부에만 취소사유가 있고 나머지를 유지하려는 가정적 의사가 있으면 일부만 취소할 수 있어요.","가사상ㆍ영업상 기타 유사한 관계에 의하여 타인의 지시를 받아 물건을 사실상 지배하는 때에는 그 타인만을 점유자로 한다":"가사상·영업상 관계로 타인의 지시를 받아 물건을 지배하는 자는 점유보조자로, 그 타인만 점유자입니다.","가압류는 시효중단 사유이며 그 효력은 가압류의 집행보전의 효력이 존속하는 동안 계속된다. 취득시효에서는 부동산에 대한 압류ㆍ가압류가 취득시효 중단사유가 아니다":"가압류는 집행보전의 효력이 존속하는 동안 중단 효력이 계속되며, 취득시효에서는 압류·가압류가 중단사유가 아닙니다.","가장행위 아래 숨은 행위는 그 자체의 유효 요건을 갖추면 유효하다. 증여를 매매로 가장한 경우 내면적으로 의욕한 증여계약은 유효하다":"가장행위 아래 숨은 행위는 그 자체의 요건을 갖추면 유효해서 증여를 매매로 가장해도 증여계약은 유효합니다.","가정법원은 6개월 이상 공시최고를 하고, 그 기간 내에 생사의 신고가 없으면 실종을 선고하여야 한다":"공시최고를 6개월 이상 거친 뒤 신고가 없으면 가정법원이 실종선고를 합니다.","각 당사자가 언제든지 해지할 수 있다. 부득이한 사유 없이 상대방의 불리한 시기에 해지한 때 손해를 배상하여야 한다(불리한 시기에도 해지는 가능)":"각 당사자는 언제든 위임을 해지할 수 있고 부득이한 사유 없이 상대방에게 불리한 때 해지하면 손해를 배상해야 해요.","각 당사자가 해제할 수 있다. 이미 이행한 부분에는 영향이 없다":"서면에 의하지 않은 증여는 각 당사자가 해제할 수 있지만 이미 이행한 부분에는 영향이 없어요.","각 당사자는 상대방에 대하여 원상회복의무가 있다. 제3자의 권리를 해하지 못한다. 반환할 금전에는 받은 날부터 이자를 가하여야 한다":"해제하면 각자 원상회복해야 하고 제3자의 권리는 해치지 못하며 돌려줄 돈에는 받은 날부터 이자를 더합니다.","각 당사자는 언제든지 상대방에 대하여 전세권의 소멸을 통고할 수 있고, 상대방이 통고를 받은 날부터 6월이 경과하면 전세권이 소멸한다":"존속기간을 약정하지 않았다면 언제든 소멸을 통고할 수 있고 상대방이 통고받은 날부터 6월이 지나면 소멸합니다.","각 사원의 결의권은 평등하고 서면이나 대리인으로 행사한다 · 정관에 다른 규정이 있으면 적용하지 않는다 · 관계사항을 의결하는 사원은 결의권이 없다":"각 사원의 결의권은 평등하고 서면이나 대리인으로 행사할 수 있으며, 의결 관계 당사자인 사원은 결의권이 없어요.","각자가 본인을 대리한다. 법률 또는 수권행위에 다른 정함이 있으면 그에 따른다":"대리인이 여럿이면 각자 본인을 대리하며 법률이나 수권행위에 다른 정함이 있으면 그에 따릅니다.","간이변제충당 허가가 있으면 유치물의 소유권은 허가(확정)에 의해 이전하며 등기를 하여야 소유권이 이전되는 것이 아니다":"간이변제충당 허가가 확정되면 유치물 소유권은 허가에 의해 이전하며 등기를 해야 이전되는 것은 아닙니다.","간접점유자도 점유보호 청구권을 행사할 수 있다. 점유자가 침탈당한 경우 간접점유자는 점유자에게 반환할 것을 청구하거나 점유자가 받을 수 없거나 원하지 않으면 자기에게 반환할 것을 청구할 수 있다":"간접점유자도 점유보호 청구권을 행사할 수 있고 침탈당했으면 점유자에게 반환하라고 하거나 받지 않으면 자기에게 반환하라고 청구해요.","감사는 정관 또는 총회의 결의로 둘 수 있는 임의기관이다 · 사단법인은 감사를 두지 않을 수 있다 · 이사는 주무관청의 허가 없이 사임할 수 있다":"감사는 정관 또는 총회 결의로 둘 수 있는 임의기관이며, 이사는 허가 없이 사임할 수 있습니다.","감사의 성명ㆍ주소는 등기사항이 아니다 · 이사의 성명과 주소는 등기사항이다":"이사의 성명과 주소는 등기사항이지만 감사는 등기사항이 아닙니다.","감사의 직무 4가지다 · ① 재산상황 감사 ② 이사의 업무집행 상황 감사 · ③ 부정ㆍ불비 발견 시 총회·주무관청 보고 ④ 총회 소집":"감사는 재산상황과 이사의 업무집행을 감사하고, 부정이 있으면 총회나 주무관청에 보고하며 총회를 소집해요.","강박에 의하여 의사결정의 자유가 완전히 박탈된 상태에서 이루어진 의사표시는 무효다(취소 아님)":"강박으로 의사결정의 자유가 완전히 박탈된 상태의 의사표시는 취소가 아니라 무효예요.","강박에 의하여 증여를 한 경우는 진의 아닌 의사표시가 아니다(증여의 의사가 있고 강박은 취소 사유)":"강박으로 증여한 경우는 증여 의사가 있으므로 진의 아닌 의사표시가 아니고 취소 사유예요.","강박에 의한 의사표시를 취소한 경우에도 같다":"강박에 의한 의사표시를 취소한 경우에도 두 청구권이 경합해 병존해요.","강박이 되려면 해악의 고지가 있어야 한다. 해악의 고지 없이 단지 각서에 서명ㆍ날인할 것을 강력히 요구한 것만으로는 강박이 아니다":"강박이 되려면 해악의 고지가 있어야 하며, 서명·날인을 강력히 요구한 것만으로는 강박이 아닙니다.","강제집행을 면할 목적의 허위 근저당권설정(통정허위표시로 무효)":"강제집행을 면하려는 허위 근저당권설정은 통정허위표시로 무효이지 반사회질서가 아닙니다.","강행규정이므로 정관 또는 청산절차 위반 처분은 무효다(특별한 사정 제외) · 사단법인의 잔여재산 처분은 총회 결의가 필요하다 · 청산인에는 이사 규정을 준용한다(제58조 제2항, 제59조~제62조, 제64조, 제65조, 제70조)":"잔여재산 처분 규정은 강행규정이어서 정관이나 청산절차를 어긴 처분은 무효이고, 사단법인은 총회 결의가 필요해요.","강행법규 위반으로 무효임을 알면서 법률행위를 한 자가 그 무효를 주장하는 것은 특별한 사정이 없는 한 신의칙에 반하지 않는다":"강행법규 위반으로 무효임을 알고 법률행위를 한 사람의 무효 주장은 특별한 사정이 없으면 신의칙에 어긋나지 않습니다.","강행법규 위반을 이유로 하면 특별한 사정이 없는 한 신의칙에 반하지 않는다":"강행법규 위반을 이유로 한 무효 주장은 특별한 사정이 없는 한 신의칙에 어긋나지 않아요.","건물 기타 공작물의 소유 등을 목적으로 한 토지임차인이 적법하게 토지를 전대한 경우, 임대차 및 전대차의 기간이 동시에 만료되고 지상시설이 현존하면 전차인은 임대인에게 전전대차와 동일한 조건으로 임대할 것을 청구할 수 있다. 임대인이 원하지 않으면 제283조 제2항을 준용한다. 건물 전차인에게는 이 청구권이 없다":"적법한 토지 전차인은 임대차·전대차가 동시에 만료되고 지상시설이 있으면 같은 조건의 임대를 청구할 수 있으나 건물 전차인에게는 없습니다.","건물 기타 공작물의 소유 또는 식목·채염·목축을 목적으로 한 토지임대차의 기간 만료 시 건물·수목 기타 지상시설이 현존한 때 제283조를 준용한다(지상물매수청구권은 형성권)":"건물 소유 등을 목적으로 한 토지임대차가 만료됐을 때 지상시설이 있으면 갱신 청구와 지상물매수청구를 할 수 있고 매수청구권은 형성권이에요.","건물 기타 공작물의 임대차에서 차임연체액이 2기의 차임액에 달하는 때 임대인은 계약을 해지할 수 있다. 건물 기타 공작물의 소유 또는 식목·채염·목축 목적의 토지임대차에도 준용한다":"건물 등의 임대차에서 차임연체액이 2기의 차임액에 이르면 임대인이 해지할 수 있고 건물 소유 등 목적의 토지임대차에도 준용합니다.","건물 기타 공작물의 임차인이 사용의 편익을 위하여 임대인의 동의를 얻어 부속한 물건이나 임대인으로부터 매수한 부속물에 대하여 임대차 종료 시 매수를 청구할 수 있다. 토지임차인에게는 지상물매수청구권이 있고 부속물매수청구권은 건물 임차인의 권리다":"건물 임차인은 동의를 얻어 부속한 물건에 대해 부속물매수청구권이 있고 토지임차인에게는 지상물매수청구권이 있어요.","건물 소유를 목적으로 한 토지임대차는 등기하지 않았어도 임차인이 지상건물을 등기한 때 제3자에 대하여 효력이 생긴다. 건물이 임대차기간 만료 전에 멸실·후폐하면 효력을 잃는다":"건물 소유 목적 토지임대차는 임차인이 지상건물을 등기하면 제3자에게 효력이 생기고 건물이 멸실·후폐되면 효력을 잃습니다.","건물소유자가 건물의 소유를 통해 타인 소유 토지 전부를 불법점유하는 경우 토지소유자는 건물소유자에게 건물철거를 청구할 수 있다":"건물소유자가 타인 토지 전부를 건물로 불법점유하면 토지소유자는 건물철거를 청구할 수 있어요.","건물에 대하여 유치권을 행사하는 자는 건물의 부지를 점유하는 자에 해당하지 않는다":"건물에 대해 유치권을 행사하는 사람은 그 건물의 부지를 점유하는 자로 보지 않습니다.","건물에 대한 저당권의 효력은 특별한 사정이 없는 한 그 건물의 소유를 목적으로 하는 지상권에도 미친다":"건물 저당권의 효력은 특별한 사정이 없으면 그 건물 소유를 위한 지상권에도 미칩니다.","건물은 토지와 별개의 독립한 부동산이다(동산이 아니다). 민법이 명문으로 규정한 것도 아니다(토지의 정착물이되 독립 부동산으로 해석)":"건물은 토지와 별개의 독립한 부동산이며 민법이 명문으로 정한 것이 아니라 정착물이되 독립 부동산으로 해석합니다.","건물을 공동으로 상속한 상속인들의 건물철거의무, 자동차를 공유하는 매도인들의 매수인에 대한 자동차인도의무, 임대목적물을 공유하는 공동임대인의 보증금반환채무, 공유 토지에 수목이 부합되어 이익을 얻은 토지공유자들의 제3자에 대한 부당이득반환채무":"공동상속인의 건물철거의무, 공유 자동차 매도인들의 인도의무 등이 불가분채무의 예예요.","건물을 사용함으로써 얻는 이득은 그 건물의 과실에 준하는 것으로 본다":"건물을 사용해 얻는 이득은 법적으로 그 건물에서 나오는 과실과 비슷하게 취급합니다.","건물의 개수는 공부상의 등록이 아니라 사회통념에 따라 소유자의 의사 등 제반 사정을 참작하여 결정한다":"건물의 개수는 공부 등록이 아니라 사회통념과 소유자 의사 등을 참작해 정해요.","건물의 신축, 유실물의 습득(제253조), 무주물의 선점(제252조), 취득시효 완성 후 등기에 의한 소유권 취득, 선의취득":"건물 신축, 유실물 습득, 무주물 선점, 취득시효 완성 후 등기, 선의취득은 원시취득의 예입니다.","건물의 임차인이 건물의 소부분을 타인에게 사용하게 하는 경우 제629조~제631조는 적용되지 않는다":"건물 임차인이 소부분을 타인에게 사용하게 하는 경우에는 양도·전대에 관한 규정이 적용되지 않아요.","건물이 완공되기 전에는 건물에 관한 소유권이전등기청구권의 시효가 진행하지 않는다":"건물이 지어지기 전에는 그 건물의 이전등기청구권에 관해 시효가 흐르지 않습니다.","건물 전세권설정자가 존속기간 만료 전 6월부터 1월까지 사이에 갱신거절 통지 또는 조건 변경 통지를 하지 않으면 만료된 때에 전전세권과 동일한 조건으로 다시 전세권을 설정한 것으로 본다. 이 경우 존속기간은 정함이 없는 것으로 본다. 법정갱신에는 등기를 요하지 않는다":"건물 전세권은 만료 6월~1월 사이에 거절 통지가 없으면 같은 조건으로 다시 설정된 것으로 보고 기간은 정함이 없으며 등기는 필요 없습니다.","격지자 간의 계약은 승낙의 통지를 발송한 때에 성립한다(도달 시가 아님)":"격지자 간 계약은 승낙의 통지를 발송한 때 성립하며 도달한 때가 아닙니다.","경계나 그 근방에서 담 또는 건물을 축조ㆍ수선하기 위하여 필요한 범위 내에서 이웃 토지의 사용을 청구할 수 있다. 이웃 사람의 승낙이 없으면 주거에 들어가지 못한다. 손해가 있으면 보상을 청구할 수 있다":"담이나 건물을 짓고 고치려면 경계 근방의 이웃 토지 사용을 청구할 수 있고 손해가 생기면 보상해 줍니다.","경계로부터 2미터 이내의 거리에서 이웃 주택의 내부를 관망할 수 있는 창이나 마루를 설치하는 경우 적당한 차면시설을 하여야 한다":"경계에서 2미터 이내에 이웃 주택 내부를 볼 수 있는 창이나 마루를 설치하면 차면시설을 해야 해요.","경계표ㆍ담ㆍ구거 등은 상린자의 공유로 추정한다. 상린자 일방의 단독비용으로 설치되었거나 담이 건물의 일부인 경우는 제외. 이 공유물에는 분할청구 금지 기간 규정이 적용되지 않고 분할을 청구하지 못한다":"경계표·담·구거 등은 상린자의 공유로 추정하며 이 공유물은 분할을 청구할 수 없어요.","경락인은 채무자에게 계약의 해제 또는 대금감액을 청구할 수 있다. 채무자가 자력이 없으면 대금의 배당을 받은 채권자에게 반환을 청구할 수 있다. 채무자가 흠결을 알고 고지하지 않았거나 채권자가 알고 경매를 청구한 때 손해배상을 청구할 수 있다. 하자담보책임 규정은 경매에는 적용하지 않는다":"경락인은 채무자에게 해제·대금감액을 청구하고 무자력이면 배당받은 채권자에게 반환을 청구하지만 하자담보책임은 경매에 적용되지 않습니다.","경매절차(공경매)에서는 매각대금이 시가에 비해 현저히 저렴해도 제104조가 적용되지 않는다":"경매절차에서는 매각대금이 시가보다 현저히 싸도 제104조가 적용되지 않아요.","계속적 보증계약의 보증인은 주채무가 확정된 이후에는 사정변경을 이유로 보증계약을 해지할 수 없다":"보증 대상 주채무가 정해진 뒤에는 사정이 바뀌었다고 계속적 보증을 해지할 수 없습니다.","계약명의신탁에서 명의신탁자가 부동산을 점유하는 경우 특별한 사정이 없는 한 타주점유다":"계약명의신탁에서 점유하는 명의신탁자는 특별한 사정이 없으면 자기 것으로 지배하는 자주점유자가 되지 못합니다.","계약에 의하여 당사자 일방이 제3자에게 이행할 것을 약정한 때 제3자는 채무자에게 직접 그 이행을 청구할 수 있다. 제3자의 권리는 제3자가 채무자에 대하여 계약의 이익을 받을 의사를 표시한 때 생긴다":"제3자를 위한 계약에서 제3자는 채무자에게 직접 이행을 청구할 수 있고 권리는 수익 의사를 표시한 때 생깁니다.","계약으로 자기 비용으로 공작물의 설치ㆍ수선 의무를 부담한 때 특별승계인도 그 의무를 부담한다. 위기(委棄)로 부담을 면할 수 있다. 공작물을 지역권 행사를 방해하지 않는 범위에서 사용할 수 있고 수익 비율로 비용을 분담한다":"계약으로 공작물 설치·수선 의무를 진 승역지 소유자의 특별승계인도 그 의무를 지며 위기로 부담을 면할 수 있어요.","계약은 장래에 대하여 효력을 잃는다":"해지는 계약이 장래에 대해서만 효력을 잃게 하는 것이에요.","계약을 채무불이행으로 해제하더라도 별도로 손해배상을 청구할 수 있다":"채무불이행으로 계약을 해제해도 별도로 손해배상을 청구할 수 있어요.","계약의 성질 또는 당사자의 의사표시에 의하여 일정한 시일 또는 기간 내에 이행하지 아니하면 계약의 목적을 달성할 수 없는 경우 최고 없이 해제할 수 있다":"정기행위는 일정 시일 안에 이행하지 않으면 목적을 달성할 수 없는 계약이라 최고 없이 해제할 수 있습니다.","계약의 청약은 이를 철회하지 못한다. 청약이 상대방에게 도달하여 효력이 발생하면 청약자는 임의로 철회하지 못한다":"청약이 상대방에게 도달해 효력이 생기면 청약자는 임의로 철회할 수 없습니다.","계약의 해제는 법정추인 사유가 아니다":"계약의 해제는 법정추인 사유에 포함되지 않아요.","계약의 해지ㆍ해제, 공유지분의 포기, 법인 이사의 사임":"계약의 해지·해제, 공유지분 포기, 법인 이사의 사임도 상대방 있는 단독행위예요.","계약체결에 관한 대리권을 수여받은 대리인이 취소권을 행사하려면 특별한 사정이 없는 한 취소권 행사에 관한 본인의 수권행위가 있어야 한다":"계약체결 대리권만으로 취소권을 행사하려면 취소권 행사에 관한 본인의 수권행위가 따로 있어야 해요.","계약 취소로 인한 부당이득반환청구권과 불법행위로 인한 손해배상청구권은 경합하여 병존한다":"계약을 취소하면 부당이득반환청구권과 불법행위 손해배상청구권이 동시에 성립하여 경합합니다.","고의 또는 과실로 인한 위법행위로 타인에게 손해를 가한 자는 그 손해를 배상할 책임이 있다":"고의나 과실로 위법하게 남에게 손해를 입힌 사람은 그 손해를 배상할 책임이 있습니다.","고의 또는 중대한 과실이 없으면 불이행으로 인한 모든 책임이 없다. 이자 있는 채권이라도 이자를 지급할 의무가 없다. 목적물 보관 또는 변제 비용이 증가된 때 증가액은 채권자가 부담한다":"채권자지체 중에는 채무자가 고의·중과실이 없으면 책임이 없고 이자도 줄 필요가 없으며 보관·변제 비용 증가분은 채권자가 부담해요.","고의의 불법행위로 인한 채무의 채무자는 상계로 채권자에게 대항하지 못한다. 압류금지채권을 수동채권으로 하는 상계 금지. 지급을 금지하는 명령을 받은 제3채무자는 그 후 취득한 채권에 의한 상계로 대항하지 못한다":"고의 불법행위 채무자는 상계로 대항하지 못하고 압류금지채권을 수동채권으로 한 상계와 지급금지 후 취득 채권의 상계도 금지됩니다.","고의의 불법행위자는 피해자의 부주의를 이용한 경우 과실상계를 주장할 수 없다. 과실로 가해한 공동불법행위자의 손해배상액 산정에서는 피해자의 과실을 참작한다":"고의 가해자는 피해자의 부주의를 이용했다면 과실상계를 주장 못 하고, 과실로 가해한 공동불법행위자는 피해자 과실을 참작받습니다.","고지소유자는 침수지 건조 또는 가용ㆍ농ㆍ공업용 여수를 소통하기 위하여 공로ㆍ공류 또는 하수도에 달하기까지 저지에 물을 통과하게 할 수 있다(손해 최소 + 보상)":"고지소유자는 침수지 건조나 여수 소통을 위해 공로·공류·하수도에 이르기까지 저지에 물을 통과시킬 수 있고 손해는 보상합니다.","고지의무가 없다면 침묵 등 부작위는 기망행위가 아니다. 목적물의 시가를 묵비하여 알리지 않은 것은 특별한 사정이 없는 한 기망이 아니다":"고지의무가 없다면 침묵 같은 부작위는 기망이 아니며 시가를 알리지 않은 것도 특별한 사정이 없으면 기망이 아닙니다.","공과부담의 증감 기타 경제사정의 변동으로 약정한 차임이 상당하지 않게 된 때 장래에 대한 차임의 증감을 청구할 수 있다":"공과부담이나 경제사정이 바뀌어 차임이 상당하지 않게 되면 장래에 대해 증감을 청구할 수 있습니다.","공동불법행위자는 피해자에 대하여 자기의 고의·과실이 없음을 증명하여 책임을 면할 수 없다(책임 발생 요건은 피해자가 증명)":"공동불법행위자가 자기 고의·과실이 없다고 증명해 면책되려 할 수 없고, 책임 요건은 피해자가 증명합니다.","공동불법행위자의 책임은 연대(부진정연대)이므로 과실비율에 따른 일부(예: 100만원)만 부담하는 것이 아니라 피해자의 과실을 참작한 책임 범위 전액을 부담한다":"공동불법행위자는 부진정연대로 책임져서 자기 과실비율만이 아니라 피해자 과실을 참작한 책임 범위 전액을 부담해요.","공동불법행위자 중 1인이 변제한 때 변제 시부터 다른 공동불법행위자에 대한 구상권의 소멸시효가 기산한다":"공동불법행위자 중 한 명이 변제하면 그때부터 다른 공동불법행위자에 대한 구상권의 소멸시효가 시작됩니다.","공동임차인의 임대인에 대한 임차물반환의무(기출 정답상 불가분채무에 해당하지 않는 것으로 출제된 것)":"공동임차인의 임차물반환의무는 불가분채무에 해당하지 않는 예로 제시됩니다.","공로와의 사이에 용도에 필요한 통로가 없는 경우 주위토지를 통행하거나 통로를 개설할 수 있다. 손해가 가장 적은 장소와 방법을 선택하고 통행지 소유자의 손해를 보상하여야 한다":"공로와 통하는 통로가 없으면 손해가 가장 적은 곳으로 주위토지를 통행할 수 있고 통행지 소유자의 손해를 보상해야 해요.","공부(公簿)상 1필로 등록된 토지는 특별한 사정이 없는 한 현실의 경계에 관계없이 지적공부상의 경계에 의해 소유권의 범위가 확정된다":"지적공부에 1필로 등록된 토지는 현실 경계와 상관없이 공부상 경계로 소유권 범위가 정해집니다.","공유관계가 존속하는 한 공유물분할청구권은 독립하여 소멸시효에 걸리지 않는다":"공유가 이어지는 동안은 분할청구권이 따로 시효로 소멸하지 않습니다.","공유물분할의 조정절차에서 협의에 의하여 조정조서가 작성되더라도 그 즉시 공유관계가 소멸하지는 않는다":"분할 조정절차에서 조정조서가 작성되어도 그 즉시 공유관계가 소멸하지는 않아요.","공유물을 단독으로 점유하는 소수지분권자는 공유물관리를 위한 과반수지분권자의 공유물 인도청구를 공유물의 사용ㆍ수익권으로 거부할 수 없다":"공유물을 단독 점유하는 소수지분권자는 과반수지분권자의 인도청구를 사용·수익권으로 거부할 수 없습니다.","공유물의 처분ㆍ변경은 다른 공유자의 동의가 있어야 한다. 관리에 관한 사항은 지분의 과반수로 결정한다. 보존행위는 각자 할 수 있다":"공유물의 처분·변경은 다른 공유자 동의가, 관리는 지분 과반수가 필요하고 보존행위는 각자 할 수 있어요.","공유자 1인이 공유물을 무단 임대하고 보증금을 수령한 경우 다른 공유자는 지분비율에 상응하는 임료 상당 부당이득의 반환을 청구할 수 있으나 보증금 자체의 지분 비율 반환을 청구할 수 있는 것은 아니다":"공유자가 무단 임대해 보증금을 받으면 다른 공유자는 지분만큼의 임료 상당 이득만 청구하고 보증금 자체는 청구하지 못합니다.","공유자가 지분을 포기하거나 상속인 없이 사망한 때 그 지분은 다른 공유자에게 각 지분의 비율로 귀속한다. 부동산은 지분포기에 따른 다른 공유자 앞 이전등기를 하여야 귀속된다":"공유자가 지분을 포기하거나 상속인 없이 죽으면 지분이 다른 공유자에게 귀속되고 부동산은 이전등기를 해야 귀속됩니다.","공유자는 공유물의 분할을 청구할 수 있다. 5년 내의 기간으로 분할하지 않을 것을 약정할 수 있고, 갱신한 때 그 기간은 갱신한 날부터 5년을 넘지 못한다. 제215조, 제239조의 공유물에는 적용하지 않는다":"공유자는 분할을 청구할 수 있고 5년 내 기간으로 분할하지 않기로 약정할 수 있으며 갱신해도 갱신일부터 5년을 넘지 못합니다.","공유자는 그 지분을 처분할 수 있고(다른 공유자의 동의 불요) 공유물 전부를 지분의 비율로 사용ㆍ수익할 수 있다. 지분을 담보로 제공하는 데도 다른 공유자의 동의가 필요하지 않다":"공유자는 다른 공유자의 동의 없이 지분을 처분하거나 담보로 제공하고 전부를 지분 비율로 사용·수익할 수 있습니다.","공유자는 다른 공유자가 분할로 취득한 물건에 대하여 지분 비율로 매도인과 동일한 담보책임이 있다":"공유자는 분할로 다른 공유자가 취득한 물건에 대해 지분 비율로 매도인과 같은 담보책임을 집니다.","공유자들이 공유물의 무단점유자에게 가지는 차임 상당의 부당이득반환채권은 특별한 사정이 없는 한 가분채권이다(지분 비율로 각자 행사)":"무단점유자에 대한 차임 상당 부당이득반환채권은 특별한 사정이 없으면 가분채권이라 지분 비율로 각자 행사해요.","공유자 중 1인이 다른 공유자의 동의 없이 공유 토지의 특정부분을 매도하여 타인 명의로 이전등기가 마쳐졌다면 그 등기는 공유자의 지분 범위에서 유효하다":"공유자 한 명이 동의 없이 특정 부분을 팔아 이전등기가 되어도 그 등기는 공유자의 지분 범위에서 유효합니다.","공유자 중 1인이 다른 공유자의 동의 없이 공유 토지의 특정 부분을 매도하여 타인 명의로 이전등기를 마친 경우, 그 등기는 그 공유자의 지분 범위에서는 유효하다(전부 무효 아님)":"공유자 한 명이 동의 없이 특정 부분을 팔고 이전등기를 마쳤다면 그 등기는 그 공유자의 지분 범위에서는 유효합니다.","공유자 중 1인이 협의 없이 공유물 전부를 독점 점유ㆍ사용하는 경우 다른 공유자는 자신의 공유지분권에 기초하여 방해배제를 청구할 수 있고 지분에 상응하는 부당이득반환을 청구할 수 있다. 보존행위로서 인도를 청구할 수는 없다":"공유자 한 명의 독점에 대해 다른 공유자는 방해배제와 지분만큼의 부당이득 반환을 청구할 수 있으나 인도 청구는 못 합니다.","공작물 소유자는 자기에게 과실이 없음을 증명하여도 책임을 면하지 못한다(공작물 임차인에 대한 소유자의 책임이 이에 해당)":"공작물 소유자는 자기에게 과실이 없음을 증명해도 책임을 면하지 못하는 무과실책임을 집니다.","공작물의 설치 또는 보존의 하자로 타인에게 손해를 가한 때 공작물 점유자가 배상한다. 점유자가 손해의 방지에 필요한 주의를 해태하지 않은 때 소유자가 배상한다(소유자는 무과실책임). 수목의 재식·보존의 하자에도 준용. 점유자·소유자는 손해의 원인에 책임 있는 자에게 구상할 수 있다":"공작물의 하자로 손해가 나면 점유자가 배상하고 점유자가 주의를 다했으면 소유자가 책임지며 소유자는 무과실책임이고 수목에도 준용합니다.","공탁은 채무이행지의 공탁소에 하고, 공탁자는 지체없이 채권자에게 공탁통지를 하여야 한다":"채무를 이행할 곳의 공탁소에 공탁하고 공탁한 사람은 채권자에게 바로 알려 주어야 합니다.","공통 해산사유는 존립기간 만료, 목적의 달성 또는 불능, 파산이다 · 정관 사유 발생, 설립허가 취소, 사단법인은 사원 소멸·총회 결의 · 해산결의는 총사원 4분의 3 이상의 동의가 필요하다":"존립기간 만료, 목적의 달성·불능, 파산은 해산사유이고, 사단법인의 해산결의에는 총사원 4분의 3 이상의 동의가 필요해요.","과반수 지분의 공유자로부터 공유물의 사용·수익을 허락받아 점유하고 있는 제3자에 대하여 소수지분권자는 점유로 인한 부당이득반환을 청구할 수 없다":"과반수 지분권자에게서 사용·수익을 허락받은 제3자에 대해 소수지분권자는 부당이득반환을 청구할 수 없습니다.","과반수 지분의 공유자로부터 사용ㆍ수익을 허락받은 제3자의 점유에 대해 소수지분권자는 부당이득반환을 청구할 수 없다":"과반수 지분권자가 사용을 허락한 제3자에 대해서는 소수지분권자가 부당이득을 청구할 수 없습니다.","과실로 인하여 스스로 심신상실을 초래하고 그 상태에서 타인에게 위법하게 손해를 가한 자는 손해배상책임을 진다":"과실로 스스로 심신상실 상태를 만들어 그 상태에서 남에게 손해를 입혔다면 배상해야 합니다.","과실 없이 변제 기타 출재로 주채무를 소멸시킨 때 구상권이 있고, 면책된 날 이후의 법정이자 및 피할 수 없는 비용 기타 손해배상을 포함한다":"과실 없이 변제해 주채무를 소멸시킨 수탁보증인은 구상권이 있고 면책일 이후의 법정이자와 비용을 포함합니다.","과징금: 명의신탁자에게 부동산 가액의 100분의 30의 범위에서 부과한다. 벌칙: 명의신탁자는 5년 이하 징역 또는 2억원 이하 벌금, 명의수탁자는 3년 이하 징역 또는 1억원 이하 벌금":"과징금은 부동산 가액의 100분의 30 범위에서 명의신탁자에게 부과하고, 명의신탁자는 5년 이하 징역 또는 2억원 이하 벌금입니다.","관리자의 비용상환청구권: 본인을 위하여 필요비 또는 유익비를 지출한 때 본인에 대하여 상환을 청구할 수 있다. 본인의 의사에 반하여 관리한 때에는 본인의 현존이익의 한도에서 준용한다":"관리자는 본인을 위해 지출한 필요비와 유익비를 청구할 수 있고 본인 의사에 반하면 본인의 현존이익 한도에서 청구합니다.","관습법으로 물권이 창설될 수 있다(분묘기지권, 관습법상 법정지상권 등)":"분묘기지권이나 관습법상 법정지상권처럼 관습법으로 물권이 만들어질 수 있습니다.","관습법이 없으면 조리에 의한다":"관습법도 없다면 마지막으로 사물의 이치인 조리를 기준으로 삼아요.","교환은 당사자 쌍방이 금전 이외의 재산권을 상호이전할 것을 약정함으로써 효력이 생긴다. 금전의 보충지급이 있으면 그 금전에 매매대금 규정을 준용한다":"교환은 쌍방이 금전 이외의 재산권을 서로 이전하기로 약정하여 성립하고 보충지급 금전에는 매매대금 규정을 준용합니다.","구거 기타 수류지의 소유자는 대안의 토지가 타인 소유이면 수로나 수류의 폭을 변경하지 못한다. 양안이 수류지 소유자의 소유이면 변경할 수 있으나 하류는 자연의 수로와 일치하여야 한다":"수류지 소유자는 대안 토지가 타인 소유이면 수로나 폭을 바꾸지 못하고, 양안이 자기 소유면 바꿀 수 있으나 하류는 자연의 수로와 같아야 합니다.","구분건물이 물리적으로 완성되기 전이라도 건축허가 신청 등으로 장래 신축되는 건물을 구분건물로 하겠다는 구분의사가 객관적으로 표시되면 구분행위의 존재를 인정할 수 있다":"구분건물이 완성되기 전이라도 건축허가 신청 등으로 구분의사가 객관적으로 표시되면 구분행위의 존재를 인정합니다.","구분소유적 공유의 성립을 주장하는 자는 구분소유 약정의 대상이 되는 토지의 위치와 면적을 모두 증명하여야 한다":"구분소유적 공유를 주장하려면 구분소유 약정 대상 토지의 위치와 면적을 모두 증명해야 해요.","국가의 민법상 불법행위책임과 국가배상법상 배상책임은 경합하여 병존하는 것이 아니다":"국가책임은 민법과 국가배상법이 겹치는 병존 관계가 아니라 국가배상법이 적용되는 관계로 봅니다.","국립공원의 입장료는 토지의 사용대가가 아니므로 법정과실이 아니다":"공원 입장료는 토지 사용의 대가가 아니라서 법정과실에 해당하지 않습니다.","궁박ㆍ경솔ㆍ무경험은 법률행위 당시를 기준으로 판단한다":"궁박·경솔·무경험은 법률행위를 하던 당시를 기준으로 판단합니다.","궁박에는 경제적 원인뿐 아니라 정신적ㆍ심리적 원인에 의한 것도 포함될 수 있다":"궁박은 경제적 곤궁만이 아니라 정신적·심리적 곤경에서도 인정될 수 있습니다.","권리가 자기에게 속하지 않음을 모르고 판 경우: 이전할 수 없는 때 손해를 배상하고 계약을 해제할 수 있다. 매수인이 악의면 매도인은 이전할 수 없음을 통지하고 계약을 해제할 수 있다":"자기 소유가 아님을 모르고 판 선의의 매도인은 이전할 수 없으면 손해를 배상하고 해제당하며, 매수인이 악의이면 통지하고 해제할 수 있습니다.","권리남용이라고 해서 그 권리가 언제나 소멸하는 것은 아니다":"권리남용이 인정되어도 그 권리가 늘 사라지는 것은 아닙니다.","권리능력은 법률에 좇아 정관으로 정한 목적의 범위 내이다 · 법인의 주소는 주된 사무소의 소재지에 있는 것으로 한다":"법인의 권리능력은 정관으로 정한 목적 범위 안이며 주소는 주된 사무소 소재지로 봅니다.","권리의 객체는 물건에 한정되지 않는다. 사람은 재산권의 객체가 될 수 없으나 사람의 일정한 행위는 재산권(채권)의 객체가 될 수 있다":"권리의 객체는 물건에 한정되지 않아서 사람의 행위도 채권의 객체가 될 수 있지만 사람 자체는 재산권의 객체가 아닙니다.","권리자의 일방적 의사표시로 법률관계를 발생ㆍ변경ㆍ소멸시킨다":"형성권은 권리자의 일방적 의사표시만으로 법률관계를 생기게 하거나 바꾸거나 없애는 권리예요.","그 권한 내에서 본인(대리인이 아님)을 대리한다. 본인이나 제3자에 대하여 대리인과 동일한 권리의무가 있다":"복대리인은 그 권한 안에서 대리인이 아닌 본인을 대리하며 본인·제3자에게 대리인과 같은 권리의무가 있습니다.","그 담보할 채무의 최고액만을 정하고 채무의 확정을 장래에 보류하여 설정할 수 있다. 확정될 때까지의 채무의 소멸 또는 이전은 저당권에 영향을 미치지 않는다. 이자는 최고액 중에 산입한 것으로 본다":"근저당은 담보할 채무의 최고액만 정하고 채무 확정은 장래에 미루며, 이자는 최고액 안에 든 것으로 봅니다.","그 사실의 발생이 불가능하게 된 때에도 기한이 도래한 것으로 본다":"그 사실이 일어날 수 없게 된 때에도 기한이 도래한 것으로 봅니다.","그 상태에서 한 종교법인의 주지임명행위는 반사회질서가 아니다":"전통사찰 주지직 거래를 묵인한 상태에서 이뤄진 주지임명 자체는 반사회질서 행위가 아닙니다.","그 의사에 의한다(소급 특약은 유효)":"그 소급 특약은 당사자의 의사에 따라 유효해요.","근저당권설정약정에 의한 근저당권설정등기청구권은 피담보채권과 별개로 소멸시효에 걸린다":"근저당권설정등기청구권은 피담보채권과 별개로 소멸시효에 걸립니다.","근저당권 설정 후 피담보채권 확정 전에 설정자와 근저당권자의 합의로 채무자를 추가하는 데는 이해관계인의 승낙이 필요하지 않다":"근저당권의 채무자를 추가할 때 이해관계인의 승낙은 필요하지 않고 설정자와 근저당권자의 합의로 됩니다.","근저당권 실행을 위한 경매에 의한 소유권 취득, 금원을 대여하면서 채무자 소유 건물에 저당권을 설정받은 경우(설정적 승계)":"근저당 실행 경매로 소유권을 얻거나 저당권을 설정받는 것은 설정적 승계취득이지 원시취득이 아닙니다.","금전으로 가액을 산정할 수 없는 것이라도 채권의 목적으로 할 수 있다":"금전으로 가액을 산정할 수 없는 급부도 채권의 목적이 될 수 있어요.","금전채무의 이행지체로 발생하는 지연손해금, 1년 이내의 정기로 지급하기로 한 것이 아닌 이자채권":"지연손해금과 정기 지급이 아닌 이자채권은 단기시효 대상이 아니라서 일반 시효를 따릅니다.","급부와 반대급부가 현저히 균형을 잃었다고 하여 궁박ㆍ경솔ㆍ무경험이 추정되는 것은 아니다":"급부가 현저히 불균형해도 궁박·경솔·무경험이 추정되지는 않아요.","급부와 반대급부 사이의 현저한 불균형은 객관적 가치를 기준으로 판단한다(당사자의 주관적 가치 아님)":"급부와 반대급부의 불균형은 당사자의 주관이 아니라 객관적 가치를 기준으로 판단합니다.","기간만료 전 6개월 내에 제한능력자에게 법정대리인이 없는 경우 그가 능력자가 되거나 법정대리인이 취임한 때부터 6개월 내에는 시효가 완성되지 않는다":"법정대리인이 없는 제한능력자는 능력자가 되거나 대리인이 취임한 때부터 6개월 내에는 시효가 완성되지 않습니다.","기망행위가 불법행위를 구성하면 사기 취소 없이도 불법행위 손해배상을 청구할 수 있다. 제3자의 사기도 같다. 취소로 인한 부당이득반환청구권과 손해배상청구권은 경합한다":"기망이 불법행위가 되면 취소 없이도 손해배상을 청구할 수 있고, 취소로 인한 부당이득반환청구권과 경합해요.","기본대리권이 될 수 있는 것: 복대리인의 권한, 등기신청의 대리권, 사실혼 부부의 일상가사대리권. 법정대리의 경우에도 권한을 넘은 표현대리 규정이 적용된다":"복대리인의 권한, 등기신청 대리권, 사실혼 부부의 일상가사대리권은 기본대리권이 되며 법정대리에도 권한 초과 표현대리가 적용됩니다.","기본재산에 부동산을 새로 편입하는 행위다 · 정관변경에 해당하여 주무관청의 허가를 얻어야 유효하다":"부동산을 기본재산에 새로 넣는 것은 정관변경이어서 허가를 받아야 효력이 있습니다.","기본재산 저당권 설정행위는 특별한 사정이 없는 한 · 정관변경을 필요로 하지 않으므로 · 주무관청의 허가도 필요하지 않다":"기본재산에 저당권을 설정하는 것은 정관변경이 아니어서 주무관청 허가도 필요하지 않습니다.","기존 건물의 소유를 목적으로 설정된 지상권은 건물이 멸실되어도 소멸하지 않는다":"지상건물의 소유를 위해 설정한 지상권은 그 건물이 사라져도 함께 없어지지 않습니다.","기존 채권(임차보증금반환채권 등)으로 전세금의 지급에 갈음할 수 있다(전세금은 현실로 수수될 필요가 없다)":"기존 채권으로 전세금 지급에 갈음할 수 있어 전세금을 현실로 주고받지 않아도 됩니다.","기한은 채무자의 이익을 위한 것으로 추정한다":"기한이 정해져 있으면 특별한 사정이 없는 한 채무자가 그동안 갚지 않아도 되는 이익을 누립니다.","기한의 이익은 포기할 수 있으나 상대방의 이익을 해하지 못한다":"기한의 이익은 스스로 포기할 수 있지만 그로 인해 상대방이 손해를 입어서는 안 됩니다.","기한의 정함이 없는 채무에 대한 이행의 최고, 시효중단을 위한 채무의 승인":"기한 없는 채무의 이행 최고와 시효중단을 위한 채무 승인은 준법률행위에 속합니다.","나대지에 저당권을 설정하면서 담보가치 유지를 위해 설정한 무상의 지상권(담보지상권)은 피담보채권이 시효로 소멸하면 소멸한다. 제3자가 대지를 무단점유한 것만으로 지상권자는 특별한 사정이 없는 한 손해배상을 청구할 수 없다":"담보지상권은 피담보채권이 시효로 소멸하면 함께 소멸하고, 제3자의 무단점유만으로 지상권자가 손해배상을 청구할 수는 없어요.","내 토지 매매계약: 처음부터 허가를 배제하는 내용의 계약이거나 당사자 쌍방이 허가신청협력의무의 이행거절 의사를 상대방에게 명백히 표시한 경우 확정적 무효다":"처음부터 허가를 배제하는 계약이나 허가신청협력의무 이행을 명백히 거절한 경우 토지거래허가구역 매매는 확정적 무효예요.","다른 연대채무자에게 통지하지 않고 면책된 경우 다른 연대채무자가 채권자에게 대항할 사유가 있었다면 부담부분에 한하여 대항할 수 있다. 통지하지 않아 다른 연대채무자가 선의로 유상의 면책행위를 하면 그의 면책행위가 유효하다":"통지 없이 면책되면 다른 연대채무자가 채권자에게 대항할 사유로 부담부분에 한해 대항할 수 있고 선의의 유상 면책행위는 유효해요.","다른 의사표시가 없으면 계약 시에 소급하여 효력이 생긴다. 제3자의 권리를 해하지 못한다":"추인하면 별다른 의사가 없는 한 계약한 때로 거슬러 올라가 효력이 생기지만 제삼자의 권리는 건드리지 못합니다.","다른 의사표시가 없으면 금전으로 배상한다":"다른 의사표시가 없으면 손해는 금전으로 배상해요.","담보가등기권리자는 선택에 따라 담보권을 실행하거나 경매를 청구할 수 있다. 우선변제는 담보가등기를 저당권으로 보고 가등기를 마친 때 설정등기가 된 것으로 본다. 경매에서 담보가등기권리는 매각으로 소멸한다":"담보가등기권리자는 담보권을 실행하거나 경매를 청구할 수 있고, 경매에서 담보가등기는 매각으로 소멸합니다.","담보책임과 동시이행: 제572조~제575조, 제580조, 제581조의 경우 제536조를 준용한다":"담보책임을 지는 경우 매도인의 의무와 매수인의 의무는 동시이행 관계로 봅니다.","당사자가 본래의 기산일과 다른 기산일을 주장하는 경우 법원은 변론주의에 따라 당사자가 주장하는 기산일을 기준으로 계산하여야 한다":"당사자가 본래와 다른 기산일을 주장하면 법원은 변론주의에 따라 그 주장한 기산일을 기준으로 계산해요.","당사자가 임의규정(선량한 풍속 기타 사회질서에 관계없는 법령 규정)과 다른 의사를 표시한 때다":"임의규정은 선량한 풍속과 무관한 규정으로, 당사자가 달리 정하면 그 의사가 우선합니다.","당사자가 조건성취의 효력을 그 성취 전에 소급하게 할 의사를 표시한 때다":"당사자가 조건 성취의 효력을 성취 전으로 소급시키겠다는 의사를 표시한 경우를 가리킵니다.","당사자가 채무의 중요한 부분을 변경하는 계약을 한 때 구채무는 경개로 소멸한다. 채무자 변경 경개는 채권자와 신채무자 간 계약으로 하되 구채무자의 의사에 반하지 못한다. 채권자 변경 경개는 확정일자 있는 증서로 하지 않으면 제3자에게 대항하지 못한다":"채무의 중요한 부분을 변경하는 계약을 하면 구채무가 경개로 소멸하고 채권자 변경 경개는 확정일자 있는 증서로 해야 제3자에게 대항합니다.","당사자 간에 동일한 내용의 청약이 상호교차된 경우 양 청약이 상대방에게 도달한 때 계약이 성립한다":"동일한 내용의 청약이 서로 교차되면 두 청약이 상대방에게 도달한 때 계약이 성립해요.","당사자는 채무불이행에 관한 손해배상액을 예정할 수 있다. 예정액이 부당히 과다한 경우 법원은 적당히 감액할 수 있다. 이행의 청구나 계약의 해제에 영향을 미치지 않는다. 위약금의 약정은 손해배상액의 예정으로 추정한다":"손해배상액을 예정할 수 있고 부당히 과다하면 법원이 감액할 수 있으며 위약금은 배상액의 예정으로 추정합니다.","당사자의 궁박, 경솔 또는 무경험으로 인하여 현저하게 공정을 잃은 법률행위는 무효로 한다":"급박한 곤궁이나 경솔, 경험 부족을 이용해 현저히 불공정하게 한 거래는 무효입니다.","당사자의 의사가 명확하지 아니한 때에 그 관습에 의한다":"당사자의 의사가 분명하지 않을 때에 한해 그 관습을 따릅니다.","당사자의 주장ㆍ증명이 없어도 법원(法院)이 직권으로 확정하여야 한다":"관습법은 당사자가 주장하거나 증명하지 않아도 재판하는 법원(法院)이 직권으로 확정해야 합니다.","당사자 일방 또는 쌍방이 그 기간 내에 해지할 권리를 보류한 때 제635조를 준용한다. 임차인이 파산선고를 받은 경우 약정기간이 있어도 임대인 또는 파산관재인은 해지통고할 수 있고 각 당사자는 손해배상을 청구하지 못한다":"기간이 있어도 해지권을 보류했거나 임차인이 파산하면 해지통고를 할 수 있으며 손해배상은 서로 청구하지 못합니다.","당사자 일방 또는 쌍방이 수인인 경우 해지·해제는 전원으로부터 또는 전원에 대하여 하여야 한다. 해제권이 당사자 1인에 대하여 소멸한 때 다른 당사자에 대하여도 소멸한다":"당사자가 여럿이면 해지·해제는 전원으로부터 또는 전원에 대해 해야 하고 한 사람에게 소멸하면 다른 사람에게도 소멸해요.","당사자 일방이 상대방에게 목적물을 사용·수익하게 할 것을 약정하고 상대방이 차임을 지급할 것을 약정함으로써 효력이 생긴다":"임대차는 한쪽이 상대방에게 목적물을 사용·수익하게 하고 상대방이 차임을 지급하기로 약정하여 성립해요.","당사자 일방이 상대방에 대하여 사무의 처리를 위탁하고 상대방이 이를 승낙함으로써 효력이 생긴다":"일을 맡기고 상대방이 승낙하면 성립하며 계약서나 보수가 반드시 필요하지는 않습니다.","당사자 일방이 어느 일을 완성할 것을 약정하고 상대방이 그 일의 결과에 대하여 보수를 지급할 것을 약정함으로써 효력이 생긴다. 부대체물을 제작하여 공급하는 계약도 도급의 성질을 갖는다(제작물공급계약)":"도급은 일의 완성을 약정하고 그 결과에 대해 보수를 지급하기로 하는 계약이며 부대체물 제작공급계약도 도급의 성질을 가집니다.","당사자 일방이 재산권을 상대방에게 이전할 것을 약정하고 상대방이 대금을 지급할 것을 약정함으로써 효력이 생긴다":"매매는 한쪽이 재산권을 이전하고 상대방이 대금을 지급하기로 약정하여 성립하는 계약이에요.","당사자 한쪽의 사망이나 파산으로 종료한다. 수임인이 성년후견개시의 심판을 받은 경우에도 같다. 급박한 사정이 있으면 수임인 등은 위임인 등이 처리할 수 있을 때까지 처리를 계속한다. 종료사유는 상대방에게 통지하거나 상대방이 안 때가 아니면 대항하지 못한다":"위임은 당사자 한쪽의 사망이나 파산으로 종료하고 종료사유는 상대방에게 통지하거나 상대방이 알아야 대항할 수 있습니다.","대가관계를 상정할 수 있는 한 단독행위에도 적용될 수 있다":"대가관계를 생각할 수 있다면 단독행위에도 불공정한 법률행위 규정이 미칠 수 있습니다.","대리권 남용의 경우에도 특별한 사정이 없는 한 진의 아닌 의사표시 규정이 유추적용될 수 있다. 대리인에 의한 법률행위에서 진의 여부는 대리인을 기준으로 판단한다":"대리권 남용에도 진의 아닌 의사표시 규정이 유추적용될 수 있고, 진의 여부는 대리인을 기준으로 봅니다.","대리권 없는 자가 타인의 대리인으로 한 계약은 본인이 추인하지 아니하면 본인에 대하여 효력이 없다":"무권대리 계약은 본인이 추인하기 전에는 본인에게 효력이 없는 유동적 상태입니다.","대리권을 증명하지 못하고 본인의 추인을 받지 못한 경우 상대방의 선택에 따라 계약을 이행할 책임 또는 손해를 배상할 책임이 있다. 상대방이 대리권 없음을 알았거나 알 수 있었을 때, 또는 무권대리인이 제한능력자일 때에는 적용하지 아니한다":"대리권도 추인도 없으면 상대방 선택으로 이행이나 배상의 책임을 지되, 상대방이 악의·과실이거나 제한능력자이면 예외입니다.","대리권의 소멸은 선의의 제3자에게 대항하지 못한다. 단 제3자가 과실로 그 사실을 알지 못한 때에는 그러하지 아니하다. 법정대리의 경우에도 성립하며, 대리인이 대리권 소멸 후 복대리인을 선임해 대리행위를 하게 한 경우에도 성립할 수 있다":"대리권 소멸은 선의 제3자에게 대항하지 못하나 제3자가 과실로 몰랐다면 달라지며, 법정대리나 복대리인 선임에도 성립할 수 있습니다.","대리인에 의한 법률행위의 경우 경솔과 무경험은 대리인을 기준으로 판단한다(궁박은 본인 기준)":"대리인이 한 법률행위에서는 경솔과 무경험은 대리인을, 궁박은 본인을 기준으로 봅니다.","대리인은 행위능력자임을 요하지 않는다. 미성년자ㆍ피한정후견인도 임의대리인이 될 수 있다":"대리인은 행위능력자일 필요가 없어 미성년자나 피한정후견인도 임의대리인이 될 수 있습니다.","대리인의 권한을 넘는 행위가 범죄를 구성하는 경우에도 권한을 넘은 표현대리의 법리가 적용될 수 있다. 대리행위 자체가 강행법규 위반으로 무효이면 표현대리가 성립하지 않는다":"권한을 넘은 행위가 범죄를 이루어도 표현대리가 적용될 수 있지만, 대리행위 자체가 강행법규 위반으로 무효이면 성립하지 않습니다.","대리인이 권한 내에서 본인을 위한 것임을 표시한 의사표시는 직접 본인에게 효력이 생긴다. 대리인에게 대한 제3자의 의사표시에도 준용한다":"대리인이 권한 안에서 본인을 위한 것임을 밝히고 한 의사표시는 곧바로 본인에게 효력이 생깁니다.","대리인이 그 권한 외의 법률행위를 한 경우 제3자가 그 권한이 있다고 믿을 만한 정당한 이유가 있는 때 본인은 책임이 있다":"대리인이 권한을 넘어 행위해도 상대가 권한이 있다고 믿을 정당한 이유가 있으면 본인이 책임집니다.","대리인이 취소권을 행사하려면 특별한 사정이 없는 한 취소권 행사에 관한 본인의 수권행위가 있어야 한다. 대리권만으로는 부족하다":"대리인이 취소권을 행사하려면 대리권만으로는 부족하고 취소권 행사에 관한 본인의 수권행위가 따로 있어야 합니다.","대여금 영수권한만을 위임받은 대리인이 그 채무의 일부를 면제하려면 본인의 특별수권이 필요하다":"대여금 영수만 맡은 대리인이 채무 일부를 면제해 주려면 본인의 특별한 수권이 있어야 합니다.","대지와 건물이 동일한 소유자에 속하는 경우 건물에 전세권을 설정한 때 대지 소유권의 특별승계인은 전세권설정자에 대하여 지상권을 설정한 것으로 본다. 지료는 당사자 청구에 의하여 법원이 정한다. 대지소유자는 대지를 임대하거나 지상권ㆍ전세권을 설정하지 못한다":"대지와 건물이 같은 소유자일 때 건물에 전세권을 설정하면 대지 소유권 승계인은 지상권을 설정한 것으로 봅니다.","대표권 없는 이사는 대표기관이 아니다 · 그의 행위로 법인의 불법행위가 성립하지 않는다":"대표권 없는 이사의 행위는 대표기관의 행위가 아니어서 법인의 불법행위가 되지 않습니다.","대표권 제한은 정관에 기재해야 효력이 있다 · 기재해도 등기하지 않으면 제3자에게 대항하지 못한다 · 비법인사단은 상대방이 선의이며 과실이 없으면 거래가 유효하다(제60조 유추적용 안 됨)":"대표권 제한은 정관에 적어야 효력이 있고 등기하지 않으면 제3자에게 대항할 수 없어요.","도급인은 수급인이 일에 관하여 제3자에게 가한 손해를 배상할 책임이 없다. 단 도급 또는 지시에 관하여 도급인에게 중대한 과실이 있는 때에는 책임이 있다":"도급인은 수급인이 제3자에게 가한 손해를 배상할 책임이 없지만 도급이나 지시에 중대한 과실이 있으면 책임이 있어요.","도급인이 공사대금을 지급하기 곤란한 현저한 사유가 있으면 수급인은 동시이행의 항변권(제536조 제2항)에 의하여 공사 완공의무를 거절할 수 있다":"도급인이 대금을 지급하기 곤란한 현저한 사유가 있으면 수급인은 동시이행 항변권으로 완공의무를 거절할 수 있습니다.","도급인이 제공한 재료의 성질 또는 지시에 기인한 하자는 면책된다. 단 수급인이 부적당함을 알고 고지하지 않은 때는 책임":"도급인이 제공한 재료의 성질이나 지시에 기인한 하자는 수급인이 면책되지만 부적당함을 알고 알리지 않았으면 책임을 집니다.","도급인이 파산선고를 받은 때 수급인 또는 파산관재인은 계약을 해제할 수 있다. 수급인은 완성된 부분에 대한 보수 및 비용에 대하여 파산재단의 배당에 가입할 수 있다. 각 당사자는 계약해제로 인한 손해배상을 청구하지 못한다":"도급인이 파산하면 수급인이나 관재인이 해제할 수 있고 수급인은 완성 부분 보수를 파산재단에 가입하며 손해배상은 서로 못 합니다.","도달은 상대방이 요지할 수 있는 상태(사회통념상 알 수 있는 객관적 상태)에 놓인 것으로 충분하다. 상대방이 내용을 알아야 하는 것이 아니다":"도달은 상대방이 알 수 있는 객관적 상태에 놓이면 충분하며 내용을 실제로 알아야 하는 것은 아닙니다.","도달 후에는 상대방이 알기 전이라도 철회할 수 없다. 내용증명 우편물이 발송되고 반송되지 않았다면 특별한 사정이 없는 한 그 무렵 송달된 것으로 본다. 보통우편은 반송되지 않았다는 사정만으로 도달이 추정되지 않는다":"도달하면 상대방이 알기 전이라도 철회할 수 없고, 내용증명은 반송이 없으면 그 무렵 송달된 것으로 보지만 보통우편은 그렇지 않습니다.","도박채무 변제를 위한 대리권 수여행위":"도박채무 변제를 위한 대리권 수여행위는 반사회질서로 보지 않는 예예요.","동기가 표시되지 않았더라도 상대방에 의하여 유발된 동기의 착오는 취소할 수 있다(표시 요건 불요). 동기를 의사표시 내용으로 삼기로 하는 별도의 합의까지 필요한 것은 아니다":"상대방이 유발한 동기의 착오는 동기가 표시되지 않았어도 취소할 수 있고 별도 합의까지 필요하지는 않습니다.","동물의 점유자는 그 동물이 타인에게 가한 손해를 배상한다. 동물의 종류와 성질에 따라 상당한 주의를 해태하지 않은 때 면책된다. 점유자에 갈음하여 동물을 보관한 자도 같다":"동물의 점유자는 그 동물이 타인에게 가한 손해를 배상하고 종류와 성질에 따른 상당한 주의를 했으면 면책되며 보관자도 같아요.","동산·건물·대지는 매월 말, 기타 토지는 매년 말. 수확기 있는 것은 수확 후 지체 없이":"차임은 동산·건물·대지는 매월 말, 기타 토지는 매년 말에 내고 수확기가 있으면 수확 후 지체 없이 냅니다.","동산 물권의 양도는 인도하여야 효력이 생긴다. 양수인이 이미 점유한 때에는 의사표시만으로 효력이 생긴다(간이인도)":"동산 물권의 양도는 인도해야 효력이 생기며 양수인이 이미 점유 중이면 의사표시만으로 효력이 생깁니다.","동일인 명의로 소유권보존등기가 중복으로 된 경우 특별한 사정이 없는 한 후행 등기가 무효다":"동일인 명의로 소유권보존등기가 중복되면 특별한 사정이 없는 한 뒤의 등기가 무효예요.","동일한 물건에 대한 소유권과 다른 물권이 동일한 사람에게 귀속한 때 다른 물권은 소멸한다. 그 물권이 제3자의 권리의 목적이 된 때에는 소멸하지 않는다. 점유권에는 적용하지 않는다":"같은 물건에 대한 소유권과 다른 물권이 한 사람에게 귀속하면 다른 물권은 소멸하지만 제3자 권리의 목적이면 소멸하지 않아요.","동일한 채권의 담보로 수개의 부동산에 저당권을 설정한 경우 경매대가를 동시에 배당하면 각 부동산의 경매대가에 비례하여 채권의 분담을 정한다. 일부 경매대가를 먼저 배당하면 그 대가에서 채권 전부의 변제를 받을 수 있고, 이 경우 그 부동산의 차순위저당권자는 선순위자가 다른 부동산의 경매대가에서 변제받을 수 있는 금액 한도에서 선순위자를 대위하여 저당권을 행사할 수 있다":"공동저당은 동시배당이면 경매대가 비율로 분담하고, 일부를 먼저 배당하면 전부 변제받되 차순위자가 선순위자를 대위할 수 있어요.","등기사항 9가지는 목적, 명칭, 사무소, 설립허가의 연월일, 자산의 총액 · 존립시기나 해산이유를 정한 때 그 시기 또는 사유 · 출자의 방법을 정한 때 그 방법, 이사의 성명ㆍ주소, 대표권 제한":"등기사항은 목적, 명칭, 사무소, 허가 연월일, 자산 총액, 존립시기, 출자 방법, 이사의 성명·주소, 대표권 제한이에요.","등기사항에 대한 변경은 3주간 내에 변경등기한다 · 설립등기 외 등기사항은 등기 후가 아니면 제3자에게 대항하지 못한다 · 등기한 사항은 법원이 지체없이 공고한다":"등기사항이 바뀌면 3주간 내에 변경등기를 하고, 설립등기 외에는 등기 후가 아니면 제3자에게 대항하지 못해요.","등기한 토지임차권은 제3자에게 대항할 수 있다. 임차권등기를 하지 않았다고 해서 제3자에게 전혀 대항하지 못하는 것은 아니다(건물 등기 등 별도 대항요건 인정)":"등기한 토지임차권은 제3자에게 대항할 수 있고, 임차권등기가 없어도 건물 등기 등 별도의 대항요건이 인정될 수 있어요.","등유 - 소비물(1회 사용으로 소멸), 자동차 - 단일물(집합물 아님), 황소 - 불가분물, 유명화가의 특정 작품 - 부대체물, 아편 - 불융통물":"등유는 소비물, 자동차는 단일물, 황소는 불가분물, 특정 작품은 부대체물, 아편은 불융통물이라는 짝입니다.","만 17세 5개월 된 자의 유언(17세에 달하면 유언 가능, 제한능력 규정 배제), 대리인으로서 한 대리행위, 허락받은 특정 영업행위, 속임수로 능력자로 믿게 한 법률행위":"17세가 되면 유언이 가능하고 대리행위, 허락받은 영업, 속임수로 능력자로 믿게 한 행위는 단독으로 취소하지 못합니다.","망을 보는 역할을 한 자도 공동불법행위자로서 피해자에 대하여 전체 손해(100만원 전부)를 배상할 책임이 있다":"망을 본 사람도 공동불법행위자라서 피해자에 대해 전체 손해를 배상할 책임이 있습니다.","매도인은 그 권리를 취득하여 매수인에게 이전하여야 한다. 이전할 수 없는 때 매수인은 계약을 해제할 수 있다. 계약 당시 권리가 매도인에게 속하지 않음을 안 매수인은 손해배상을 청구하지 못한다(악의면 해제만)":"타인 권리 매매의 매도인은 권리를 취득해 이전해야 하고 못 하면 매수인이 해제하며 악의 매수인은 손해배상을 못 합니다.","매도인은 목적이 된 권리를 이전하고 매수인은 대금을 지급하여야 하며 쌍방 의무는 특별한 약정이나 관습이 없으면 동시에 이행한다":"매도인은 권리를 이전하고 매수인은 대금을 지급하며 특약이나 관습이 없으면 두 의무는 동시에 이행해요.","매도인의 하자담보책임과 채무불이행책임은 별개의 권원으로 경합하여 병존할 수 있다":"하자담보책임과 채무불이행책임은 서로 다른 근거여서 함께 주장할 수 있습니다.","매도인이 매매계약과 동시에 환매권을 보류한 때 영수한 대금과 매수인이 부담한 매매비용을 반환하고 목적물을 환매할 수 있다. 기간은 부동산 5년, 동산 3년을 넘지 못하고 연장하지 못한다. 기간을 정하지 않으면 부동산 5년, 동산 3년. 환매권 보류의 등기는 매매등기와 동시에 한다":"환매권을 보류한 매도인은 영수한 대금과 매매비용을 반환하고 환매할 수 있으며 기간은 부동산 5년, 동산 3년을 넘지 못해요.","매도인이 매매계약을 적법하게 해제한 후에도 매수인은 해제의 불이익을 면하기 위해 착오를 이유로 계약을 취소할 수 있다":"매도인이 계약을 적법하게 해제한 뒤에도 매수인은 착오를 이유로 계약을 취소할 수 있습니다.","매매계약에 기한 매수인의 소유권이전등기청구권, 점유취득시효 완성자의 소유자에 대한 소유권이전등기청구권, 민법 제621조에 의한 임차인의 임대인에 대한 임차권설정등기청구권":"매매에 기한 이전등기청구권, 점유취득시효 완성자의 등기청구권, 임차권설정등기청구권은 채권적 청구권입니다.","매매계약은 채권행위로서 처분행위가 아니다":"매매계약은 채무를 발생시키는 채권행위일 뿐이어서 처분행위에 속하지 않습니다.","매매계약을 체결할 권한을 수여받은 대리인이라도 특별한 사정이 없는 한 그 계약을 해제할 권한은 없다":"매매 체결 권한만으로는 그 계약을 해제할 권한까지 대리인에게 생기지 않습니다.","매매계약의 비용은 당사자 쌍방이 균분하여 부담한다":"매매 계약에 드는 비용은 매도인과 매수인이 절반씩 나누어 부담합니다.","매매계약의 체결과 이행에 관하여 포괄적 대리권을 받은 대리인은 특별한 사정이 없는 한 대금지급기일을 연기해 줄 권한도 가진다":"매매의 체결과 이행을 포괄적으로 맡은 대리인은 특별한 사정이 없으면 대금지급기일을 늦춰 줄 수도 있습니다.","매매계약이 무효가 되는 사정을 알지 못하고 부동산을 매수한 자의 점유는 후일 매매가 무효로 되어도 자주점유가 타주점유로 변하지 않는다":"무효인 매매를 모르고 매수한 점유는 나중에 매매가 무효가 되어도 자주점유가 타주점유로 바뀌지 않습니다.","매매계약이 합의해제되면 원칙적으로 매수인에게 이전되었던 소유권은 당연히 매도인에게 복귀한다":"합의해제가 되면 원칙적으로 매수인에게 넘어갔던 소유권이 당연히 매도인에게 돌아옵니다.","매매계약이 합의해제된 후 매도인의 등기말소청구권은 소유권에 기한 물권적 청구권이다(채권적 청구권 아님)":"매매계약이 합의해제된 뒤 매도인의 등기말소청구권은 채권적 청구권이 아니라 소유권에 기한 물권적 청구권입니다.","매매계약 체결 대리권을 수여받은 대리인이 대금을 수령한 경우 본인에게 전달하지 않아도 상대방의 대금지급의무는 소멸한다":"매매 체결 대리권을 받은 대리인이 대금을 받았다면 본인에게 전달하지 않아도 상대방의 대금지급의무는 없어집니다.","매매계약 후에도 인도하지 않은 목적물로부터 생긴 과실은 매도인에게 속한다. 매수인은 목적물의 인도를 받은 날부터 대금의 이자를 지급한다. 대금지급에 기한이 있으면 제외":"인도하지 않은 목적물의 과실은 매도인에게 속하고 매수인은 인도받은 날부터 대금 이자를 내며 대금지급에 기한이 있으면 제외됩니다.","매매 당사자 일방이 계약 당시 금전 기타 물건을 계약금·보증금 등의 명목으로 상대방에게 교부한 때, 다른 약정이 없는 한 당사자의 일방이 이행에 착수할 때까지 교부자는 이를 포기하고 수령자는 그 배액을 상환하여 계약을 해제할 수 있다. 이 해제에는 제551조(손해배상)를 적용하지 않는다":"계약금을 준 쪽은 포기하고 받은 쪽은 배액을 상환하면 한쪽이 이행에 착수하기 전까지 해제할 수 있으며 손해배상은 적용되지 않습니다.","매매 등으로 점유를 승계한 경우 전 점유자의 점유가 타주점유여도 현 점유자가 자기의 점유만을 주장하면 현 점유자의 점유는 자주점유로 추정된다":"점유를 승계하고 자기 점유만 주장하면 전 점유자가 타주점유였어도 현 점유자의 점유는 자주점유로 추정됩니다.","매매예약 완결의 의사표시 전에 목적물이 멸실된 경우 완결의 의사표시를 하여도 매매의 효력은 발생하지 않는다. 甲만이 예약완결권을 가지는 예약을 ‘편무예약’이라고 한 선지는 정답이 아니었고, 甲이 완결권을 행사하려면 乙에게 대금 전액을 제공하여야 한다는 선지도 정답이 아니었다":"완결 의사표시 전에 목적물이 멸실되면 매매의 효력이 생기지 않으며, 편무예약이라는 선지와 대금 전액 제공이 필요하다는 선지는 틀린 보기였어요.","매매의 일방예약은 상대방(예약완결권자)이 매매를 완결할 의사를 표시하는 때에 매매의 효력이 생긴다. 의사표시의 기간을 정하지 않은 때 예약자는 상당한 기간을 정해 확답을 최고할 수 있고, 확답을 받지 못하면 예약은 효력을 잃는다":"매매의 일방예약은 예약완결권자가 완결 의사를 표시하면 매매 효력이 생기고 기간이 없으면 최고 후 확답이 없을 때 효력을 잃습니다.","매수인은 그 부분의 비율로 대금감액을 청구할 수 있다(선의·악의 불문). 잔존부분만이면 매수하지 않았을 때 선의의 매수인은 계약 전부를 해제할 수 있다. 선의의 매수인은 감액청구 또는 해제 외에 손해배상도 청구할 수 있다(감액청구와 손해배상 병행 가능)":"권리의 일부가 타인에게 속하면 그 비율로 대금감액을 청구할 수 있고 선의 매수인은 해제나 손해배상도 청구할 수 있어요.","매수인의 대리인이 매도인을 기망한 경우 매수인이 알 수 없었더라도 매도인은 사기를 이유로 취소할 수 있다":"매수인의 대리인이 매도인을 속였다면 매수인이 몰랐어도 매도인은 사기를 이유로 취소할 수 있어요.","매수인이 목적 부동산을 인도받아 계속 점유하는 경우 소유권이전등기청구권의 소멸시효는 진행하지 않는다. 점유를 승계시켜 타인에게 처분한 경우에도 같다. 이 청구권은 권리의 성질상 양도가 제한되고 양도에 채무자의 승낙이나 동의가 필요하다":"목적 부동산을 인도받아 계속 점유하는 매수인의 소유권이전등기청구권은 소멸시효가 진행하지 않으며, 점유를 승계시켜 처분해도 같습니다.","매수인이 소유권을 취득할 수 없거나 취득한 소유권을 잃은 때 계약을 해제할 수 있다. 출재로 소유권을 보존한 때 상환을 청구할 수 있다. 손해를 받은 때 배상을 청구할 수 있다(매수인의 선의·악의를 묻지 않는다)":"저당권·전세권 행사로 소유권을 취득할 수 없거나 잃은 매수인은 선의·악의를 묻지 않고 해제와 손해배상을 청구할 수 있어요.","매월 1개월 단위로 지급되는 집합건물 관리비채권, 도급받은 공사의 공사대금채권, 상인이 판매한 상품의 대가채권, 공사대금채권을 담보하기 위한 수급인의 저당권설정청구권(공사대금채권과 같이 3년)":"월 단위 관리비채권, 공사대금채권, 상품 대가채권과 공사대금 담보용 저당권설정청구권에 3년 단기시효가 적용됩니다.","면제하는 특약을 한 경우에도 매도인이 알고 고지하지 않은 사실 및 제3자에게 권리를 설정 또는 양도한 행위에 대하여는 책임을 면하지 못한다":"담보책임을 면제하는 특약을 해도 매도인이 알고 알리지 않은 사실과 제3자에게 권리를 설정·양도한 행위에는 책임을 면하지 못합니다.","명의신탁약정에서 제외되는 경우: 채무변제 담보를 위한 이전ㆍ가등기, 부동산의 위치와 면적을 특정한 구분소유적 공유 등기, 신탁재산인 사실을 등기한 경우":"채무변제 담보를 위한 이전·가등기, 구분소유적 공유 등기, 신탁재산임을 등기한 경우는 명의신탁약정에서 제외됩니다.","명의신탁약정은 무효다. 명의신탁약정에 따른 등기로 이루어진 부동산 물권변동도 무효다. 이 무효는 제3자에게 대항하지 못한다":"명의신탁약정과 그에 따른 등기의 물권변동은 무효이고 이 무효는 제3자에게 대항하지 못해요.","명인방법을 갖춘 수목의 집단ㆍ미분리 과실은 독립한 거래 객체가 되며 양도담보권을 설정할 수 있다":"명인방법으로 공시한 수목 집단과 아직 따지 않은 과실은 토지와 별개 거래 대상이며 양도담보를 설정할 수 있습니다.","목적물에 권리를 주장하는 자가 있어 매수인이 권리의 전부나 일부를 잃을 염려가 있는 때 그 위험의 한도에서 대금 지급을 거절할 수 있다. 매도인이 상당한 담보를 제공하면 제외. 매도인은 대금 공탁을 청구할 수 있다":"제삼자가 권리를 주장해 매수인이 권리를 잃을 염려가 있으면 그 한도에서 대금 지급을 거절할 수 있고 매도인은 공탁을 청구합니다.","목적물에 하자가 있는 때 제575조 제1항을 준용한다. 매수인이 하자 있는 것을 알았거나 과실로 인하여 알지 못한 때에는 책임이 없다(선의·무과실 매수인만 보호)":"목적물의 하자는 매수인이 알았거나 과실로 몰랐으면 책임이 없어 선의·무과실 매수인만 보호됩니다.","목적물을 임차인에게 인도하고 계약존속 중 사용·수익에 필요한 상태를 유지하게 할 의무를 부담한다":"임대인은 목적물을 인도하고 계약 존속 중 사용·수익에 필요한 상태를 유지해 줄 의무가 있습니다.","목적물이 공탁에 부적당하거나 멸실ㆍ훼손의 염려가 있거나 과다한 비용이 드는 경우 법원의 허가를 얻어 경매·방매하여 대금을 공탁할 수 있다. 채권자의 상대의무이행과 동시에 변제할 경우 채권자는 의무이행을 하지 아니하면 공탁물을 수령하지 못한다":"공탁에 부적당한 물건은 법원 허가로 경매해 대금을 공탁하며 상대의무와 동시이행이면 채권자가 의무를 이행해야 수령할 수 있어요.","목적물이 지상권·지역권·전세권·질권·유치권의 목적이 된 경우 매수인이 알지 못한 때 계약의 목적을 달성할 수 없는 경우에 한하여 해제할 수 있고 기타는 손해배상만 청구할 수 있다. 부동산을 위하여 존재할 지역권이 없거나 등기된 임대차계약이 있는 경우 준용. 매수인이 그 사실을 안 날부터 1년 내에 행사한다":"지상권·지역권·전세권·질권·유치권이 있어 모르던 매수인은 목적 달성 불가 시 해제, 아니면 손해배상만 청구하고 안 날부터 1년 내 행사합니다.","목적범위 외 행위로 손해를 가한 경우다 · 의결 찬성자와 집행한 사원ㆍ이사ㆍ대표자가 연대 배상한다":"목적 범위 밖의 행위로 손해를 가하면 의결에 찬성한 사원·이사와 집행한 자가 연대하여 배상합니다.","목적이 원시적으로 불능한 계약을 체결할 때 그 불능을 알았거나 알 수 있었던 자는 상대방이 계약의 유효를 믿었음으로 인하여 받은 손해(신뢰이익)를 배상한다. 배상액은 이행이익을 넘지 못한다. 상대방이 불능을 알았거나 알 수 있었던 경우는 적용하지 않는다":"원시적 불능을 알았거나 알 수 있었던 자는 상대방이 유효를 믿어 입은 신뢰이익을 배상하며 이행이익을 넘지 못합니다.","무권대리인이 본인을 단독상속한 경우 본인의 지위에서 추인거절권을 행사하는 것은 신의칙상 허용되지 않는다":"무권대리인이 본인을 단독상속하면 본인 자격으로 추인을 거절하는 주장은 신의칙에 어긋납니다.","무권대리행위가 제3자의 위법행위로 야기된 경우에도 무권대리인의 책임은 귀책사유와 무관하게(무과실책임) 인정된다":"무권대리인의 책임은 제3자의 위법행위로 일어난 경우에도 귀책사유와 무관한 무과실책임입니다.","무권대리행위에 대하여 본인이 이의를 제기하지 않고 장기간 방치한 사실만으로는 추인이 있다고 볼 수 없다":"무권대리행위를 본인이 이의 없이 오래 방치한 사실만으로는 추인했다고 볼 수 없습니다.","무권리자의 처분행위에 대한 권리자의 추인의 의사표시는 무권리자나 그 상대방 어느 쪽에 하여도 무방하다":"무권리자의 처분행위에 대한 권리자의 추인은 무권리자나 상대방 어느 쪽에 해도 됩니다.","무상증여 등 무상계약에는 제104조가 적용되지 않는다":"무상증여 같은 무상계약에는 제104조가 적용되지 않지만 대가관계를 상정할 수 있으면 단독행위에도 적용됩니다.","무주물선점에 의한 소유권 취득은 자주점유인 경우에 인정된다":"무주물선점으로 소유권을 얻으려면 소유의 의사로 하는 자주점유여야 해요.","무주의 동산을 소유의 의사로 점유한 자는 소유권을 취득한다(무주의 부동산은 국유). 유실물은 공고 후 6개월 내 소유자가 권리를 주장하지 않으면 습득자가 소유권을 취득한다. 매장물은 1년 내":"무주의 동산을 소유 의사로 점유하면 소유권을 취득하고, 유실물은 공고 후 6개월, 매장물은 1년 내 주장이 없으면 습득자가 취득합니다.","무효등기의 유용에 관한 합의는 명시적이 아니어도 묵시적으로 가능하다. 유용 합의 시부터 유효하다":"무효등기 유용의 합의는 명시적이지 않아도 묵시적으로 할 수 있고 합의한 때부터 유효해요.","무효를 주장하는 자가 상대방의 악의 또는 과실을 증명할 책임을 진다":"상대방의 악의나 과실은 무효를 주장하는 쪽이 증명해야 해요.","무효인 가등기를 유효한 등기로 전용하기로 약정한 경우 그 가등기는 약정 시부터 유효하고, 등기 시로 소급하여 유효하게 되는 것은 아니다":"무효 가등기를 유효한 등기로 전용하기로 약정하면 약정 시부터 유효하고 등기 시로 소급하지 않아요.","무효인 명의신탁약정에 의해 명의수탁자 명의 등기가 마쳐진 경우는 불법원인급여에 해당하지 않는다":"무효인 명의신탁약정으로 수탁자 명의 등기가 되어도 불법원인급여로 보지 않습니다.","무효인 명의신탁약정에 의해 명의수탁자 명의의 등기가 마쳐진 경우는 불법원인급여에 해당하지 않는다":"무효인 명의신탁약정에 따라 수탁자 명의 등기가 마쳐진 경우는 불법원인급여가 아닙니다.","무효인 법률행위가 다른 법률행위의 요건을 구비하고 당사자가 그 무효를 알았더라면 다른 법률행위를 하는 것을 의욕하였으리라고 인정될 때 다른 법률행위로서 효력을 가진다. 불공정한 법률행위에도 적용될 수 있다":"무효 행위가 다른 행위의 요건을 갖추고 당사자가 알았다면 그 다른 행위를 원했으리라 인정될 때 그 행위로 유효해집니다.","무효인 법률행위는 추인하여도 효력이 생기지 않는다. 당사자가 그 무효임을 알고 추인한 때에는 새로운 법률행위로 본다(소급효 없음)":"무효행위는 추인해도 효력이 없고, 무효임을 알고 추인하면 새 법률행위로 보며 소급효는 없습니다.","무효인 편입허가를 받은 자에 대해 오랜 기간 경과 후 편입학을 취소하는 것은 신의칙 위반이 아니다":"무효인 편입허가를 받은 사람의 편입학을 오랜 뒤 취소해도 신의칙 위반이 아닙니다.","무효임을 알면서 법률행위를 한 자의 무효 주장이다":"무효임을 알면서 법률행위를 해 놓고 나중에 그 무효를 주장하는 경우를 다룹니다.","무효행위의 전환(제138조)은 적용될 수 있다":"무효인 행위가 다른 행위의 요건을 갖추고 있으면 그 다른 행위로 효력을 인정하는 전환이 가능합니다.","묵시적 승인도 관념의 통지에 해당한다":"말이나 행동으로 드러난 묵시적 승인도 관념의 통지에 해당해요.","물건을 사실상 지배하는 자는 점유권이 있다. 사실상의 지배를 상실하면 소멸한다. 단 점유회수의 소(제204조)로 점유를 회수한 때에는 소멸하지 않는다":"물건을 사실상 지배하는 자는 점유권이 있고 지배를 잃으면 소멸하지만 점유회수의 소로 회수하면 소멸하지 않습니다.","물건의 사용대가로 받는 금전 기타의 물건(차임, 이자 등). 수취할 권리의 존속기간 일수의 비율로 취득한다":"법정과실은 차임이나 이자처럼 물건의 사용 대가로 받는 금전 등이며, 권리 존속 일수의 비율로 취득합니다.","물건의 소유자가 그 물건의 상용에 공하기 위하여 자기 소유인 다른 물건을 부속하게 한 것. 종물은 주물의 처분에 따른다":"종물은 소유자가 상용에 쓰려고 자기 소유 물건을 덧붙인 것으로 주물을 처분하면 함께 처분됩니다.","물건의 용법에 의하여 수취하는 산출물. 원물로부터 분리하는 때 수취할 권리자에게 속한다":"천연과실은 물건의 용법에 따라 얻는 산출물로, 원물에서 분리될 때 수취할 권리자에게 속해요.","물건이 지분에 의하여 수인의 소유로 된 때. 공유자의 지분은 균등한 것으로 추정한다":"공유는 물건이 지분에 의해 여러 사람의 소유가 된 것으로 지분은 균등한 것으로 추정해요.","물권에 관한 등기가 원인 없이 말소되어도 물권의 효력에는 영향이 없다":"원인 없이 등기가 말소되어도 물권 자체의 효력은 그대로 유지됩니다.","물권은 법률 또는 관습법에 의하는 외에는 임의로 창설하지 못한다(제185조)":"물권법정주의에 따라 물권은 법률이나 관습법에 없는 한 당사자가 마음대로 만들 수 없습니다.","물권은 법률 또는 관습법에 의하는 외에는 임의로 창설하지 못한다. 여기서 ‘법률’에는 규칙이나 지방자치단체의 조례가 포함되지 않는다":"물권은 법률이나 관습법에 의해서만 만들 수 있고 여기서 법률에는 규칙이나 조례가 포함되지 않습니다.","물권 이외의 권리(채권 등)를 직접 변동시키는 처분행위다":"준물권행위는 물권이 아닌 채권 등 권리를 직접 변동시키는 처분행위입니다.","물상보증인 소유 부동산에 대한 압류는 주채무자에게 통지하여야 주채무자에 대하여 시효중단의 효력이 생긴다":"물상보증인 소유 부동산을 압류하면 주채무자에게 통지해야 주채무자에 대한 중단 효력이 생깁니다.","물상보증인이 근저당권설정계약을 체결하는 경우 채무자의 동일성에 관한 착오는 중요부분의 착오다":"물상보증인이 근저당 설정계약을 맺을 때 채무자가 누구인지에 관한 착오는 중요부분의 착오입니다.","미등기건물을 양수하여 사실상의 처분권을 가진 자는 토지소유자에 대하여 건물부지의 점유ㆍ사용에 따른 부당이득반환의무를 진다. 건물에 유치권을 행사하는 자는 건물 부지를 점유하는 자에 해당하지 않는다":"미등기건물을 양수해 사실상 처분권을 가진 자는 부지 점유에 따른 부당이득을 반환하며, 건물 유치권자는 부지 점유자가 아닙니다.","미등기 무허가건물의 취득자에게는 소유권에 준하는 관습상의 물권이 인정되지 않는다":"미등기 무허가건물의 취득자는 소유권과 비슷한 관습상 물권까지는 인정받지 못합니다.","미성년자가 법률행위를 할 때는 법정대리인의 동의를 얻어야 한다. 단 권리만을 얻거나 의무만을 면하는 행위는 동의 불요. 위반한 행위는 취소할 수 있다":"미성년자는 법정대리인 동의를 얻어야 하나 권리만 얻거나 의무만 면하는 행위는 동의가 필요 없고 위반하면 취소할 수 있어요.","미성년자가 타인에게 손해를 가한 경우 그 행위의 책임을 변식할 지능이 없는 때에는 배상책임이 없다":"미성년자가 책임을 변식할 지능이 없으면 배상책임이 없어요.","미성년자가 행위능력자가 된 후 이의를 보류함이 없이 법률행위에 따라 이행한 때에는 추인한 것으로 본다":"미성년자가 성년이 된 뒤 이의를 보류하지 않고 이행했다면 추인한 것으로 봅니다.","미성년자가 혼인을 한 때에는 성년자로 본다":"미성년자가 혼인하면 성년자로 보는 성년의제가 적용됩니다.","미성년자는 법정대리인의 동의 없이 부담부증여계약을 체결할 수 없다(의무를 지므로)":"부담부증여는 의무를 지게 되므로 미성년자가 법정대리인의 동의 없이는 체결할 수 없습니다.","미성년자는 타인의 임의대리인이 될 수 있다. 법정대리인의 승낙은 필요 없다(대리인은 행위능력자임을 요하지 않는다)":"미성년자는 타인의 임의대리인이 될 수 있으며, 대리인은 행위능력자일 필요가 없어 법정대리인 승낙도 필요 없어요.","민법상 조합의 대리는 조합원 전원의 성명을 표시할 필요가 없고 조합 이름으로 대리행위를 할 수 있다":"민법상 조합의 대리는 조합원 전원의 성명을 밝히지 않고 조합 이름으로 할 수 있습니다.","민사에 관하여 법률에 규정이 없으면 관습법에 의한다":"민사에서 적용할 법률이 없을 때 두 번째로 따르는 법원(法源)이 관습법입니다.","민사에 관한 일반적으로 승인된 국제법규":"민사에 관한 일반적으로 승인된 국제법규도 법원으로 인정됩니다.","민사에 관한 집행명령, 대법원규칙(부동산등기규칙 포함), 대통령의 긴급재정명령":"집행명령, 부동산등기규칙을 포함한 대법원규칙, 대통령의 긴급재정명령도 민사의 법원에 듭니다.","민사에 관한 헌법에 의해 체결ㆍ공포된 조약":"헌법에 따라 체결·공포된 민사 관련 조약은 민법의 법원이 됩니다.","반려동물은 물건이다. 위자료청구권의 귀속주체가 될 수 없다":"반려동물은 법적으로 물건이어서 정신적 고통에 대한 위자료를 청구하는 주체가 될 수 없습니다.","반려동물은 민법 규정의 해석상 물건에 해당한다":"민법을 해석하면 반려동물도 사람이 아닌 물건의 범주에 속합니다.","반사회질서의 법률행위로 볼 수 없다":"이런 허위 저당권설정은 반사회질서의 법률행위로는 볼 수 없어요.","받은 이익에 이자를 붙여 반환하고 손해가 있으면 배상한다":"악의의 수익자는 받은 이익에 이자를 붙여 반환하고 손해가 있으면 배상해요.","받은 이익이 현존한 한도에서 반환한다":"선의의 수익자는 받은 이익이 현존한 한도에서 반환합니다.","발송 후 도달 전에 표의자가 사망하거나 제한능력자가 되어도 의사표시의 효력에 영향이 없다":"의사표시를 보낸 후 도달 전에 표의자가 죽거나 제한능력자가 돼도 이미 보낸 표시의 효력은 유지됩니다.","방해를 받을 염려가 있는 때 방해의 예방 또는 손해배상의 담보를 청구할 수 있다":"점유보전은 방해를 받을 염려가 있을 때 예방이나 손해배상의 담보를 청구하는 권리입니다.","방해배제청구에서 방해는 현재에도 지속되고 있는 침해를 의미한다. 방해배제는 현재 계속되고 있는 방해의 원인을 제거하는 것을 내용으로 한다":"방해배제청구에서 방해는 현재도 계속되는 침해를 뜻하고 그 원인을 제거하는 것이 내용이에요.","방해제거ㆍ방해예방 청구(제214조 준용)는 가능하나 승역지의 반환청구는 할 수 없다":"지역권자는 방해제거·예방을 청구할 수 있지만 승역지의 반환청구는 할 수 없습니다.","법령으로서의 효력이 없는 단순한 관행이며 법률행위 당사자의 의사를 보충하는 데 그친다":"사실인 관습은 법령의 효력이 없는 단순한 관행으로서 당사자의 의사를 보충하는 데 그칩니다.","법령 중 선량한 풍속 기타 사회질서에 관계없는 규정(임의규정)과 다른 관습이 있다":"사실인 관습은 선량한 풍속과 무관한 임의규정과 다른 내용의 관습을 말합니다.","법률상 원인 없이 타인의 재산 또는 노무로 인하여 이익을 얻고 이로 인하여 타인에게 손해를 가한 자는 그 이익을 반환하여야 한다":"법률상 원인 없이 타인의 재산이나 노무로 이익을 얻어 손해를 입힌 자는 그 이익을 반환해야 해요.","법률의 규정에 의한 부동산 물권 취득(상속, 공용징수, 판결, 경매 기타)은 등기를 요하지 않는다. 그러나 등기를 하지 않으면 처분하지 못한다":"상속이나 경매처럼 법률 규정에 의한 취득은 등기가 필요 없지만 등기하지 않으면 처분할 수 없어요.","법률행위(계약)의 취소(사기에 의한 매매계약 취소 포함), 한정후견인의 동의":"사기에 의한 매매계약 취소와 한정후견인의 동의는 상대방 있는 단독행위입니다.","법률행위 내용의 중요부분에 착오가 있을 때 취소할 수 있다. 그 착오가 표의자의 중대한 과실로 인한 때에는 취소하지 못한다. 취소는 선의의 제3자에게 대항하지 못한다":"법률행위 내용의 중요부분에 착오가 있으면 취소할 수 있지만 중대한 과실이 있으면 못하고, 취소는 선의 제3자에게 대항하지 못해요.","법률행위로 인한 부동산 물권의 득실변경은 등기하여야 효력이 생긴다(성립요건주의). 등기는 효력발생요건이지 효력존속요건이 아니다":"법률행위로 인한 부동산 물권변동은 등기해야 효력이 생기며 등기는 효력발생요건이지 존속요건이 아닙니다.","법률행위에 정지조건이 붙어 있다는 사실(조건의 존재)의 증명이다":"정지조건이 붙어 있다는 사실, 곧 조건의 존재를 증명하는 문제입니다.","법률행위의 성립이 인정되는 경우에만 가능하다(의사표시의 흠결 보충)":"보충적 해석은 법률행위가 성립한 경우에 한해 의사표시의 빈틈을 채우는 해석입니다.","법률행위의 일부분이 무효인 때에는 그 전부를 무효로 한다. 단 그 무효부분이 없더라도 법률행위를 하였을 것이라고 인정될 때에는 나머지 부분은 무효가 되지 아니한다":"법률행위 일부가 무효이면 전부 무효가 원칙이나, 무효 부분 없이도 했으리라 인정되면 나머지는 유효해요.","법률효과의 발생을 다투려는 자가 증명하여야 한다":"법률효과의 발생을 다투려는 쪽이 조건의 존재를 증명해야 해요.","법원(法源)으로서 효력을 가진다":"관습법은 법원(法源)으로서 효력을 가지므로 법률처럼 구속력이 있어요.","법원(法院)은 관습법이 헌법에 위반되는지 여부를 판단할 수 있다":"재판하는 법원(法院)이 관습법의 내용이 헌법에 맞는지 심사할 수 있다는 뜻입니다.","법원은 이해관계인이나 검사의 청구에 의하여 재산관리에 필요한 처분을 명하여야 한다. 본인의 부재 중 재산관리인의 권한이 소멸한 때에도 같다":"재산관리인을 정하지 않았거나 그 권한이 사라졌다면 법원은 청구에 따라 재산관리에 필요한 처분을 명해야 합니다.","법원은 인정사망이나 실종선고에 의하지 않고도 경험칙에 의거하여 사망사실을 인정할 수 있다":"법원은 인정사망이나 실종선고가 없어도 경험칙에 따라 사망 사실을 인정할 수 있습니다.","법원은 재산관리인에게 재산의 관리 및 반환에 관하여 상당한 담보를 제공하게 할 수 있고, 부재자의 재산으로 상당한 보수를 지급할 수 있다":"법원은 재산관리인에게 담보를 내게 할 수 있고 부재자 재산으로 상당한 보수를 줄 수 있습니다.","법원은 피해자의 청구에 의하여 손해배상에 갈음하거나 손해배상과 함께 명예회복에 적당한 처분을 명할 수 있다":"법원은 피해자가 청구하면 배상 대신 또는 배상과 함께 명예회복에 적당한 처분을 명할 수 있습니다.","법원의 허가는 사후적으로 처분행위를 추인하는 방법으로도 할 수 있다. 허가 없이 매각한 후 허가를 얻어 이전등기를 마쳤다면 추인된 것으로 본다":"법원의 허가는 나중에 처분행위를 추인하는 방식으로도 가능해서, 허가 없이 팔고 허가받아 등기를 마치면 추인된 것으로 봅니다.","법원이 선임한 재산관리인은 관리할 재산목록을 작성하여야 한다. 법원은 선임한 재산관리인에게 부재자의 재산을 보존하기 위하여 필요한 처분을 명할 수 있다. 비용은 부재자의 재산으로 지급한다":"법원이 정한 재산관리인은 재산목록을 만들고 보존 처분을 따르며, 그 비용은 부재자 재산에서 지급합니다.","법원이 선임한 재산관리인은 법정대리인이다. 언제든지 사임할 수 있다(법원의 허가는 불요)":"법원이 선임한 재산관리인은 법정대리인이며 법원 허가 없이도 언제든 사임할 수 있어요.","법원이 선임한 재산관리인이 부재자의 사망을 확인한 경우에도 선임결정이 취소되지 않는 한 권한을 행사할 수 있다. 선임결정 취소의 효력은 장래에 향하여서만 생기며, 취소 전의 권한 내 행위는 실종선고기간 만료 후에 이루어졌더라도 유효하다":"재산관리인이 사망을 확인해도 선임결정이 취소되기 전까지는 권한이 유지되고, 취소의 효력은 장래에만 생깁니다.","법원이 선임한 재산관리인이 제118조의 권한(보존행위, 이용ㆍ개량행위)을 넘는 행위를 하려면 법원의 허가를 얻어야 한다. 부재자의 생사가 분명하지 않은 경우 부재자가 정한 재산관리인이 권한을 넘는 행위를 할 때도 같다":"재산관리인이 보존·이용·개량을 넘는 행위를 하려면 법원의 허가가 필요하며, 부재자가 정한 관리인도 같습니다.","법인도 유증을 받을 수 있다. 청산법인의 권리능력은 청산의 목적범위 내로 제한된다":"법인도 유증을 받을 수 있고, 청산법인의 권리능력은 청산 목적의 범위 안으로 좁아집니다.","법인 아닌 재단의 재산 소유를 민법이 단독소유로 규정한 것은 아니다 · 합유는 수인이 조합체로서 소유하며 처분ㆍ변경은 전원 동의, 보존은 각자 · 지분처분은 전원 동의가 필요하고 분할을 청구하지 못한다":"합유는 조합체로 소유하며 처분·변경은 전원 동의, 보존은 각자 하고 지분처분은 전원 동의가 필요하며 분할청구는 못합니다.","법인은 법률의 규정에 의함이 아니면 성립하지 못한다(법인법정주의)":"법인은 법에 근거가 있어야만 만들어질 수 있고 당사자가 임의로 새 종류를 만들지 못합니다.","법인은 이사를 두어야 한다(필수기관) · 수와 임기는 제한이 없고 정관으로 정한다 · 사무를 집행하고 수인이면 정관에 다른 규정 없는 한 과반수 결정":"이사는 법인의 필수기관으로 수와 임기는 정관으로 정하고 여럿이면 과반수로 사무를 결정해요.","법인은 주된 사무소 소재지에서 설립등기를 함으로써 성립한다 · 설립등기는 성립요건이다(대항요건 아님) · 사단법인은 정관이 작성된 때가 아니라 설립등기 시에 성립한다":"법인은 주된 사무소 소재지에서 설립등기를 해야 성립하며, 설립등기는 성립요건입니다.","법인의 사무는 주무관청이 검사ㆍ감독한다 · 해산 및 청산은 법원이 검사ㆍ감독한다":"법인의 사무는 주무관청이, 해산과 청산은 법원이 검사하고 감독합니다.","법정대리인은 미성년자가 아직 법률행위를 하기 전에는 동의와 허락을 취소할 수 있다":"미성년자가 아직 그 행위를 하지 않았다면 법정대리인이 이미 한 동의와 허락을 거둬들일 수 있어요.","법정대리인의 동의는 묵시적으로도 할 수 있다":"법정대리인의 동의는 말로 하지 않아도 묵시적으로 할 수 있어요.","법정대리인이 범위를 정하여 처분을 허락한 재산은 미성년자가 임의로 처분할 수 있다":"법정대리인이 범위를 정해 허락한 재산은 미성년자가 따로 동의를 받지 않고 스스로 처분합니다.","법정대리인이 제한능력자의 법률행위를 추인한 후에는 제한능력을 이유로 취소하지 못한다":"법정대리인이 제한능력자의 법률행위를 추인하면 이후 제한능력을 이유로 취소할 수 없습니다.","법정대위자가 있는 경우 채권자의 고의나 과실로 담보가 상실되거나 감소된 때 대위할 자는 상환받을 수 없는 한도에서 책임을 면한다":"법정대위자가 있는데 채권자 고의·과실로 담보가 줄면 대위할 자는 상환받지 못하는 한도에서 책임을 면해요.","법정지상권을 취득한 건물소유자가 설정등기 없이 건물을 양도하는 경우 특별한 사정이 없는 한 토지소유자는 건물 양수인에 대하여 건물철거를 청구할 수 없다":"법정지상권을 얻은 건물소유자가 설정등기 없이 건물을 양도하면 토지소유자는 양수인에게 건물철거를 청구할 수 없어요.","법정추인 법리도 적용되지 않는다":"법정추인의 법리도 불공정한 법률행위에는 적용되지 않아요.","변제기에 있지 않은 채무를 변제한 때 반환을 청구하지 못한다. 단 채무자가 착오로 변제한 때 채권자는 이로 인하여 얻은 이익(중간이자)을 반환하여야 한다":"변제기 전에 변제한 때는 반환을 청구하지 못하나 착오로 변제했다면 채권자는 얻은 중간이자를 반환해야 합니다.","변제 기타 출재로 공동면책이 된 연대채무자는 다른 연대채무자의 부담부분에 대하여 구상권을 행사할 수 있다. 구상권에는 면책된 날 이후의 법정이자 및 피할 수 없는 비용 기타 손해배상을 포함한다":"공동면책된 연대채무자는 다른 연대채무자의 부담부분에 구상권을 행사하며 면책일 이후의 법정이자와 비용을 포함합니다.","변제를 받을 때까지 질물을 유치할 수 있으나 우선권 있는 채권자에게 대항하지 못한다. 전질: 자기의 책임으로 질물을 전질할 수 있고 불가항력 손해에도 책임을 진다. 전질의 대항요건: 채무자에게 통지하거나 채무자가 승낙":"질권자는 변제받을 때까지 질물을 유치하되 우선권 있는 채권자에게 대항 못 하고, 전질은 자기 책임으로 하며 채무자에게 통지·승낙을 받습니다.","변제비용은 다른 의사표시가 없으면 채무자 부담. 채권자의 주소이전 등으로 증가된 부분은 채권자 부담. 변제자는 영수증을 청구할 수 있고, 채무 전부를 변제한 때 채권증서의 반환을 청구할 수 있다":"변제비용은 채무자가 부담하고 채권자의 주소이전으로 늘면 채권자가 부담하며 변제자는 영수증과 채권증서 반환을 청구할 수 있어요.","변제한 가액에 비례하여 채권자와 함께 권리를 행사한다. 계약의 해지 또는 해제는 채권자만이 할 수 있다":"일부대위는 변제한 가액에 비례해 채권자와 함께 권리를 행사하고 해지·해제는 채권자만 할 수 있습니다.","변호사 아닌 자가 승소를 조건으로 소송당사자로부터 소송목적물 일부를 양도받기로 한 약정":"변호사 아닌 자가 승소를 조건으로 소송목적물 일부를 받기로 한 약정은 반사회질서 행위의 예예요.","병원의 입원환자 휴대품 도난 방지 보호의무":"병원은 입원환자의 휴대품이 도난당하지 않도록 보호할 의무를 신의칙상 집니다.","보전행위 이외의 권리를 행사한 때 채무자에게 통지하여야 한다. 채무자는 통지를 받은 후 그 권리를 처분하여도 채권자에게 대항하지 못한다":"보전행위 외의 권리를 대위 행사하면 채무자에게 통지해야 하고 통지 후 채무자의 처분은 채권자에게 대항하지 못해요.","보존ㆍ개량을 위하여 필요비 또는 유익비를 지출한 때 제203조에 의하여 경매대가에서 우선 상환받을 수 있다":"제삼취득자가 저당부동산에 쓴 필요비·유익비는 경매대가에서 먼저 돌려받을 수 있습니다.","보증계약 체결 시 알고 있는 주채무자의 채무 관련 신용정보를 보증인에게 알려야 한다. 체결 후 주채무자가 3개월 이상 이행하지 않거나 이행기에 이행할 수 없음을 미리 알거나 신용정보에 중대한 변화를 알게 된 때 지체 없이 알려야 한다. 보증인의 청구가 있으면 주채무의 내용 및 이행 여부를 알려야 한다. 위반하여 손해를 입히면 법원은 보증채무를 감경 또는 면제할 수 있다":"채권자는 보증 체결 시 아는 신용정보와 3개월 이상 불이행 등을 알려야 하고 어기면 법원이 보증채무를 감경·면제할 수 있습니다.","보증의 의사가 보증인의 기명날인 또는 서명이 있는 서면으로 표시되어야 효력이 발생한다. 전자적 형태의 의사표시는 효력이 없다. 보증채무를 불리하게 변경하는 경우에도 같다. 이행한 한도에서는 방식 하자를 이유로 무효를 주장할 수 없다":"보증은 보증인의 기명날인이나 서명이 있는 서면으로 표시되어야 하며 전자적 형태는 효력이 없고 이행한 한도에서는 방식 하자를 주장할 수 없습니다.","보증인은 주채무자가 이행하지 아니하는 채무를 이행할 의무가 있다. 장래의 채무에 대하여도 보증할 수 있다":"주채무자가 이행하지 않을 때 대신 이행할 의무를 지는 사람이 보증인이며 장래 채무도 보증할 수 있습니다.","보증인은 주채무자의 채권에 의한 상계로 채권자에게 대항할 수 있다. 주채무자가 채권자에 대하여 취소권ㆍ해제권ㆍ해지권이 있는 동안 보증인은 채무의 이행을 거절할 수 있다":"보증인은 주채무자의 채권으로 상계로 대항하고, 주채무자에게 취소·해제·해지권이 있는 동안 이행을 거절할 수 있어요.","보증인은 주채무자의 항변으로 채권자에게 대항할 수 있다. 주채무자의 항변포기는 보증인에게 효력이 없다":"보증인은 주채무자가 가진 항변을 채권자에게 내세울 수 있고 주채무자가 항변을 포기해도 보증인에게는 효력이 없습니다.","보증인이 주채무자에게 통지하지 않고 변제한 경우 주채무자가 채권자에게 대항할 수 있는 사유로 보증인에게 대항할 수 있다. 주채무자가 면책을 부탁받은 보증인에게 통지하지 않은 경우 보증인이 선의로 변제하면 보증인의 면책행위가 유효하다":"통지 없이 변제하면 주채무자가 채권자에게 댈 수 있던 사유로 보증인에게 대항하고, 선의 보증인의 면책행위는 유효합니다.","보증채무에서 주채무자의 기한이익 포기는 보증인에게 효력이 미치지 않는다":"보증채무에서 주채무자가 기한이익을 포기해도 그 효력은 보증인에게 미치지 않아요.","보험계약자가 다수의 보험계약으로 보험금을 부정취득할 목적으로 체결한 보험계약":"다수 보험계약으로 보험금을 부정 취득하려는 목적의 보험계약도 반사회질서에 해당합니다.","복대리인을 선임한 때 본인에 대하여 선임감독에 관한 책임이 있다. 본인의 지명에 의해 선임한 경우에는 복대리인의 부적임 또는 불성실함을 알고도 본인에게 통지하거나 해임하기를 태만한 때에 한하여 책임이 있다":"복대리인을 선임하면 선임·감독 책임이 있고, 본인이 지명한 경우에는 부적임을 알고도 통지·해임을 게을리한 때에만 책임을 집니다.","본래의 채권이 시효로 소멸한 경우 채권자는 시효완성 전의 그 채권에 대한 채무불이행을 이유로 계약을 해제할 수 없다":"본래 채권이 시효로 소멸했다면 시효완성 전 그 채권의 채무불이행을 이유로 계약을 해제할 수 없어요.","본인의 사망, 대리인의 사망ㆍ성년후견 개시ㆍ파산, 복대리인의 사망ㆍ성년후견 개시ㆍ파산, 대리인의 대리권 소멸. 본인의 특정후견 개시는 소멸사유가 아니다":"본인이나 대리인·복대리인의 사망·성년후견 개시·파산 등이 복대리권의 소멸사유이고, 본인의 특정후견 개시는 소멸사유가 아닙니다.","본인의 승낙이 있거나 부득이한 사유가 있는 때가 아니면 복대리인을 선임하지 못한다":"임의대리인은 본인의 승낙이 있거나 부득이한 사유가 있을 때만 복대리인을 선임할 수 있어요.","본인의 추인이 있을 때까지 본인이나 그 대리인에 대하여 철회할 수 있다. 계약 당시 상대방이 대리권 없음을 안 때에는 철회할 수 없다(선의만 철회). 악의라는 사실은 철회를 다투는 본인이 증명한다":"상대방은 본인의 추인이 있을 때까지 철회할 수 있으나 대리권 없음을 알았다면 철회하지 못하고 악의는 본인이 증명해요.","본인의 허락이 없으면 자기와 법률행위를 하거나 동일한 법률행위에 당사자 쌍방을 대리하지 못한다. 단 채무의 이행은 할 수 있다":"본인의 허락이 없으면 자기계약과 쌍방대리가 금지되지만 채무의 이행은 할 수 있어요.","본인이 무권대리인에게 추인한 경우 상대방이 그 사실을 알 때까지는 상대방이 철회할 수 있다":"본인이 무권대리인에게 추인한 사실을 상대방이 알기 전까지는 상대방이 계약을 철회할 수 있습니다.","부담부분은 균등한 것으로 추정한다":"연대채무자의 부담부분은 균등한 것으로 추정해요.","부당이득반환채무는 성립한 때부터 소멸시효가 진행한다(채권자가 이행을 청구한 때가 기산점이 아님)":"부당이득반환 채무는 채무가 생긴 순간부터 시효가 흐르고 청구한 때부터 흐르는 것이 아닙니다.","부당이득반환채무는 이행의 기한이 없는 채무로서 이행청구를 받은 때부터 지체책임이 있다(상당 기간 경과가 필요하지 않음)":"부당이득반환채무는 기한이 없는 채무라 이행청구를 받은 때부터 지체책임을 지며 상당 기간이 지나야 하는 것은 아닙니다.","부당이득반환채무의 소멸시효는 채무가 성립한 때부터 진행한다":"부당이득을 돌려줄 채무의 소멸시효는 그 채무가 성립한 때부터 흐르기 시작합니다.","부당이득은 법정채권이며 전형계약이 아니다":"부당이득은 법률의 규정에 따라 생기는 법정채권이며 전형계약이 아닙니다.","부당하게 과다한 세무사 보수 약정은 상당하다고 인정되는 범위의 보수액만 청구할 수 있다":"터무니없이 비싼 세무사 보수 약정은 상당하다고 인정되는 범위의 금액만 청구할 수 있어요.","부동산, 지상권, 전세권, 등록된 자동차, 광업권, 등기된 입목. 지역권은 저당권의 객체가 될 수 없다":"부동산, 지상권, 전세권, 등록자동차, 광업권, 등기된 입목은 저당권의 객체이고 지역권은 아닙니다.","부동산공사의 수급인은 보수에 관한 채권을 담보하기 위하여 그 부동산을 목적으로 한 저당권의 설정을 청구할 수 있다":"부동산공사의 수급인은 보수채권을 담보하려고 그 부동산에 저당권 설정을 청구할 수 있어요.","부동산매매로 인한 소유권이전등기청구권은 특별한 사정이 없는 한 권리의 성질상 양도가 제한되고 양도에 채무자의 승낙이나 동의를 요한다. 양도통지만으로는 채무자에게 대항할 수 없다":"부동산 매매로 인한 소유권이전등기청구권은 양도가 제한되어 채무자의 승낙이나 동의가 필요하고 통지만으로는 대항할 수 없습니다.","부동산 매매에서 시가에 관한 착오는 원칙적으로 법률행위 내용의 중요부분의 착오가 아니다":"부동산 매매에서 시가를 잘못 안 것은 원칙적으로 중요부분의 착오로 보지 않습니다.","부동산에 대한 압류 또는 가압류는 취득시효의 중단사유가 아니다":"압류나 가압류가 있어도 부동산 취득시효는 중단되지 않습니다.","부동산임차인은 반대약정이 없으면 임대인에 대하여 등기절차에 협력할 것을 청구할 수 있다. 등기한 때부터 제3자에 대하여 효력이 생긴다":"임차인은 반대약정이 없다면 임대인에게 임차권 등기절차에 협력하라고 요구할 수 있고 등기한 때부터 제삼자에게 효력이 생깁니다.","부부 중 한쪽이 다른 쪽에 대하여 가지는 권리는 혼인관계가 종료된 때부터 6개월 내에는 시효가 완성되지 않는다":"부부 한쪽의 다른 쪽에 대한 권리는 혼인관계가 끝난 때부터 6개월 내에는 시효가 완성되지 않습니다.","부수적 채무의 불이행을 이유로 해제하려면 그로 인하여 계약의 목적을 달성할 수 없거나 특별한 약정이 있어야 한다":"부수적 채무를 어겼다는 이유로 해제하려면 계약의 목적을 달성할 수 없거나 특별한 약정이 있어야 합니다.","부재자가 스스로 재산처분권을 위임한 재산관리인이 재산을 처분하는 데는 법원의 허가가 필요하지 않다(법원 선임 재산관리인과 구별)":"부재자가 직접 처분권을 맡긴 재산관리인은 법원이 선임한 관리인과 달리 처분에 법원 허가가 필요 없습니다.","부재자가 재산관리인을 정한 경우 생사가 분명하지 아니하면 법원은 재산관리인ㆍ이해관계인ㆍ검사의 청구에 의하여 재산관리인을 개임할 수 있다":"부재자가 정한 재산관리인이 있어도 생사가 불분명하면 법원이 청구에 따라 재산관리인을 바꿀 수 있어요.","부재자의 생사가 5년간 분명하지 아니한 때 법원은 이해관계인이나 검사의 청구에 의하여 실종선고를 하여야 한다":"보통실종은 생사가 5년간 분명하지 않을 때 이해관계인이나 검사의 청구로 법원이 선고합니다.","분묘기지권을 시효로 취득한 자는 토지소유자가 지료를 청구한 날부터 지료지급의무가 있다":"분묘기지권을 시효로 취득한 사람은 토지소유자가 지료를 청구한 날부터 지료를 내야 해요.","분사무소 설치는 주사무소 소재지에서 3주일 내에 등기한다 · 분사무소 소재지와 설치 연월일을 등기한다":"분사무소를 설치하면 주사무소 소재지에서 3주일 내에 소재지와 설치 연월일을 등기해요.","분할ㆍ일부양도로 공로에 통하지 못하게 된 토지의 소유자는 다른 분할자(양수인ㆍ양도인)의 토지를 통행할 수 있고 보상의 의무가 없다":"분할이나 일부양도로 공로에 통하지 못하게 되면 다른 분할자의 토지를 보상 없이 통행할 수 있습니다.","분할이 가능한 토지의 일부에도 유치권이 성립할 수 있다":"나눌 수 있는 토지는 그 일부에 대해서도 유치권이 성립할 수 있습니다.","불가분채무에는 연대채무 규정(제413조~제415조, 제422조, 제424조~제427조)과 제410조를 준용한다. 불가분채권이나 채무가 가분으로 변경된 때에는 각 채권자는 자기 부분만 청구하고 각 채무자는 자기 부담부분만 이행한다":"불가분채무에는 연대채무 규정을 준용하고 가분으로 변경되면 각자 자기 부분만 청구·이행합니다.","불공정한 법률행위는 추인에 의해서도 유효로 될 수 없다":"불공정한 법률행위는 추인해도 유효가 되지 않습니다.","불공정한 법률행위로서 무효인 법률행위는 추인에 의하여 유효로 될 수 없다":"불공정한 법률행위로 무효인 행위는 추인으로도 유효가 되지 않습니다.","불법도박채무에 대하여 양도담보의 명목으로 소유권이전등기를 해주는 것은 불법원인급여에 해당한다":"불법 도박빚의 대가로 양도담보 명목의 소유권이전등기를 해 주는 것은 불법원인급여입니다.","불법원인급여로 부당이득반환청구가 불가능한 경우 특별한 사정이 없는 한 불법의 원인에 가공한 상대방에게 불법행위에 의한 손해배상청구권도 행사할 수 없다":"불법원인급여로 반환청구가 안 되면 불법의 원인에 가공한 상대방에게 불법행위 손해배상청구권도 행사할 수 없습니다.","불법의 원인으로 재산을 급여하거나 노무를 제공한 때 이익의 반환을 청구하지 못한다. 불법원인이 수익자에게만 있는 때에는 반환을 청구할 수 있다":"불법의 원인으로 재산을 급여하면 반환을 청구하지 못하지만 불법원인이 수익자에게만 있으면 반환을 청구할 수 있어요.","불법행위능력은 이사 기타 대표자의 직무상 가해에 성립한다 · 타인에게 가한 손해를 배상하며 대표자 개인의 책임도 면하지 못한다":"법인의 불법행위능력은 이사나 대표자가 직무상 남에게 손해를 가했을 때 성립하고 대표자 개인의 책임도 남아요.","불법행위로 인한 손해배상청구권은 피해자나 법정대리인이 손해 및 가해자를 안 날부터 3년, 불법행위를 한 날부터 10년 내에 행사하지 않으면 소멸한다":"불법행위 손해배상 청구권은 손해와 가해자를 안 날부터 3년, 행위일부터 10년이 지나면 소멸합니다.","불확정기한부 채무는 채무자가 기한이 도래함을 안 때부터 지체책임이 있다":"불확정기한이 있는 채무는 채무자가 기한이 왔음을 알게 된 때부터 지체책임이 시작됩니다.","불확정한 다수의 채무에 대해서도 보증할 수 있되 최고액을 서면으로 특정하여야 한다. 최고액을 특정하지 않은 보증계약은 효력이 없다":"불확정한 다수의 채무도 보증할 수 있지만 최고액을 서면으로 특정해야 하고 특정하지 않으면 효력이 없어요.","불확정한 사실이 발생한 때를 이행기한으로 정한 경우":"불확정한 사실이 일어난 때를 이행기로 삼은 약정을 다루는 규정입니다.","비법인사단ㆍ재단은 대표자(관리인)로 민사소송 당사자가 될 수 있다 · 고유한 의미의 종중은 종중원이 임의로 탈퇴할 수 없다 · 공동주택 입주자대표회의는 동별 세대수 비례 선출 대표자 구성 사단이다":"비법인사단·재단은 대표자로 소송당사자가 될 수 있고, 종중원은 임의로 탈퇴할 수 없으며 입주자대표회의는 사단이에요.","비법인사단의 타인 간의 금전채무 보증은 총유물의 관리ㆍ처분이 아니다 · 총회 결의를 거치지 않았어도 계약은 유효하다 · 채권자대위권으로 대위행사할 때 내부 의사결정을 거칠 필요가 없다":"비법인사단이 타인 간 금전채무를 보증한 것은 총유물 관리·처분이 아니라서 총회 결의가 없어도 계약이 유효합니다.","비영리법인은 영리 아닌 사업을 목적으로 하는 사단·재단이다 · 학술ㆍ종교ㆍ자선ㆍ기예ㆍ사교 등이며 종교사업 사단도 허가(인가 아님) · 주무관청의 허가를 얻어 법인이 된다(허가주의)":"비영리법인은 영리 아닌 사업의 사단·재단으로, 주무관청 허가를 얻어 법인이 되는 허가주의를 따릅니다.","비용상환청구권, 차임감액청구권, 계약갱신청구권, 건물(지상물)매수청구권. 부속물매수청구권은 건물 임차인에게 인정된다":"토지임차인은 비용상환청구권, 차임감액청구권, 계약갱신청구권, 지상물매수청구권을 행사할 수 있고 부속물매수청구권은 건물 임차인의 권리입니다.","비진의 의사표시의 무효는 선의의 제3자에게 대항할 수 없다":"비진의표시가 무효로 되는 경우에도 선의의 제3자에게는 그 무효를 내세울 수 없습니다.","사기ㆍ강박 취소는 선의의 제3자에게 대항하지 못한다. 사기를 이유로 취소를 주장하는 자 쪽에서 제3자의 악의를 증명한다(제3자는 선의로 추정)":"사기·강박 취소는 선의의 제3자에게 대항하지 못하고, 제3자의 악의는 취소를 주장하는 쪽이 증명합니다.","사기나 강박에 의한 의사표시는 취소할 수 있다":"속임을 당하거나 협박을 받아 한 의사표시는 자유로운 판단이 아니므로 나중에 취소할 수 있습니다.","사기에 기한 취소권과 매도인의 하자담보책임이 경합하는 경우 기망당한 매수인은 사기를 이유로 취소할 수 있다":"사기 취소권과 하자담보책임이 경합하면 속은 매수인은 사기를 이유로 취소할 수 있습니다.","사기에 의한 매매계약의 취소는 상대방 있는 단독행위다":"사기를 이유로 매매계약을 취소하는 행위는 상대방이 있는 단독행위로 분류합니다.","사단법인 설립행위는 요식행위이다 · 설립자(2인 이상)가 정관을 작성해 기명날인한다 · 주무관청의 허가가 필요하다":"사단법인 설립은 2인 이상이 정관을 작성해 기명날인하고 주무관청의 허가를 받는 요식행위입니다.","사단법인 정관변경은 총사원 3분의 2 이상의 동의가 필요하다 · 정수에 관해 정관에 다른 규정이 있어도 그에 의한다 · 주무관청의 허가를 얻지 아니하면 효력이 없다":"사단법인의 정관변경은 총사원 3분의 2 이상 동의와 주무관청의 허가가 필요합니다.","사단법인 정관의 법적 성질은 계약이 아니라 자치법규다 · 정관의 규범적 의미와 다른 총회 결의 해석은 사원·법원을 구속하지 않는다":"사단법인 정관은 계약이 아닌 자치법규이므로 그 규범적 의미와 다른 총회 결의 해석은 사원과 법원을 구속하지 않습니다.","사단법인 정관의 필요적 기재사항 7가지다 · 목적, 명칭, 사무소 소재지, 자산, 이사 임면, 사원자격 득실 · 존립시기나 해산사유를 정하는 때 그 시기 또는 사유":"사단법인 정관에는 목적, 명칭, 사무소 소재지, 자산, 이사 임면, 사원자격 득실, 존립시기·해산사유(정한 때)를 적어야 해요.","사람은 19세로 성년에 이른다":"사람은 19세가 되면 성년에 이릅니다.","사람은 생존한 동안 권리와 의무의 주체가 된다":"권리능력은 사람이 살아 있는 동안 권리를 갖고 의무를 지는 자격이라는 말입니다.","사람의 유체ㆍ유골은 매장ㆍ관리ㆍ제사ㆍ공양의 대상이 되는 유체물이며, 분묘에 안치된 선조의 유체ㆍ유골은 제사주재자에게 승계된다":"사람의 유체와 유골은 매장·제사의 대상이 되는 유체물이며 분묘 안치 유골은 제사주재자에게 승계됩니다.","사망의 원인이 될 위난 후 시신 미발견이어도 사망으로 인정하는 제도. 강한 추정력이 있으나 반증으로 번복될 수 있다":"인정사망은 위난 뒤 시신이 없어도 사망으로 인정하는 제도로, 추정력은 강해도 반증으로 뒤집힐 수 있어요.","사망자 명의로 신청하여 이루어진 소유권이전등기는 특별한 사정이 없는 한 원인무효 등기다":"죽은 사람 이름으로 신청해 마친 이전등기는 특별한 사정이 없으면 원인 없는 무효 등기입니다.","사실상 권리의 존재나 권리행사 가능성을 알지 못하였다는 사유는 특별한 사정이 없는 한 소멸시효 진행을 방해하지 않는다":"권리의 존재나 행사 가능성을 몰랐다는 사정만으로는 시효 진행이 방해되지 않아요.","사실인 관습은 법률행위 당사자의 의사를 보충하는 효력이 있을 뿐이다":"사실인 관습은 당사자 의사가 불분명할 때 이를 보충해 줄 뿐 법적 구속력은 없습니다.","사용ㆍ수익권능이 영구적ㆍ대세적으로 포기된 소유권은 특별한 사정이 없는 한 허용될 수 없다":"사용·수익 권능이 영구적이고 대세적으로 포기된 소유권은 특별한 사정이 없으면 허용되지 않아요.","사용자의 근로자 안전 보호의무":"사용자는 근로자의 안전을 보호할 의무를 신의칙상 부담합니다.","사원권은 사원총회에서의 결의권이다":"사원권은 사원총회에서 결의에 참여하는 권리 같은 사단 구성원의 권리예요.","사적 자치 분야에서 임의규정에 관한 법률행위의 해석기준·재판의 자료가 된다":"사적 자치 영역에서 임의규정과 관련해 법률행위 해석의 기준이나 재판 자료로 쓰입니다.","사전구상에 응하는 주채무자는 자기를 면책하게 하거나 담보 제공을 청구하거나, 배상할 금액을 공탁하거나 담보를 제공하거나 보증인을 면책하게 하여 배상의무를 면할 수 있다":"사전구상에 응하는 주채무자는 면책 청구, 담보제공 청구, 공탁이나 담보제공, 보증인 면책으로 배상의무를 면할 수 있습니다.","사정변경의 원칙에서 ‘사정’은 계약의 기초가 된 객관적 사정이다":"사정변경에서 따지는 사정은 계약 성립의 바탕이 된 객관적 사정을 가리킵니다.","사회생활규범이 사회의 법적 확신으로 법적 규범으로 승인된 것이다":"사회생활규범이 사회의 법적 확신으로 법규범으로 승인되면 관습법이 성립합니다.","사회질서의 변화로 적용 시점의 전체 법질서에 반하게 되면 효력이 부정된다":"사회질서가 달라져 적용할 때의 전체 법질서에 어긋나면 그 관습법은 효력을 잃습니다.","사회통념상 대리권을 추단할 수 있는 직함이나 명칭 등의 사용을 승낙한 경우에는 대리권 수여의 표시가 있는 것으로 볼 수 있다":"대리권이 있다고 믿을 만한 직함이나 명칭의 사용을 허락했다면 대리권 수여의 표시로 볼 수 있습니다.","산모가 태아의 상해에 대비하여 체결한 상해보험계약":"산모가 태아의 상해에 대비해 든 상해보험계약은 반사회질서에 해당하지 않습니다.","상계권, 계약해제권ㆍ해지권, 법률행위 취소권, 매매의 일방예약완결권":"상계권, 해제권·해지권, 취소권, 매매의 일방예약완결권이 형성권에 해당합니다.","상계권을 청구권이라 하면 틀리다":"상계권은 일방적 의사표시로 효과가 생기는 형성권이므로 청구권이라고 하면 틀립니다.","상계에는 변제충당 규정(제476조~제479조)을 준용한다":"상계에도 변제충당 규정이 준용됩니다.","상계의 의사표시에는 조건이나 기한을 붙일 수 없다":"상계는 한 번의 의사표시로 끝나야 하므로 조건이나 기한을 붙이는 것이 허용되지 않습니다.","상당한 기간을 정하여 본인에게 추인 여부의 확답을 최고할 수 있다. 본인이 그 기간 내에 확답을 발하지 아니하면 추인을 거절한 것으로 본다. 최고권은 상대방의 선의ㆍ악의를 묻지 않는다":"상대방은 상당한 기간을 정해 본인에게 추인 여부를 최고할 수 있고 확답이 없으면 추인을 거절한 것으로 보며 상대방의 선의·악의는 묻지 않아요.","상당한 기간을 정하여 이행을 최고하고 그 기간 내에 이행하지 않으면 해제할 수 있다. 채무자가 미리 이행하지 않을 의사를 표시한 경우 최고를 요하지 않는다":"상당한 기간을 정해 이행을 최고하고 이행하지 않으면 해제할 수 있으며 채무자가 미리 이행 거절 의사를 밝히면 최고가 필요 없어요.","상당한 기간을 정하여 향수 여부의 확답을 제3자에게 최고할 수 있고 확답을 받지 못하면 거절한 것으로 본다":"채무자는 상당한 기간을 정해 제3자에게 향수 여부를 최고할 수 있고 확답이 없으면 거절한 것으로 봅니다.","상대방과 동일시할 수 있는 자(예: 매수인의 대리인)의 사기는 제3자의 사기가 아니다. 상대방의 단순한 피용자는 제3자에 해당한다":"매수인의 대리인처럼 상대방과 동일시할 수 있는 자의 사기는 제3자의 사기가 아니며 단순 피용자는 제3자입니다.","상대방과 통정한 허위의 의사표시는 무효다. 무효는 선의의 제3자에게 대항하지 못한다":"상대방과 짜고 한 허위 의사표시는 무효이며 선의의 제3자에게는 대항하지 못합니다.","상대방에 대하여 하지 아니하면 그 상대방에 대항하지 못한다. 상대방이 그 사실을 안 때에는 그러하지 아니하다":"추인이나 거절은 상대방에게 해야 대항할 수 있으며 상대방이 그 사실을 안 때에는 예외입니다.","상대방에 대한 의사표시로 하며 조건 또는 기한을 붙이지 못한다. 상계의 의사표시는 각 채무가 상계할 수 있는 때에 대등액에 관하여 소멸한 것으로 본다(소급효)":"상계는 상대방에 대한 의사표시로 하며 조건·기한을 붙일 수 없고 상계할 수 있는 때로 소급해 소멸한 것으로 봅니다.","상대방은 그 조건이 성취한 것으로 주장할 수 있다(방해 시점에 당연히 성취로 의제되는 것은 아니다)":"이때 상대방은 그 조건이 성취된 것으로 주장할 수 있을 뿐 당연히 성취로 간주되지는 않아요.","상대방은 성취하지 아니한 것으로 주장할 수 있다":"이때 상대방은 조건이 성취되지 않은 것으로 주장할 수 있어요.","상대방은 제한능력자가 능력자가 된 후 그에게 1개월 이상의 기간을 정해 추인 여부의 확답을 촉구할 수 있다. 능력자가 그 기간 내에 확답을 발송하지 않으면 추인한 것으로 본다":"상대방은 능력자가 된 제한능력자에게 1개월 이상 기간을 정해 추인 여부를 촉구할 수 있고, 답이 없으면 추인한 것으로 봅니다.","상대방이 무권대리인에게 가지는 계약의 이행 또는 손해배상청구권의 소멸시효는 상대방이 이를 선택할 수 있는 때(대리권 증명 불능ㆍ추인 거절 시)부터 진행한다":"무권대리인에 대한 이행·손해배상청구권의 시효는 상대방이 선택할 수 있게 된 때부터 진행합니다.","상대방이 의사표시를 받은 때 제한능력자이면 의사표시자는 의사표시로써 대항할 수 없다. 그 상대방의 법정대리인이 도달 사실을 안 후에는 그러하지 아니하다":"상대방이 제한능력자일 때는 의사표시로 대항할 수 없으나 법정대리인이 도달 사실을 안 후에는 대항할 수 있어요.","상대방이 이해한 바에 따른 객관적 해석이다":"규범적 해석은 상대방이 이해한 바를 기준으로 하는 객관적 해석이에요.","상대방이 표의자의 진의 아님을 알았거나 알 수 있었을 경우에는 무효다. 무효는 선의의 제3자에게 대항하지 못한다":"진의 아님을 상대방이 알았거나 알 수 있었던 경우에는 표시가 무효이며 선의 제3자에겐 주장하지 못합니다.","상대방이 표의자의 착오를 알고 이용한 경우에는 표의자에게 중대한 과실이 있어도 취소할 수 있다":"상대방이 착오를 알고 이용했다면 표의자의 중대한 과실이 있어도 취소권을 잃지 않습니다.","상대방 있는 의사표시는 상대방에게 도달한 때에 효력이 생긴다(도달주의)":"의사표시는 보낸 때가 아니라 상대방에게 닿은 때에 효력이 생깁니다.","상대방 있는 의사표시에 관하여 제3자가 사기나 강박을 행한 경우 상대방이 그 사실을 알았거나 알 수 있었을 경우에 한하여 취소할 수 있다":"제삼자가 속이거나 겁을 준 경우에는 상대방이 그 사실을 알았거나 알 수 있었을 때에만 취소할 수 있습니다.","상대방 있는 의사표시에 적용된다":"규범적 해석은 상대방이 있는 의사표시에 적용됩니다.","상속의 포기(상대방 없음) 등":"상속의 포기도 상대방이 없는 단독행위의 예예요.","상속인의 확정, 관리인의 선임 또는 파산선고가 있는 때부터 6월 내에는 시효가 완성하지 않는다":"상속재산에 관한 권리는 상속인 확정, 관리인 선임, 파산선고 때부터 6월 내에는 시효가 완성하지 않아요.","상속회복청구권, 지상권갱신청구권이 이에 속한다":"상속회복청구권과 지상권갱신청구권도 청구권에 속합니다.","상속회복청구권, 지상권자의 지상권갱신청구권이다":"상속회복청구권과 지상권갱신청구권도 형성권이 아닌 청구권이에요.","상환무자력자의 부담부분은 구상권자 및 다른 자력 있는 채무자가 부담부분에 비례하여 분담한다. 구상권자에게 과실이 있으면 분담을 청구하지 못한다":"상환무자력자의 부담부분은 구상권자와 자력 있는 채무자들이 부담부분 비율로 나누며 구상권자 과실이 있으면 청구하지 못합니다.","석조 건물 소유를 목적으로 하는 지상권의 존속기간은 ‘최장 30년으로 제한’되는 것이 아니라 최단 30년이다":"석조 건물 지상권의 30년은 최장 제한이 아니라 최단 기간이에요.","선량한 관리자의 주의로 점유한다. 채무자의 승낙 없이 유치물을 사용ㆍ대여ㆍ담보제공하지 못한다(보존에 필요한 사용 제외). 위반 시 채무자는 소멸을 청구할 수 있다. 소유자 승낙 없이 임대한 경우 임차인의 점유는 소유자에게 대항할 수 없다":"유치권자는 선량한 관리자의 주의로 점유하고 승낙 없이 사용·대여·담보제공을 못하며 위반하면 채무자가 소멸을 청구할 수 있어요.","선량한 풍속 기타 사회질서에 위반한 사항을 내용으로 하는 법률행위는 무효로 한다":"사회가 받아들일 수 없는 내용을 담은 법률행위는 처음부터 효력이 없습니다.","선의의 매수인은 사실을 안 날부터, 악의의 매수인은 계약한 날부터 1년 내에 행사하여야 한다":"이 권리의 행사기간은 선의 매수인은 안 날부터, 악의 매수인은 계약한 날부터 1년입니다.","선의의 점유자는 점유물의 과실을 취득한다. 악의의 점유자는 수취한 과실을 반환하고 소비ㆍ훼손하거나 수취하지 못한 경우 그 대가를 보상한다. 폭력 또는 은비에 의한 점유자에 준용한다":"선의 점유자는 과실을 취득하고 악의 점유자는 수취한 과실을 반환하며 소비·훼손한 때에는 대가를 보상해요.","선의 제3자 보호 규정이 없어 절대적 무효다":"선의 제3자를 보호하는 규정이 없기 때문에 이 무효는 절대적입니다.","선의취득(제249조~제251조)과 유치권 규정(제321조~제325조)을 동산질권에 준용한다":"동산질권에는 선의취득과 유치권 규정이 준용됩니다.","선택권 행사의 기간이 있는데 선택권자가 그 기간 내에 선택하지 않으면 상대방은 상당한 기간을 정하여 선택을 최고할 수 있고, 그 기간 내에 선택하지 않으면 선택권은 상대방에게 있다(즉시 이전되는 것이 아니다). 기간이 없는 경우에는 채권의 기한 도래 후 같은 방식이다":"선택권자가 기간 내에 선택하지 않으면 상대방이 최고할 수 있고 그래도 선택하지 않으면 선택권이 상대방에게 넘어가며 즉시 넘어가는 것은 아닙니다.","선택의 효력은 채권이 발생한 때에 소급한다. 제3자의 권리를 해하지 못한다":"선택의 효력은 채권이 발생한 때로 소급하지만 제3자의 권리를 해치지 못해요.","선택채권은 선택권을 행사할 수 있을 때부터 진행한다":"선택채권은 선택권을 행사할 수 있을 때부터 소멸시효가 진행해요.","선택채권의 소멸시효는 선택권을 행사할 수 있을 때부터 진행한다":"선택채권의 소멸시효는 선택권을 행사할 수 있게 된 때부터 흐르기 시작합니다.","선택할 수개의 행위 중 처음부터 불능한 것이나 후에 이행불능이 된 것이 있으면 채권의 목적은 잔존한 것에 존재한다. 선택권 없는 당사자의 과실로 불능이 된 때는 적용하지 않는다":"선택할 행위 중 불능인 것이 있으면 채권의 목적은 남은 것에 존재하지만 선택권 없는 당사자의 과실로 불능이 되면 적용하지 않습니다.","설립자가 명칭, 사무소 소재지, 이사 임면 방법을 정하지 않고 사망한 때 · 이해관계인 또는 검사의 청구로 법원이 정한다":"설립자가 이사 임면 방법 등을 정하지 않고 죽으면 이해관계인이나 검사의 청구로 법원이 정합니다.","설립허가가 있는 때 3주간 내에 설립등기를 하여야 한다 · 주된 사무소 소재지에서 등기한다 · 등기기간은 허가서가 도착한 날부터 기산한다":"설립허가가 나면 3주간 안에 주된 사무소 소재지에서 설립등기를 하며, 기간은 허가서 도착일부터 셉니다.","설정자가 제450조에 의하여 제3채무자에게 통지하거나 제3채무자가 승낙하여야 제3채무자 기타 제3자에게 대항할 수 있다":"지명채권질권은 설정자가 제3채무자에게 통지하거나 제3채무자가 승낙해야 제3자에게 대항할 수 있습니다.","설정자의 책임 있는 사유로 저당물의 가액이 현저히 감소된 때 저당권자는 원상회복 또는 상당한 담보제공을 청구할 수 있다. 저당목적물을 권한 없이 멸실ㆍ훼손하거나 담보가치를 감소시키는 행위는 불법행위가 될 수 있다":"설정자 책임으로 저당물 가액이 크게 줄면 원상회복·담보제공을 청구할 수 있고 담보가치를 줄이는 행위는 불법행위일 수 있습니다.","성년후견개시 청구가 있더라도 가정법원은 필요하다면 한정후견을 개시할 수 있다":"성년후견을 청구받은 법원이라도 필요하면 더 가벼운 한정후견으로 개시할 수 있습니다.","소를 제기하여 계약해제권을 행사한 후 나중에 소송을 취하해도 해제권 행사의 효력에는 영향이 없다":"소로 해제권을 행사한 뒤 소송을 취하해도 이미 한 해제의 효력은 그대로 유지됩니다.","소멸시효는 권리를 행사할 수 있는 때로부터 진행한다. 부작위를 목적으로 하는 채권은 위반행위를 한 때부터 진행한다(계약체결 시부터가 아님)":"소멸시효는 권리를 행사할 수 있는 때부터 진행하며 부작위 채권은 위반행위를 한 때부터 진행합니다.","소멸시효는 그 기산일에 소급하여 효력이 생긴다":"시효가 완성되면 처음 시효가 시작된 날로 거슬러 올라가 권리가 사라진 것으로 봅니다.","소멸시효 완성된 채권도 완성 전에 상계할 수 있었던 것이면 채권자는 상계할 수 있다":"채권이 시효로 소멸했어도 시효 전에 상계할 수 있었다면 채권자가 이를 이용해 상계할 수 있습니다.","소멸시효의 이익은 미리 포기하지 못한다. 소멸시효는 법률행위로 배제ㆍ연장ㆍ가중할 수 없으나 단축 또는 경감할 수 있다":"소멸시효 이익은 미리 포기할 수 없고, 시효는 법률행위로 배제·연장·가중할 수 없지만 단축·경감할 수는 있어요.","소멸시효 이익의 포기는 시효완성의 이익을 받을 당사자가 해야 한다. 당사자나 대리인이 아닌 제3자가 한 포기는 이익을 받을 자에게 효력이 없다. 가분채무의 일부에 대하여도 포기할 수 있다":"시효이익의 포기는 이익을 받을 당사자가 해야 하며 제3자가 한 포기는 효력이 없고 가분채무의 일부에 대해서도 할 수 있습니다.","소수지분권자가 협의 없이 공유물 일부를 독점 사용하는 경우 다른 소수지분권자는 보존행위로서 공유물의 인도를 청구할 수 없다":"소수지분권자가 일부를 독점해도 다른 소수지분권자가 보존행위라며 인도를 청구할 수는 없습니다.","소유권에 기한 물권적 청구권은 소멸시효의 대상이 아니다":"소유권에서 나오는 물권적 청구권은 시효로 소멸하지 않는 권리입니다.","소유권을 방해하는 자에 대하여 방해의 제거를 청구할 수 있고, 방해할 염려 있는 행위를 하는 자에 대하여 예방이나 손해배상의 담보를 청구할 수 있다":"소유권을 방해하는 자에게는 방해제거를, 방해할 염려가 있는 자에게는 예방이나 담보를 청구할 수 있습니다.","소유권을 상실한 전소유자는 제3자인 불법점유자에 대하여 소유권에 기한 물권적 청구권을 행사할 수 없다":"소유권을 잃은 전소유자는 더 이상 소유권에 기한 청구를 불법점유자에게 할 수 없습니다.","소유권이전등기를 마치지 않은 매수인(미등기 건물의 매수인 포함)은 직접 소유권에 기한 방해제거ㆍ반환청구를 할 수 없다":"이전등기를 못 마친 매수인은 미등기 건물의 매수인도 직접 소유권에 기해 방해제거나 반환을 청구하지 못합니다.","소유권이전등기명의자는 그 전소유자에 대하여 적법한 등기원인에 의해 소유권을 취득한 것으로 추정된다(등기의 추정력)":"소유권이전등기 명의자는 전소유자에 대하여 적법한 등기원인으로 취득한 것으로 추정됩니다.","소유권이전등기청구권, 전세금반환채권, 유익비상환청구권":"등기를 이전해 달라는 권리, 전세금 돌려받을 채권, 유익비 상환 권리가 청구권의 예입니다.","소유권이전등기청구권의 소멸시효기간이 지난 사실을 알고 있는 등기의무자가 소유권이전등기를 해 주기로 약정한 경우 특별한 사정이 없는 한 시효이익의 포기로 본다":"시효기간이 지난 사실을 아는 등기의무자가 등기해 주기로 약정하면 특별한 사정이 없는 한 시효이익을 포기한 것으로 봅니다.","소유자는 그 소유에 속한 물건을 점유한 자에 대하여 반환을 청구할 수 있다. 점유자가 점유할 권리가 있으면 반환을 거부할 수 있다":"소유자는 자기 물건을 점유한 자에게 반환을 청구할 수 있으나 점유할 권리가 있는 자는 반환을 거부할 수 있어요.","소유자는 법률의 범위 내에서 소유물을 사용, 수익, 처분할 권리가 있다":"소유권의 내용은 법이 허용하는 범위에서 물건을 쓰고 이익을 얻고 처분하는 권능입니다.","소유자와 동일한 지배를 사실상 행사하려는 의사(사실상 소유할 의사)를 가지고 하는 점유. 점유취득의 원인이 된 권원의 성질이나 점유와 관계있는 모든 사정에 의하여 외형적ㆍ객관적으로 결정한다":"자주점유는 소유자처럼 지배하려는 의사로 하는 점유이며 권원의 성질과 모든 사정으로 객관적으로 정해집니다.","소유자의 대리인으로부터 토지를 적법하게 매수하였다면, 이전등기가 위조서류로 마쳐졌더라도 실체관계에 부합하면 등기는 유효하다":"위조서류로 이전등기가 마쳐졌어도 실체관계에 부합하면 그 등기는 유효합니다.","소유자의 소유물반환청구에 대하여 유치권을 항변하면 법원은 상환이행판결(채권 변제와 동시에 인도)을 한다":"소유자의 반환청구에 유치권을 항변하면 법원은 채권 변제와 동시에 인도하라는 상환이행판결을 해요.","소유지의 물을 소통하기 위하여 이웃 토지소유자가 시설한 공작물을 사용할 수 있다. 이익 비율로 설치ㆍ보존 비용을 분담한다. 여수급여청구권: 물을 얻기 곤란한 때 보상하고 여수의 급여를 청구할 수 있다":"이웃이 시설한 유수용 공작물을 쓸 수 있고 이익 비율로 비용을 분담하며, 물이 부족하면 보상하고 여수의 급여를 청구할 수 있어요.","소음이 사회통념상 수인한도를 넘지 않으면 소유권에 기하여 소음피해의 제거를 청구할 수 없다":"소음이 참을 수 있는 한도를 넘지 않으면 소유권을 근거로 소음 제거를 요구할 수 없습니다.","소집은 1주간 전에 목적사항을 기재한 통지를 발한다 · 기타 정관에 정한 방법에 의한다 · 통지는 발송하면 되고 도달은 필요 없다":"총회 소집은 1주간 전에 목적사항을 적은 통지를 발송하면 되고 도달할 필요는 없어요.","손해가 고의 또는 중대한 과실에 의한 것이 아니고 배상으로 배상자의 생계에 중대한 영향을 미치게 될 경우 법원에 경감을 청구할 수 있다":"고의나 중과실이 아닌 손해로 배상 때문에 생계가 크게 흔들리면 배상액을 줄여 달라고 법원에 청구할 수 있습니다.","손해배상액은 법정이율에 의한다. 법령의 제한에 위반하지 않는 약정이율이 있으면 그 이율에 의한다. 채권자는 손해의 증명을 요하지 않고 채무자는 과실 없음을 항변하지 못한다":"금전채무 불이행은 법정이율, 약정이율이 있으면 그 이율로 배상하며 채권자는 손해 증명이 필요 없고 채무자는 과실 없음을 항변하지 못해요.","손해배상의 범위·방법·과실상계·손해배상자 대위는 채무불이행 규정(제393조, 제394조, 제396조, 제399조)을 준용한다":"손해배상의 범위·방법·과실상계·손해배상자 대위는 채무불이행 규정을 준용해요.","수급인은 특약 등 특별한 사정이 없는 한 제3자를 사용하여 일을 완성할 수 있다(직접 완성할 필요 없음)":"수급인은 특약 등 특별한 사정이 없으면 제3자를 사용해 일을 완성할 수 있습니다.","수급인이 담보책임이 없음을 약정한 경우에도 알고 고지하지 아니한 사실에 대하여는 책임을 면하지 못한다":"수급인이 담보책임이 없다고 약정해도 알면서 알리지 않은 사실은 책임을 면하지 못합니다.","수급인이 미리 계약을 이행하지 않을 의사를 표시한 경우 도급인은 최고 없이 해제할 수 있다":"수급인이 미리 이행하지 않겠다고 밝히면 도급인은 최고 없이 해제할 수 있습니다.","수급인이 일을 완성하기 전에는 도급인은 손해를 배상하고 계약을 해제할 수 있다":"일이 끝나기 전에는 도급인이 손해만 물어 주면 이유 없이도 계약을 해제할 수 있어요.","수량을 지정한 매매의 목적물이 부족되거나 일부가 계약 당시 이미 멸실: 매수인이 부족 또는 멸실을 알지 못한 때 제572조·제573조를 준용한다":"수량 지정 매매에서 수량이 부족하거나 일부가 이미 멸실되었는데 매수인이 몰랐다면 일부 타인 권리 매매 규정을 준용해요.","수령자가 배액을 제공하면 족하고 상대방이 수령하지 않는다고 해서 공탁까지 해야 하는 것은 아니다":"배액상환 해제에서 수령자는 배액을 제공하면 되고 상대방이 받지 않아도 공탁까지 할 필요는 없어요.","수익자가 받은 목적물을 반환할 수 없는 때 그 가액을 반환하여야 한다. 수익자로부터 무상으로 이익의 목적물을 양수한 악의의 제3자도 반환할 책임이 있다":"받은 목적물을 반환할 수 없으면 그 가액을 반환해야 하고 무상으로 양수한 악의의 제3자도 반환할 책임이 있어요.","수익자가 부당이득을 얻기 위하여 지출한 비용은 반환할 이득의 범위에서 공제된다":"부당이득을 얻으려고 수익자가 쓴 비용은 반환할 이득의 범위에서 공제됩니다.","수익자가 이익을 받은 후 법률상 원인 없음을 안 때 ‘그때부터’ 악의의 수익자로서 반환책임을 진다. 선의의 수익자가 패소한 때에는 소를 제기한 때부터 악의로 본다":"이익을 받은 후 원인이 없음을 안 때부터 악의의 수익자가 되고 선의 수익자가 패소하면 소 제기 때부터 악의로 봅니다.","수인의 보증인이 각자의 행위로 보증채무를 부담한 경우에도 제408조(균등 분할)를 적용한다":"여러 보증인이 각자 행위로 보증하더라도 균등 분할 규정을 적용합니다.","수인의 채무자가 채무 전부를 각자 이행할 의무가 있고 1인의 이행으로 다른 채무자도 의무를 면하는 채무":"연대채무는 여러 채무자가 각자 전부를 이행할 의무를 지고 한 명의 이행으로 모두 면책되는 채무예요.","수인이 공동의 불법행위로 타인에게 손해를 가한 때 연대하여 배상할 책임이 있다. 공동 아닌 수인의 행위 중 어느 자의 행위가 손해를 가한 것인지 알 수 없는 때에도 같다. 교사자나 방조자는 공동행위자로 본다":"여럿이 공동으로 불법행위를 하면 연대하여 배상하고 누구 행위가 손해를 냈는지 알 수 없어도 같으며 교사자와 방조자는 공동행위자로 봅니다.","수인이 한 채의 건물을 구분하여 각각 일부분을 소유한 때 건물과 그 부속물 중 공용하는 부분은 공유로 추정한다. 공용부분의 보존 비용 기타 부담은 각자의 소유부분의 가액에 비례하여 분담한다":"구분소유한 건물의 공용부분은 공유로 추정하고 보존비용 등은 각자 소유부분의 가액에 비례해 분담해요.","순위는 설정의 선후에 의한다. 피담보채권의 범위: 원본, 이자, 위약금, 질권실행비용, 질물보존비용, 채무불이행 또는 질물의 하자로 인한 손해배상(다른 약정 있으면 그에 의함)":"질권의 순위는 설정의 선후에 따르며 피담보채권에는 원본, 이자, 위약금, 실행·보존 비용, 손해배상이 포함됩니다.","시가 300만원 상당 물품을 100만원에 매수한 행위(의무를 부담)":"시가보다 훨씬 싼 값이어도 대금 지급이라는 의무를 지는 매수 행위는 미성년자가 단독으로 취소할 수 있어요.","시기(始期) 있는 법률행위는 기한이 도래한 때로부터 효력이 생긴다":"시기가 붙은 법률행위는 기한이 도래한 때부터 효력이 생깁니다.","시효완성 당시에는 일반재산이었으나 완성 후 행정재산으로 변경된 경우 국가를 상대로 시효완성을 원인으로 한 소유권이전등기를 청구할 수 없다":"시효완성 후 행정재산으로 바뀐 경우에는 국가를 상대로 소유권이전등기를 청구할 수 없습니다.","시효완성 당시의 소유자는 시효완성자가 등기를 마치지 않았더라도 부동산의 점유로 인한 부당이득반환 청구나 불법점유임을 이유로 한 인도 청구를 할 수 없다. 시효완성자가 등기이전을 청구하더라도 점유로 인한 부당이득반환의무를 지지 않는다":"시효완성 당시의 소유자는 시효완성자가 등기 전이어도 부당이득반환이나 인도를 청구할 수 없고 시효완성자도 점유로 인한 부당이득반환의무가 없어요.","시효완성 당시의 점유자로부터 점유를 양수한 현 점유자는 전 점유자의 시효완성 효과를 주장하여 직접 자기에게 소유권이전등기를 청구할 수 없다(전 점유자의 청구권을 대위·양도받아야 함)":"점유를 양수한 현 점유자는 전 점유자의 시효완성 효과를 주장해 직접 자기에게 이전등기를 청구할 수 없습니다.","시효완성을 알고 있는 소유자가 부동산을 선의의 제3자에게 처분하여 이전등기를 마친 경우 소유자는 시효완성자에게 불법행위로 인한 손해배상책임을 진다(채무불이행 아님)":"시효완성을 알면서 선의 제3자에게 처분한 소유자는 시효완성자에게 불법행위 손해배상책임을 집니다.","시효완성 전 채무의 일부 변제는 채무 승인의 효력은 있으나 채무 전부에 관한 시효이익 포기의 효력은 없다":"시효가 끝나기 전 채무 일부를 갚으면 승인은 되지만 채무 전체의 시효이익을 포기한 것은 아닙니다.","시효 완성 후 등기 전에 소유자가 저당권을 설정한 경우 시효완성자는 저당권의 부담 있는 소유권을 취득한다":"시효 완성 후 등기 전에 소유자가 설정한 저당권의 부담을 지고 소유권을 취득해요.","시효완성 후 소멸시효가 완성된 채권도 완성 전에 상계할 수 있었던 것이면 채권자는 상계할 수 있다":"시효가 지난 채권도 그전에 상계할 수 있던 상태였다면 채권자가 상계로 쓸 수 있습니다.","시효완성 후 채무를 승인하였다고 곧바로 시효이익을 포기한 것으로 간주되지는 않는다(시효완성 사실을 알고 한 것으로 추정되는 정도)":"시효 후 채무를 승인했다고 바로 이익을 포기했다고 보지 않고, 완성 사실을 알고 한 것으로 추정할 뿐입니다.","시효이익의 포기는 특별한 사정이 없는 한 시효완성 당시의 진정한 소유자에 대하여 하여야 한다. 원인무효 등기의 등기부상 소유명의자에게 한 포기는 효력이 없다":"시효이익의 포기는 시효완성 당시의 진정한 소유자에게 해야 하고 원인무효 등기 명의자에게 한 포기는 효력이 없습니다.","시효중단의 효력 있는 승인에는 상대방의 권리에 관한 처분의 능력이나 권한 있음을 요하지 않는다. 승인은 의사표시가 아니라 관념의 통지이며 묵시적으로도 할 수 있다":"승인은 의사표시가 아닌 관념의 통지이며 묵시적으로도 할 수 있고 처분능력이나 권한이 필요 없어요.","시효 진행이 개시되기 전의 승인은 시효중단의 효력이 없다":"시효 진행이 시작되기 전에 한 승인은 시효중단 효력이 없어요.","식목·채염 또는 석조·석회조·연와조 등 건축 목적의 토지 임대차 10년, 기타 토지 5년, 건물 기타 공작물 3년, 동산 6월. 갱신은 기간 만료 전 토지 1년, 건물 3월, 동산 1월 내에 하여야 한다":"처분권한 없는 자의 단기임대차 한도는 건축 목적 토지 10년, 기타 토지 5년, 건물 3년, 동산 6월이고 갱신은 만료 전 기간 내에 합니다.","신고기간 내 변제 금지, 지연손해배상 의무 면하지 못함 · 변제기 전 채권도 변제할 수 있다 · 가액 불확정 채권은 감정인의 평가에 의한다":"신고기간 내 변제는 금지되지만 지연손해배상 의무는 면하지 못하고, 변제기 전 채권도 변제할 수 있습니다.","신의칙은 권리의 행사와 의무의 이행을 신의에 좇아 성실히 하라는 원칙이다":"신의칙은 권리를 행사하고 의무를 이행할 때 신의에 따라 성실히 하라는 원칙이에요.","신의칙은 사법관계에만 적용되지 않고 공법관계에도 적용된다":"신의칙의 적용 범위는 사인 간 관계만이 아니라 국가와 국민 사이의 공법관계에도 미칩니다.","신채무가 원인의 불법 또는 당사자가 알지 못한 사유로 성립하지 않거나 취소된 때 구채무는 소멸되지 않는다. 구채무의 담보는 목적 한도에서 신채무의 담보로 할 수 있으나 제3자 제공 담보는 승낙이 필요하다":"신채무가 불법 등으로 성립하지 않거나 취소되면 구채무는 소멸하지 않고 구채무 담보는 목적 한도에서 신채무 담보로 쓸 수 있어요.","신축건물의 소유권이 수급인에게 있는 경우의 공사대금 채권, 부동산 매도인의 매매대금 채권(매수인에 대한 유치권 행사 불가), 임대차보증금반환채권(임차건물에 관하여 생긴 채권이 아님), 불법행위로 인한 점유":"수급인 소유 신축건물의 공사대금, 매도인의 매매대금, 임대차보증금반환채권, 불법행위로 인한 점유는 유치권이 성립하지 않아요.","실종선고가 있더라도 당사자가 생존하는 한 권리능력은 상실되지 않는다":"실종선고를 받아도 당사자가 살아 있는 한 권리능력은 없어지지 않습니다.","실종선고를 받은 자가 종전 주소에서 새로운 법률행위를 하는 데 실종선고의 취소는 필요하지 않다. 생존하는 한 권리능력이 있다":"실종선고를 받아도 살아 있는 한 권리능력이 있어, 종전 주소에서 새 법률행위를 하는 데 선고 취소가 필요 없어요.","실종선고를 받은 자는 실종기간이 만료한 때에 사망한 것으로 본다(선고 시가 아님)":"실종선고를 받은 사람은 선고 시점이 아니라 실종기간이 만료한 때에 사망한 것으로 봅니다.","실종선고를 직접원인으로 재산을 취득한 자가 선의면 현존이익 한도로, 악의면 받은 이익에 이자를 붙이고 손해가 있으면 배상한다":"실종선고를 직접 원인으로 재산을 얻은 사람은 선의면 현존이익, 악의면 이자와 손해배상까지 돌려줘야 해요.","실종자의 생존 또는 다른 시기의 사망 사실의 증명이 있으면 법원은 본인ㆍ이해관계인ㆍ검사의 청구로 취소하여야 한다. 실종선고 후 취소 전에 선의로 한 행위의 효력에는 영향이 없다":"실종자의 생존이나 다른 시기의 사망이 증명되면 법원이 취소해야 하며, 선고 후 취소 전에 선의로 한 행위는 영향이 없습니다.","심신상실 중에 타인에게 손해를 가한 자는 배상책임이 없다. 고의 또는 과실로 심신상실을 초래한 때에는 책임이 있다":"심신상실 중에 손해를 가한 자는 책임이 없지만 고의나 과실로 심신상실을 초래했다면 책임이 있습니다.","쌍무계약의 당사자 일방은 상대방이 그 채무이행을 제공할 때까지 자기의 채무이행을 거절할 수 있다. 상대방의 채무가 변제기에 있지 않은 때는 제외. 선이행 의무자도 상대방의 이행이 곤란할 현저한 사유가 있으면 거절할 수 있다":"쌍무계약의 당사자는 상대방이 이행을 제공할 때까지 이행을 거절할 수 있고 선이행 의무자도 상대방 이행이 곤란할 현저한 사유가 있으면 거절합니다.","쌍무계약의 당사자 일방의 채무가 당사자 쌍방의 책임 없는 사유로 이행할 수 없게 된 때 채무자는 상대방의 이행(반대급부)을 청구하지 못한다":"쌍방 책임 없는 사유로 한쪽 채무가 불능이 되면 채무자는 반대급부를 청구하지 못하는 채무자위험부담주의입니다.","쌍방이 X토지를 목적물로 삼았으나 계약서에 착오로 Y토지를 기재한 경우다":"쌍방이 X토지를 목적으로 삼았는데 계약서에 착오로 Y토지를 적은 경우의 예예요.","쌍방이 서로 같은 종류를 목적으로 한 채무를 부담하고 쌍방 채무의 이행기가 도래한 때 대등액에 관하여 상계할 수 있다. 채무의 성질이 허용하지 않으면 제외. 당사자가 다른 의사를 표시한 경우 적용하지 않으나 선의의 제3자에게 대항하지 못한다":"같은 종류의 채무를 서로 지고 이행기가 모두 오면 대등액을 상계하며 성질상 불가하거나 합의로 배제 가능하나 선의 제3자에게는 대항 못 합니다.","아직 능력자가 되지 못한 경우에는 법정대리인에게 촉구할 수 있다. 법정대리인이 기간 내에 확답을 발송하지 않으면 추인한 것으로 본다. 상대방이 계약 당시 제한능력자임을 알았더라도 확답 촉구는 할 수 있다":"아직 능력자가 되지 않았다면 법정대리인에게 촉구하며, 계약 당시 제한능력자임을 알았어도 촉구는 가능합니다.","아파트 분양자의 단지 인근 공동묘지 사실 고지의무":"아파트 분양자는 단지 가까이에 공동묘지가 있다는 사실을 알려야 할 의무가 있어요.","압류ㆍ가압류ㆍ가처분은 권리자의 청구에 의하거나 법률 규정에 따르지 않아 취소된 때 중단 효력이 없다. 시효의 이익을 받은 자에 대하여 하지 아니한 때에는 그에게 통지한 후가 아니면 중단 효력이 없다":"압류·가압류·가처분이 취소되거나 시효의 이익을 받는 자에게 통지가 없으면 중단 효력이 생기지 않습니다.","양도금지특약을 위반하여 채권을 양도한 경우 양수인이 특약을 과실 없이 알지 못하였다면(중대한 과실이 없다면) 양도는 유효하다. 양수인이 경과실로 특약을 알지 못한 경우에도 양수금을 청구할 수 있다":"양도금지특약을 어기고 양도해도 양수인이 특약을 중대한 과실 없이 몰랐다면 양도는 유효하고 양수금을 청구할 수 있어요.","양도소득세 일부를 회피할 목적으로 계약서에 실제보다 낮은 금액을 대금으로 기재한 매매계약(다운계약서)":"양도소득세 일부를 피하려고 계약서에 낮은 금액을 적은 다운계약서도 반사회질서가 아닙니다.","양도소득세 회피를 목적으로 한 명의신탁약정은 이 법에 의하여 무효가 될 뿐 반사회질서 법률행위가 아니다":"양도소득세 회피 목적의 명의신탁은 이 법으로 무효가 될 뿐 반사회질서 법률행위는 아닙니다.","양도소득세 회피 목적의 명의신탁약정, 양도소득세 회피 및 투기 목적의 미등기 전매":"양도소득세를 피하려는 명의신탁이나 미등기 전매는 반사회질서에 해당하지 않아요.","양도인이 채무자에게 양도를 통지한 때 아직 양도하지 않았거나 양도가 무효인 경우에도 선의인 채무자는 양수인에게 대항할 수 있는 사유로 양도인에게 대항할 수 있다. 통지는 양수인의 동의가 없으면 철회하지 못한다":"양도 안 했거나 무효인데 통지했어도 선의 채무자는 양수인에게 한 사유로 양도인에게 대항할 수 있고 통지는 양수인 동의 없이 철회 못 합니다.","양도인이 채무자에게 통지하거나 채무자가 승낙하지 않으면 채무자 기타 제3자에게 대항하지 못한다. 통지나 승낙은 확정일자 있는 증서에 의하지 않으면 채무자 이외의 제3자에게 대항하지 못한다":"양도인이 통지하거나 채무자가 승낙해야 대항할 수 있고 채무자 외 제3자에게는 확정일자 있는 증서로 해야 합니다.","양도통지는 양도인이 하여야 하나 양수인이 양도인의 대리인(또는 사자)으로서 통지에 관한 위임을 받았다면 양수인에 의한 양도통지도 유효하다":"양도통지는 양도인이 하는 것이 원칙이나 양수인이 대리인으로 위임받아 통지해도 유효해요.","양도할 수 없는 물건은 질권의 목적이 되지 못한다. 질권자는 설정자로 하여금 질물을 점유하게 하지 못한다(대리점유 금지)":"양도할 수 없는 물건은 질권의 목적이 될 수 없고 질권자는 설정자에게 질물을 점유하게 할 수 없습니다.","어느 연대채무자에 대한 법률행위의 무효나 취소의 원인은 다른 연대채무자의 채무에 영향을 미치지 않는다. 그 외의 사항은 효력이 없다(상대적 효력의 원칙)":"어느 연대채무자에 대한 무효·취소 원인은 다른 연대채무자에게 영향이 없고 나머지는 상대적 효력이 원칙입니다.","어느 종류의 통화로 지급할 것인 경우 그 통화가 변제기에 강제통용력을 잃은 때 채무자는 다른 통화로 변제한다. 외화채권: 채무자는 자기가 선택한 그 나라의 각 종류의 통화로 변제할 수 있다. 채권액이 다른 나라 통화로 지정된 때 채무자는 지급할 때의 이행지 환금시가에 의하여 우리나라 통화로 변제할 수 있다":"통화가 강제통용력을 잃으면 다른 통화로 변제하고 외화채권은 채무자가 고른 통화나 이행지 환금시가의 국내 통화로 갚을 수 있습니다.","어느 지역 주민이 집합체의 관계로 타인의 토지에서 초목ㆍ야생물ㆍ토사의 채취, 방목 기타 수익을 하는 권리에 지역권 규정을 준용한다":"어느 지역 주민이 집합체로 타인 토지에서 초목·토사를 채취하거나 방목하는 권리에는 지역권 규정을 준용해요.","언제든지 해지통고를 할 수 있다. 상대방이 통고를 받은 날부터 토지·건물 기타 공작물은 임대인 통고 6월, 임차인 통고 1월, 동산은 5일이 경과하면 해지의 효력이 생긴다":"기간 약정이 없으면 언제든 해지통고가 가능하고 토지·건물은 임대인 통고 6월, 임차인 통고 1월, 동산은 5일이 지나면 효력이 생깁니다.","연기적(일시적) 항변권은 동시이행의 항변권, 보증인의 최고ㆍ검색의 항변권이다":"연기적 항변권에는 동시이행의 항변권과 보증인의 최고·검색의 항변권이 있어요.","연대보증인이 있는 주채무를 제3자가 변제하여 주채무가 소멸한 경우, 제3자는 연대보증인에게 부당이득반환을 청구할 수 없다":"제3자가 연대보증인이 있는 주채무를 변제해 주채무가 소멸해도 연대보증인에게는 부당이득반환을 청구할 수 없습니다.","연대채무자ㆍ불가분채무자를 위한 보증인은 다른 연대채무자나 불가분채무자에 대하여 그 부담부분에 한하여 구상권이 있다. 공동보증인 간 구상은 자기 부담부분을 넘은 변제를 한 때 제444조를 준용하고, 주채무가 불가분이거나 상호연대·주채무자와 연대인 경우 제425조~제427조를 준용한다":"연대채무자·불가분채무자를 위한 보증인은 부담부분에 한해 구상권이 있고 공동보증인 간 구상은 자기 부담부분 초과 변제 시 인정됩니다.","영구적 항변권은 청구권의 행사를 영구적으로 저지한다":"영구적 항변권은 청구권의 행사를 영원히 막는 항변권이에요.","영리를 목적으로 하는 사단은 상사회사 설립 조건에 좇아 법인이 된다 · 상사회사에 관한 규정을 준용한다 · 영리 목적 재단은 불가이며 재단법인은 항상 비영리법인이다":"영리 사단은 상사회사 설립 조건에 따라 법인이 되고, 재단법인은 항상 비영리법인이에요.","예약완결권은 형성권이다. 예약완결권을 재판상 행사하는 경우 그 의사표시가 담긴 소장 부본이 제척기간 내에 상대방에게 송달되면 적법하게 행사한 것이다. 제척기간 도과 여부는 법원이 직권으로 조사한다":"예약완결권은 형성권이고 소장 부본이 제척기간 내에 송달되면 적법하게 행사한 것이며 제척기간 도과는 법원이 직권으로 조사해요.","예약완결권의 제척기간(약정이 없으면 예약 성립일부터 10년)이 지나면 예약목적물인 부동산을 인도받아 점유하고 있어도 완결권은 소멸한다. 예약완결권은 가등기의 대상이 되며 채권자대위권의 목적이 될 수 있다":"예약완결권은 약정이 없으면 예약 성립일부터 10년의 제척기간이 지나면 소멸하고 가등기의 대상이 되며 대위의 목적이 될 수 있습니다.","예외(계약명의신탁): 부동산 물권을 취득하기 위한 계약에서 명의수탁자가 당사자가 되고 상대방 당사자가 명의신탁약정이 있다는 사실을 알지 못한 경우에는 물권변동이 유효하다":"계약명의신탁에서 상대방이 명의신탁약정 사실을 몰랐다면 예외적으로 물권변동이 유효합니다.","오로지 보험사고를 가장하여 보험금을 취득할 목적으로 체결한 생명보험계약":"보험사고를 가장해 보험금을 얻으려고 맺은 생명보험계약은 반사회질서로 무효예요.","온천수는 토지와 별개의 부동산이 아니고, 온천에 관한 권리는 독립한 물권(관습상 물권)이 아니다":"온천수는 토지에서 독립한 부동산이 아니며 온천 이용권도 독립 물권으로 인정되지 않습니다.","온천에 관한 권리는 독립한 물권이 아니다(관습상 물권 아님)":"온천 이용에 관한 권리는 독립된 물권도 관습상 물권도 아닙니다.","완공기한을 넘겨 도급계약이 해제된 경우 지체상금의 발생 시기는 완공기한 다음 날이다. 선급금 지급을 도급인이 지체한 기간은 지체상금 발생기간에서 공제된다":"완공기한을 넘겨 해제된 경우 지체상금은 완공기한 다음 날부터 생기고 도급인이 선급금을 늦게 준 기간은 공제됩니다.","완성된 목적물 또는 완성 전의 성취된 부분에 하자가 있는 때 도급인은 상당한 기간을 정하여 보수를 청구할 수 있다. 하자가 중요하지 않은 경우 보수에 과다한 비용이 들 때는 보수를 청구할 수 없다. 보수에 갈음하여 또는 보수와 함께 손해배상을 청구할 수 있다(동시이행)":"하자가 있으면 도급인은 기간을 정해 보수를 청구하고 중요하지 않은데 비용이 과다하면 청구 못 하며 손해배상은 동시이행입니다.","완성된 목적물의 인도와 동시에 지급한다. 목적물의 인도를 요하지 않는 경우 일을 완성한 후 지체 없이 지급한다. 보수 일부를 선급하기로 하는 특약이 있으면 수급인은 그 제공이 있을 때까지 일의 착수를 거절할 수 있다":"보수는 인도와 동시에, 인도가 필요 없으면 완성 후 지체 없이 주며 선급 특약이 있으면 제공 때까지 착수를 거절할 수 있습니다.","완성된 주택을 도급인이 원시취득한 경우 수급인은 보수를 지급받을 때까지 그 주택에 유치권을 행사할 수 있다":"도급인이 원시취득한 완성 주택의 수급인은 보수를 받을 때까지 주택을 유치할 수 있습니다.","요역지가 수인의 공유인 경우 그 1인에 의한 지역권 소멸시효의 중단 또는 정지는 다른 공유자를 위하여 효력이 있다":"요역지 공유자 한 명의 지역권 시효 중단이나 정지는 다른 공유자를 위해서도 효력이 있어요.","용수승역지의 수량이 요역지 및 승역지의 수요에 부족한 때 먼저 가용에 공급하고 다른 용도에 공급한다. 승역지에 수개의 용수지역권이 설정될 수 있고 후순위 지역권자는 선순위 지역권자의 용수를 방해하지 못한다":"용수가 부족하면 먼저 가용에 공급하고 후순위 지역권자는 선순위 지역권자의 용수를 방해하지 못합니다.","우물을 파거나 용수ㆍ하수ㆍ오물 저치 지하시설은 경계로부터 2미터 이상, 저수지ㆍ구거ㆍ지하실 공사는 경계로부터 그 깊이의 반 이상의 거리를 둔다":"우물이나 하수·오물 지하시설은 경계에서 2미터 이상, 저수지·구거·지하실 공사는 깊이의 반 이상 떨어뜨립니다.","원본, 이자, 위약금, 채무불이행으로 인한 손해배상, 저당권 실행비용. 지연배상은 원본의 이행기일을 경과한 후의 1년분에 한한다. 등기된 손해배상예정액은 범위에 속하고 등기된 금액을 초과하는 원본이나 저당물의 보존비용 등은 범위에 속하지 않는다":"피담보채권의 범위는 원본, 이자, 위약금, 손해배상, 실행비용이며 지연배상은 이행기일을 넘긴 후 1년분에 한해요.","원본채권이 양도된 경우 이미 변제기에 도달한 이자채권은 별도의 의사표시가 없는 한 당연히 함께 양도되지는 않는다":"원본채권이 양도돼도 이미 변제기가 된 이자채권은 별도 의사표시가 없으면 당연히 함께 양도되지 않습니다.","위반 여부는 당사자의 주장이 없어도 법원이 직권으로 판단할 수 있다":"신의칙 위반 여부는 당사자가 주장하지 않아도 법원이 직권으로 판단할 수 있습니다.","위반하여 관리한 경우 과실 없는 때에도 손해를 배상할 책임이 있다. 단 공공의 이익에 적합한 관리행위는 중대한 과실이 없으면 배상할 책임이 없다. 긴급사무관리: 급박한 위해를 면하게 하기 위한 관리는 고의나 중대한 과실이 없으면 책임이 없다":"위반해서 관리하면 과실이 없어도 배상책임이 있으나 공공 이익에 적합하면 중과실 없을 때, 긴급사무관리는 고의·중과실 없을 때 책임이 없어요.","위 사유 외에 수권행위의 원인된 법률관계의 종료에 의하여 소멸한다. 법률관계 종료 전 본인이 수권행위를 철회한 경우도 같다. 원인된 법률관계가 기간만료로 종료되면 그 시점에 대리권도 소멸한다":"임의대리는 수권행위의 원인인 법률관계가 끝나거나 본인이 수권을 철회하면 소멸하며 기간만료로 끝나면 그 시점에 소멸합니다.","위임사무의 처리에 비용을 요하는 때 위임인은 수임인의 청구에 의하여 선급한다. 필요비 지출 시 지출한 날 이후의 이자 청구. 필요한 채무를 부담한 때 위임인에게 대신 변제하게 하거나 담보를 제공하게 할 수 있다. 과실 없이 받은 손해의 배상 청구":"사무 처리에 비용이 들면 위임인이 선급하고 수임인은 필요비와 이자, 채무 대변제나 담보제공, 과실 없이 입은 손해 배상을 청구할 수 있습니다.","위임의 본지에 따라 선량한 관리자의 주의로 위임사무를 처리하여야 한다(자기 재산과 동일한 주의가 아님)":"수임인은 위임의 본지에 따라 선량한 관리자의 주의로 사무를 처리해야 하며 자기 재산과 같은 주의로는 부족합니다.","위임인의 승낙이나 부득이한 사유 없이 제3자로 하여금 자기에 갈음하여 위임사무를 처리하게 하지 못한다":"수임인은 위임인 승낙이나 부득이한 사유 없이 제3자에게 자기를 대신해 사무를 처리하게 하지 못해요.","위임인의 청구가 있는 때 처리상황을 보고하고 위임이 종료한 때 지체 없이 그 전말을 보고한다. 취득물 등의 인도: 위임사무 처리로 받은 금전 기타 물건 및 과실을 위임인에게 인도하고 자기 명의로 취득한 권리를 이전한다. 위임인에게 인도할 금전을 소비한 때 소비한 날 이후의 이자와 손해배상":"수임인은 청구 시 처리상황을, 종료 시 전말을 보고하고 받은 금전·물건·권리를 위임인에게 넘기며 소비한 금전은 이자와 손해를 배상합니다.","위조서류에 의해 마쳐진 소유권이전등기에 대한 소유자의 말소등기청구권":"위조서류로 마쳐진 이전등기에 대한 소유자의 말소등기청구권은 물권적 청구권이에요.","위 최단존속기간으로 한다. 공작물의 종류와 구조를 정하지 않으면 제280조 제2호(15년)의 건물 소유 목적으로 본다":"존속기간을 정하지 않으면 최단존속기간으로 하고, 공작물의 종류와 구조를 정하지 않으면 건물 소유 목적으로 봅니다.","유권대리의 주장에는 표현대리의 주장이 포함되어 있지 않다(별개 주장)":"유권대리를 주장했다고 해서 표현대리 주장이 포함된 것이 아니며 별개의 주장이에요.","유언 같은 상대방 없는 의사표시는 자연적 해석이 우선한다":"유언처럼 해석할 상대방이 없는 의사표시는 표의자의 실제 의사를 따지는 자연적 해석이 먼저입니다.","유체물 및 전기 기타 관리할 수 있는 자연력을 말한다. 자연력은 배타적 지배를 할 수 있는 등 관리할 수 있어야 물건이다":"물건은 유체물과 전기 등 관리할 수 있는 자연력으로, 자연력은 배타적 지배가 가능해야 물건이에요.","유치권에는 물상대위성이 없다. 피담보채권의 양도와 목적물의 인도가 있으면 유치권은 이전된다":"유치권은 물상대위가 인정되지 않는 담보물권이지만 피담보채권 양도와 목적물 인도로 이전됩니다.","유치권은 법정담보물권이나 당사자가 유치권배제특약으로 성립을 배제할 수 있다. 배제특약 있으면 다른 요건을 갖춰도 성립하지 않는다. 배제특약의 효력은 특약 상대방뿐 아니라 누구든지 주장할 수 있고, 배제특약에는 조건을 붙일 수 있다":"유치권은 법정담보물권이지만 배제특약으로 성립을 막을 수 있고 그 효력은 누구든지 주장할 수 있으며 조건을 붙일 수도 있어요.","유치권은 점유의 상실로 소멸한다. 점유를 침탈당한 경우 점유회수의 소를 제기해 승소하여 점유를 회복해야 유치권이 되살아난다(소 제기만으로 회복되는 것이 아님). 점유 침탈로 인한 유치권 소멸을 원인으로 한 손해배상청구권은 침탈일부터 1년 내에 행사할 필요가 없다":"유치권은 점유를 잃으면 소멸하고 침탈당했다면 점유회수의 소에서 승소해 점유를 회복해야 되살아나며 손해배상청구는 1년 내 행사 제한이 없습니다.","유치권의 행사는 피담보채권의 소멸시효의 진행에 영향을 미치지 않는다":"유치권을 행사해도 피담보채권의 소멸시효 진행에는 영향이 없습니다.","유치권자는 변제를 받기 위해 유치물을 경매할 수 있으나(우선변제는 받지 못함), 정당한 이유가 있으면 감정인 평가에 의하여 직접 변제에 충당할 것을 법원에 청구할 수 있고 미리 채무자에게 통지하여야 한다":"유치권자는 경매를 할 수 있어도 우선변제권은 없고, 정당한 이유가 있으면 감정 평가로 직접 변제충당을 법원에 청구합니다.","유치권자는 채권 전부의 변제를 받을 때까지 유치물 전부에 대하여 권리를 행사할 수 있다. 목적물이 분할 가능하거나 수개의 물건인 경우에도 적용된다":"유치권자는 채권 전부를 변제받을 때까지 유치물 전부에 권리를 행사할 수 있고 목적물이 나눌 수 있어도 마찬가지예요.","유치물의 과실을 수취하여 다른 채권보다 먼저 변제에 충당할 수 있다. 과실이 금전이 아니면 경매하여야 한다. 과실은 이자에 먼저 충당하고 잉여는 원본에 충당한다":"유치권자는 과실을 수취해 다른 채권보다 먼저 변제에 충당할 수 있고 금전이 아니면 경매하며 이자에 먼저 충당합니다.","의결은 사원 과반수의 출석과 출석사원 결의권의 과반수다 · 서면ㆍ대리인 행사 사원은 출석한 것으로 본다 · 의사록에 경과ㆍ요령ㆍ결과를 기재하고 의장·출석 이사가 기명날인한다":"의결은 사원 과반수 출석과 출석 결의권 과반수로 하며, 의사록에 경과·요령·결과를 적고 의장과 출석 이사가 기명날인합니다.","의무 없이 타인을 위하여 사무를 관리하는 자는 그 사무의 성질에 좇아 가장 본인에게 이익이 되는 방법으로 관리하여야 한다. 본인의 의사를 알거나 알 수 있는 때에는 그 의사에 적합하도록 관리하여야 한다":"사무관리자는 사무의 성질에 따라 본인에게 가장 이익이 되는 방법으로 관리하고 본인 의사를 알면 그 의사에 맞게 관리해야 합니다.","의사능력의 유무는 구체적인 법률행위와 관련하여 개별적으로 판단한다":"의사능력이 있는지는 구체적인 법률행위마다 개별적으로 따져 판단해요.","의사능력이 없는 자라도 성년후견개시의 심판을 받아야 피성년후견인이 된다":"의사능력이 없더라도 성년후견개시 심판이 있어야 법적으로 피성년후견인 신분이 생깁니다.","의사무능력으로 무효가 된 경우 의사무능력자는 받은 이익이 현존하는 한도에서 상환할 책임이 있다":"의사무능력으로 무효가 되면 의사무능력자는 받은 이익이 남아 있는 한도에서 돌려줍니다.","의사무능력을 이유로 법률행위의 무효를 주장하는 자가 의사무능력에 대하여 증명책임을 진다":"의사무능력을 이유로 법률행위의 무효를 주장하는 쪽이 그 사실을 증명해야 합니다.","의사의 흠결, 사기, 강박 또는 선의ㆍ과실 여부는 대리인을 표준으로 결정한다. 특정한 법률행위를 위임한 경우 대리인이 본인의 지시에 좇아 행위한 때 본인은 자기가 안 사정이나 과실로 알지 못한 사정에 관하여 대리인의 부지를 주장하지 못한다":"대리행위의 하자는 대리인을 기준으로 정하되, 본인이 지시한 행위에서는 본인이 안 사정을 대리인의 부지로 주장하지 못해요.","의사표시는 표의자가 진의 아님을 알고 한 것이라도 효력이 있다":"본심과 다르게 말한 줄 알면서 한 의사표시라도 원칙적으로 말한 대로 효력이 있습니다.","이때 적용되는 것은 관습법이며 사실인 관습이 아니다":"이 순서에서 말하는 관습은 법적 효력이 있는 관습법이며 단순한 사실인 관습과는 다릅니다.","이미 매도된 부동산임을 알면서 매도인의 배임행위에 적극 가담해 체결한 저당권설정계약이다":"이미 팔린 부동산인 줄 알면서 매도인의 배임에 적극 가담해 맺은 저당권설정계약이 해당 예입니다.","이사ㆍ감사·청산인이 등기 해태, 재산목록ㆍ사원명부 부정기재 · 검사ㆍ감독 방해 등을 한 때 500만원 이하의 과태료이다":"이사·감사·청산인이 등기를 게을리하거나 장부를 부정 기재하면 500만원 이하의 과태료가 부과됩니다.","이사는 법인의 사무에 관하여 각자 법인을 대표한다 · 정관의 취지에 위반할 수 없다 · 사단법인은 총회 의결에 의하고 대리 규정을 준용한다":"이사는 법인을 각자 대표하되 정관의 취지에 위반할 수 없고, 사단법인은 총회 의결을 따릅니다.","이사는 선량한 관리자의 주의로 직무를 행한다 · 임무를 해태하면 법인에 대하여 연대하여 손해배상 책임이 있다 · 정관·총회가 금지하지 않은 사항은 타인에게 대리시킬 수 있다":"이사는 선량한 관리자의 주의로 직무를 행하고, 임무를 게을리하면 연대하여 법인에 손해를 배상합니다.","이사회 구성 규정, 감사 임면 규정은 필요적 기재사항이 아니다 · 존립시기ㆍ해산사유는 정한 경우에만 기재한다":"이사회 구성과 감사 임면 규정은 정관에 꼭 적을 사항에 해당하지 않습니다.","이의를 보류하지 않은 승낙을 하였더라도 승낙 전에 상계적상에 있는 반대채권이 있고 양수인이 이를 알고 있었다면 채무자는 양수인의 청구에 대하여 상계로 대항할 수 있다":"이의를 보류하지 않은 승낙 후에도 승낙 전에 상계적상이 있었고 양수인이 알았다면 채무자는 상계로 대항할 수 있어요.","이자 있는 채권의 이율은 다른 법률의 규정이나 약정이 없으면 연 5푼이다(민법 규정. 상행위는 상법상 연 6푼)":"이자 있는 채권의 이율은 다른 법률이나 약정이 없으면 민법상 연 5푼이고 상행위는 상법상 연 6푼이에요.","이중매매에서 제2매수인이 매도인의 배임행위에 적극 가담한 경우 제1매수인은 반사회질서를 이유로 제2매매의 무효를 주장할 수 있다. 제2매수인으로부터 전득한 자가 선의여도 등기는 유효해지지 않는다(절대적 무효)":"제2매수인이 매도인의 배임에 적극 가담했다면 제1매수인은 제2매매의 무효를 주장할 수 있고 전득자가 선의여도 등기는 유효해지지 않습니다.","이해관계인(법률상 이해관계인)이나 검사. 부재자의 제1순위 상속인이 있으면 제4순위 상속인은 실종선고를 청구할 수 없다(후순위 상속인은 이해관계인이 아님)":"실종선고는 법률상 이해관계인이나 검사가 청구하며, 후순위 상속인은 이해관계인이 아닙니다.","이행지를 달리하는 채무도 상계할 수 있으나 상계하는 당사자는 상대방에게 상계로 인한 손해를 배상하여야 한다":"이행지가 달라도 상계할 수 있으나 상계한 쪽은 상대방의 손해를 배상해야 합니다.","이행청구, 경개(모든 연대채무자의 이익을 위해 소멸), 상계(상계한 때 모든 연대채무자를 위해 소멸), 채권자지체. 부담부분에 한한 절대효: 면제, 혼동, 소멸시효 완성":"이행청구, 경개, 상계, 채권자지체는 절대적 효력이 있고 면제·혼동·시효완성은 부담부분에 한해 절대효가 있어요.","인격권 침해에 대하여는 예방적 구제수단으로서 금지청구권이 인정될 수 있다":"인격권을 침해당할 때는 미리 막는 구제수단으로 금지청구권이 인정될 수 있습니다.","인수인은 전채무자의 항변사유로 채권자에게 대항할 수 있다. 전채무자의 채무에 대한 보증이나 제3자가 제공한 담보는 채무인수로 소멸한다. 보증인이나 제3자가 채무인수에 동의한 경우는 제외":"인수인은 전채무자의 항변으로 대항할 수 있고 전채무자의 보증이나 제3자 담보는 소멸하지만 동의하면 유지됩니다.","인접지 수목 가지가 경계를 넘으면 그 소유자에 대하여 가지의 제거를 청구할 수 있고, 응하지 않으면 청구자가 제거할 수 있다. 뿌리가 경계를 넘으면 임의로 제거할 수 있다":"이웃 수목의 가지가 경계를 넘으면 제거를 청구하고 응하지 않으면 직접 제거할 수 있으며 뿌리는 임의로 제거할 수 있습니다.","인접지의 지반이 붕괴할 정도로 자기 토지를 심굴하지 못한다. 충분한 방어공사를 한 때는 제외":"인접지 지반이 무너질 정도로 자기 토지를 깊이 파서는 안 되고 충분한 방어공사를 하면 예외예요.","인접 토지소유자는 공동비용으로 통상의 경계표나 담을 설치할 수 있다. 비용은 쌍방이 절반하여 부담하되 측량비용은 면적에 비례한다":"인접 토지소유자는 공동비용으로 경계표나 담을 설치할 수 있고 비용은 절반씩, 측량비용은 면적에 비례해 부담해요.","인지청구권은 포기할 수 없는 권리이므로 실효의 원칙이 적용되지 않는다":"인지청구권은 포기할 수 없는 권리이므로 오래 행사하지 않아도 실효의 원칙이 적용되지 않아요.","일방 당사자의 계약위반으로 해제된 경우 계약을 위반한 당사자도 해제로 계약이 소멸되었음을 들어 이행을 거절할 수 있다":"계약위반으로 해제되었다면 위반한 당사자도 계약이 소멸했음을 들어 이행을 거절할 수 있어요.","일방 당사자의 주관적 사정이 아니다":"한쪽 당사자가 개인적으로 겪은 주관적 사정은 이 원칙의 사정이 아닙니다.","일방에 대한 의무이행의 기한이 있는 때 상대방의 의무이행에 대하여도 동일한 기한이 있는 것으로 추정한다. 대금지급장소: 목적물의 인도와 동시에 대금을 지급할 경우 그 인도장소에서 지급한다":"한쪽의 이행기한이 있으면 상대방의 이행에도 같은 기한이 있다고 추정하고, 인도와 동시에 지급하면 인도장소에서 대금을 지급합니다.","일부 이행된 계약의 묵시적 합의해제가 인정되려면 원상회복에 관하여도 의사가 일치되어야 한다. 일방 당사자가 원상회복 및 손해배상의 범위에 관한 조건을 제시한 경우 그 조건에 관한 합의까지 이루어져야 합의해제가 성립한다":"일부 이행된 계약의 묵시적 합의해제가 인정되려면 원상회복에 관해서도 의사가 일치되어야 하고, 조건을 제시했다면 그 조건까지 합의되어야 해요.","일시사용을 위한 가설건축물은 토지의 정착물로 볼 수 없다":"일시 사용을 위한 가설건축물은 토지의 정착물로 보지 않아요.","일시적 후원 또는 특정한 사무에 관한 후원이 필요한 사람에 대한 심판이다. 본인의 의사에 반하여 할 수 없다. 심판 시 특정후견의 기간 또는 사무의 범위를 정하여야 한다":"특정후견은 일시적이거나 특정 사무에 한해 후원이 필요한 사람에 대한 심판으로 본인 의사에 반하여 할 수 없습니다.","일정한 목적을 위하여 타인의 토지를 자기 토지의 편익에 이용하는 권리다":"지역권은 일정한 목적을 위해 남의 토지를 자기 토지의 이익에 쓰는 물권입니다.","임대인의 동의를 얻어 부속한 물건이나 임대인으로부터 매수하였거나 동의를 얻어 임차인으로부터 매수한 부속물에 대하여 전대차 종료 시 임대인에게 매수를 청구할 수 있다":"전차인은 임대인 동의를 얻어 부속한 물건이나 매수한 부속물에 대해 전대차 종료 시 임대인에게 매수를 청구할 수 있어요.","임대인의 동의를 얻어 전대한 경우 임대인과 임차인의 합의로 계약을 종료한 때에도 전차인의 권리는 소멸하지 않는다":"임대인의 동의를 얻은 전대에서는 임대인과 임차인이 합의로 계약을 종료해도 전차인의 권리가 소멸하지 않습니다.","임대인의 동의를 얻어 전대한 때 전차인은 직접 임대인에 대하여 의무를 부담한다. 전차인은 전대인에 대한 차임 지급으로써 임대인에게 대항하지 못한다(차임 지급시기 이전의 선급은 대항 불가, 지급시기 이후 지급이나 임대인의 차임청구 전에 지급시기가 도래한 지급은 대항 가능). 임대인의 임차인에 대한 권리행사에 영향이 없다":"동의를 얻은 전대에서 전차인은 임대인에게 직접 의무를 지고, 전대인에게 차임을 선급해도 임대인에게 대항하지 못합니다.","임대인이 임대물의 보존에 필요한 행위를 하는 때 임차인은 거절하지 못한다. 임대인이 임차인의 의사에 반하여 보존행위를 하여 임차의 목적을 달성할 수 없는 때 임차인은 계약을 해지할 수 있다":"임대인의 보존행위는 임차인이 거절하지 못하지만 임차인의 의사에 반해 목적을 달성할 수 없게 되면 임차인이 계약을 해지할 수 있어요.","임대차계약이 해지의 통고로 종료된 경우 그 임대물이 적법하게 전대되었을 때 임대인은 전차인에 대하여 그 사유를 통지하지 않으면 해지로써 전차인에게 대항하지 못한다. 차임연체 등 임차인 채무불이행을 이유로 한 해지에는 전차인에 대한 통지가 필요하지 않다":"해지통고로 종료된 임대차는 적법한 전차인에게 그 사유를 통지해야 대항할 수 있지만 차임연체 같은 채무불이행 해지에는 통지가 필요 없습니다.","임대차기간 만료 후 임차인이 사용·수익을 계속하는 경우 임대인이 상당한 기간 내에 이의를 하지 아니한 때 전임대차와 동일한 조건으로 다시 임대차한 것으로 본다. 당사자는 제635조에 의한 해지통고를 할 수 있다. 전임대차에 대하여 제3자가 제공한 담보는 기간 만료로 소멸한다":"기간 만료 후 임차인이 계속 쓰는데 임대인이 이의하지 않으면 같은 조건으로 다시 임대차한 것으로 보고 제3자 담보는 기간 만료로 소멸해요.","임대차와 전대차가 모두 종료된 경우 전차인이 목적물을 임대인에게 직접 인도하면 전대인에 대한 인도의무를 면한다":"임대차와 전대차가 모두 끝난 뒤 전차인이 임대인에게 직접 인도하면 전대인에 대한 인도의무도 없어집니다.","임시이사는 이사가 없거나 결원이어서 손해 염려가 있을 때 선임한다 · 이해관계인이나 검사의 청구로 법원이 선임한다(직권 아님) · 이익 상반 시 특별대리인을 선임한다(임시이사 아님)":"임시이사는 이사가 없거나 결원으로 손해 염려가 있을 때 이해관계인이나 검사의 청구로 법원이 선임하고, 이익 상반에는 특별대리인을 선임해요.","임시총회는 이사가 필요하다고 인정한 때 소집한다 · 총사원 5분의 1 이상이 목적사항을 제시해 청구한 때도 같다 · 청구 후 2주간 내 소집하지 않으면 청구 사원이 법원 허가로 소집한다":"임시총회는 이사가 필요하다고 보거나 총사원 5분의 1 이상이 청구하면 열고, 2주 내 소집이 없으면 청구자가 법원 허가로 소집합니다.","임의대위: 채무자를 위하여 변제한 자는 변제와 동시에 채권자의 승낙을 얻어 채권자를 대위할 수 있다. 법정대위: 변제할 정당한 이익이 있는 자는 변제로 당연히 채권자를 대위한다(채권자 승낙 불요)":"임의대위는 채권자 승낙을 얻어 하고, 변제할 정당한 이익이 있는 자는 승낙 없이 당연히 채권자를 대위하는 법정대위입니다.","임의적 기재사항도 정관에 기재되면 변경은 정관변경 절차에 따른다":"임의적 기재사항도 정관에 적히면 그 변경은 정관변경 절차를 따라야 해요.","임차물의 수리를 요하거나 임차물에 대하여 권리를 주장하는 자가 있는 때 지체 없이 임대인에게 통지하여야 한다. 임대인이 이미 안 때 제외":"임차물 수리가 필요하거나 권리를 주장하는 자가 있으면 임차인은 지체 없이 임대인에게 통지해야 하고 임대인이 이미 알았으면 제외됩니다.","임차물의 일부가 임차인의 과실 없이 멸실 기타 사유로 사용·수익할 수 없는 때 그 부분의 비율로 차임감액을 청구할 수 있다. 잔존부분으로 목적을 달성할 수 없는 때 해지할 수 있다":"임차물 일부를 과실 없이 쓸 수 없게 되면 그 비율만큼 차임감액을 청구할 수 있고 잔존부분으로 목적을 달성할 수 없으면 해지할 수 있어요.","임차인은 임대인의 동의 없이 임차권을 양도하거나 임차물을 전대하지 못한다. 위반 시 임대인은 계약을 해지할 수 있다":"임차인이 임대인 동의 없이 임차권을 양도하거나 전대하면 임대인은 계약을 해지할 수 있습니다.","임차인이 임대차계약 종료 후 임차건물을 계속 점유하였더라도 이익을 얻지 않았다면 부당이득반환의무를 지지 않는다":"임대차 종료 후 임차건물을 계속 점유해도 이익을 얻지 않았다면 부당이득반환의무가 없어요.","자기를 위한 것으로 본다. 단 상대방이 대리인으로서 한 것임을 알았거나 알 수 있었을 때에는 본인에게 효력이 생긴다":"본인을 위한 것임을 표시하지 않으면 자기를 위한 것으로 보지만, 상대방이 알았거나 알 수 있었다면 본인에게 효력이 생깁니다.","자기 비용으로 담의 재료를 통상보다 양호하게 하거나 높이를 높게 하거나 방화벽 기타 특수시설을 할 수 있다":"자기 비용으로 담의 재료를 좋게 하거나 높이거나 방화벽 같은 특수시설을 할 수 있습니다.","자기의 권리에 의하여 구상할 수 있는 범위에서 채권 및 담보에 관한 권리를 행사할 수 있다. 보증인은 미리 전세권이나 저당권의 등기에 대위를 부기하지 아니하면 그 부동산에 권리를 취득한 제3자에 대하여 채권자를 대위하지 못한다. 제3취득자는 보증인에 대하여 채권자를 대위하지 못한다":"대위자는 구상할 수 있는 범위에서 채권과 담보권을 행사하고 보증인은 부기등기가 없으면 제삼취득자에게 대위하지 못합니다.","자기 책임으로 복대리인을 선임할 수 있다. 부득이한 사유로 선임한 때에는 제121조 제1항의 선임감독 책임만 있다":"법정대리인은 자기 책임으로 복대리인을 선임할 수 있고, 부득이한 사유로 선임했다면 선임·감독 책임만 집니다.","자연인의 권리능력을 제한하는 약정(당사자 합의)은 무효이다":"자연인의 권리능력을 당사자 합의로 제한하는 약정은 무효예요.","잔여재산은 ① 정관으로 지정한 자에게 귀속한다 · ② 지정이 없으면 주무관청 허가로 유사 목적에 처분한다 · ③ 처분되지 않은 재산은 국고에 귀속(출연자 귀속 아님)":"잔여재산은 정관 지정자에게, 없으면 허가받아 유사 목적에 처분하고, 처분 안 된 것은 국고에 귀속합니다.","잠수장비를 착용하고 입수한 후 행방불명된 것은 특별실종의 원인이 되는 사유에 해당하지 않는다":"잠수장비를 착용하고 입수한 뒤 행방불명된 경우는 법이 정한 특별실종의 원인에 해당하지 않습니다.","장소를 정하지 않은 때 특정물의 인도는 채권성립 당시 그 물건이 있던 장소, 그 외 채무는 채권자의 현주소(영업에 관한 채무는 현영업소)":"장소를 정하지 않으면 특정물은 채권성립 당시 소재지에서, 그 외는 채권자의 현주소에서 변제해요.","재단법인 설립행위는 요식행위이며 출연자도 착오를 이유로 취소할 수 있다 · 생전처분이면 증여, 유언이면 유증 규정을 준용한다 · 출연재산은 생전처분이면 성립 때, 유언이면 효력 발생 때 귀속한다":"재단법인 설립은 요식행위로, 생전처분이면 증여, 유언이면 유증 규정을 준용하고 출연재산은 각각 성립·효력 발생 때 귀속됩니다.","재단법인 설립행위와 유언은 상대방 없는 단독행위다":"재단법인을 세우는 행위와 유언은 상대방이 따로 없는 단독행위로 분류합니다.","재단법인은 설립자가 재산을 출연하고 기명날인한다 · 정관에 목적, 명칭, 사무소, 자산, 이사 임면 규정을 기재한다(제40조 제1호~제5호) · 존립시기ㆍ해산사유는 필요적 기재사항이 아니다":"재단법인은 설립자가 재산을 출연하고 정관에 목적, 명칭, 사무소, 자산, 이사 임면을 적으며 존립시기는 필수가 아닙니다.","재단법인의 목적을 달성할 수 없는 때다 · 설립자나 이사는 주무관청의 허가를 얻는다 · 설립 취지를 참작해 목적 기타 정관 규정을 변경한다":"목적을 달성할 수 없으면 설립자나 이사가 허가를 얻어 설립 취지를 참작해 목적을 변경할 수 있습니다.","재단법인 정관변경은 정관에 정한 때에 한하여 가능하다 · 목적달성 또는 재산보전을 위하여 적당한 때 명칭·소재지 변경 가능 · 어느 경우든 주무관청의 허가가 필요하다":"재단법인은 정관에 정한 때에 한해 정관을 바꿀 수 있고, 어느 경우든 주무관청의 허가가 있어야 해요.","재산관리인의 보존행위: 법원 허가 없이 보존행위(예: 말소등기절차 이행청구)를 할 수 있다":"재산관리인은 말소등기절차 이행청구 같은 보존행위는 법원의 허가 없이 할 수 있습니다.","재산권. 단 부동산의 사용ㆍ수익을 목적으로 하는 권리는 제외. 설정방법은 그 권리의 양도에 관한 방법에 의한다. 양도할 수 없는 채권은 질권의 목적이 될 수 없다":"재산권은 질권의 목적이 되지만 부동산의 사용·수익권은 제외하고, 양도할 수 없는 채권도 질권의 목적이 될 수 없어요.","재산권은 소유권이전등기청구권이다":"소유권이전등기청구권은 재산권에 해당합니다.","재산목록은 성립한 때와 매년 3월 내에 작성해 사무소에 비치한다 · 사단법인은 사원명부를 비치한다 · 사원의 지위는 양도·상속할 수 없다(정관에 정하면 상속 가능)":"재산목록은 성립한 때와 매년 3월 내에 만들어 비치하고, 사원의 지위는 정관에 정하지 않으면 양도·상속할 수 없습니다.","재산을 관리하는 아버지ㆍ어머니ㆍ후견인에 대한 제한능력자의 권리는 능력자가 되거나 후임 법정대리인이 취임한 때부터 6개월 내에는 시효가 완성되지 않는다":"부모나 후견인처럼 재산을 관리하는 사람에 대한 권리는 능력자가 되거나 후임이 취임한 때부터 6개월은 시효가 완성되지 않습니다.","재판상 청구는 소송의 각하ㆍ기각ㆍ취하의 경우 중단 효력이 없다. 그 경우 6월 내에 재판상 청구, 파산절차참가, 압류ㆍ가압류ㆍ가처분을 하면 최초의 재판상 청구로 중단된 것으로 본다":"재판상 청구가 각하·기각·취하되면 중단 효력이 없으나 6월 내에 다시 청구 등을 하면 최초 청구로 중단된 것으로 봅니다.","재판 없이 효과가 발생하는 것은 상계권ㆍ계약해제권ㆍ동의권ㆍ일방예약완결권이다":"상계권, 해제권, 동의권, 일방예약완결권은 재판 없이도 효과가 생기는 형성권입니다.","저당권으로 담보한 채권을 질권의 목적으로 한 때: 저당권 등기에 질권의 부기등기를 하여야 그 효력이 저당권에 미친다(질권의 목적이 될 수 있음). 무담보 채권에 질권 설정 후 그 채권을 담보하기 위한 저당권이 설정되어도 같다":"저당권부 채권을 질권의 목적으로 하면 저당권 등기에 질권의 부기등기를 해야 그 효력이 저당권에 미칩니다.","저당권으로 담보한 채권이 시효 완성 기타 사유로 소멸하면 저당권도 소멸한다":"피담보채권이 시효 등으로 사라지면 부종성 때문에 저당권도 함께 소멸합니다.","저당권으로 담보한 채권이 시효 완성으로 소멸하면 저당권도 소멸한다. 나대지의 담보가치 유지를 위한 무상 지상권도 피담보채권이 시효로 소멸하면 소멸한다":"저당권으로 담보한 채권이 시효로 소멸하면 저당권도 소멸하고, 담보가치 유지용 무상 지상권도 같아요.","저당권은 그 담보한 채권과 분리하여 타인에게 양도하거나 다른 채권의 담보로 하지 못한다":"저당권은 담보한 채권과 분리해서 양도하거나 다른 채권의 담보로 삼을 수 없어요.","저당권이 설정된 후 소유권이 제3자에게 이전된 경우 종전 소유자(설정자)도 피담보채권의 소멸을 이유로 저당권설정등기의 말소를 청구할 수 있다":"저당권 설정 후 소유권이 넘어가도 종전 소유자는 피담보채권 소멸을 이유로 설정등기의 말소를 청구할 수 있습니다.","저당권자는 저당목적물에서 임의로 분리ㆍ반출된 물건을 자신에게 반환하라고 청구할 수 없다(원래 장소로의 반환을 청구)":"저당목적물에서 분리·반출된 물건은 저당권자가 자신에게 반환하라고 청구할 수 없고 원래 장소로의 반환만 청구합니다.","저당권자는 채권의 변제를 받기 위하여 저당물의 경매를 청구할 수 있다. 저당물의 소유권을 취득한 제3자도 경매인이 될 수 있다":"저당권자는 변제를 받으려고 저당물 경매를 청구할 수 있으며 저당물을 취득한 제3자도 경락인이 될 수 있습니다.","저당물의 경매로 토지와 지상 건물이 다른 소유자에 속하게 된 때 토지소유자는 건물소유자에 대하여 지상권을 설정한 것으로 본다. 지료는 당사자의 청구에 의하여 법원이 정한다":"저당물 경매로 토지와 건물 소유자가 달라지면 토지소유자가 지상권을 설정한 것으로 보고 지료는 법원이 정하는 저당권 법정지상권입니다.","저당물의 경매로 토지와 지상 건물이 다른 소유자에 속한 경우 토지소유자는 건물소유자에 대하여 지상권을 설정한 것으로 본다. 지료는 당사자의 청구에 의하여 법원이 정한다":"저당물 경매로 토지와 건물의 소유자가 달라지면 토지소유자가 건물소유자에게 지상권을 설정한 것으로 보고 지료는 법원이 정합니다.","저당부동산에 대하여 소유권ㆍ지상권ㆍ전세권을 취득한 제3자는 저당권자에게 담보된 채권을 변제하고 저당권의 소멸을 청구할 수 있다(설정자의 의사에 반해도 가능)":"저당부동산의 제3취득자는 담보된 채권을 변제하고 저당권의 소멸을 청구할 수 있으며 설정자의 의사에 반해도 됩니다.","저당부동산에 대한 압류가 있은 후에 설정자가 수취한 과실 또는 수취할 수 있는 과실에 미친다. 저당권자가 그 부동산의 소유권ㆍ지상권ㆍ전세권을 취득한 제3자에 대하여는 압류한 사실을 통지한 후가 아니면 대항하지 못한다":"저당부동산을 압류한 뒤 설정자가 거둔 과실에도 미치지만 제3취득자에게는 압류 사실을 통지한 후에야 대항할 수 있습니다.","저당부동산에 부합된 물건과 종물에 미친다(설정 후 부합된 물건 포함). 법률에 특별한 규정 또는 설정행위에 다른 약정이 있으면 제외":"저당권의 효력은 저당부동산에 부합된 물건과 종물에 미치며 설정 후 부합된 것도 포함하지만 특약이 있으면 제외합니다.","전기 기타 관리할 수 있는 자연력은 동산이다":"전기 같은 관리할 수 있는 자연력은 동산으로 취급해요.","전세권설정자가 전세금의 반환을 지체한 때 전세권자는 민사집행법에 따라 목적물의 경매를 청구할 수 있다":"전세금을 돌려주지 않고 미루는 설정자를 상대로 전세권자는 민사집행법상 경매를 청구할 수 있습니다.","전세권양수인은 전세권설정자에 대하여 전세권양도인과 동일한 권리의무가 있다. 전전세 또는 임대한 경우 전세권자는 하지 않았으면 면할 수 있는 불가항력으로 인한 손해에 대하여도 책임을 진다":"전세권양수인은 양도인과 같은 권리의무를 가지고, 전전세를 한 전세권자는 불가항력 손해에도 책임을 집니다.","전세권은 건물뿐 아니라 토지에도 설정할 수 있다(농경지 제외). 1필 토지의 일부에도 설정할 수 있다":"전세권은 건물과 토지 모두에 설정할 수 있고 농경지는 제외하며 1필 토지의 일부에도 가능합니다.","전세권의 목적물이 불가항력으로 멸실된 부분의 전세권은 소멸한다. 잔존부분으로 목적을 달성할 수 없는 때 전세권 전부의 소멸을 통고하고 전세금 반환을 청구할 수 있다. 전세권자 책임 있는 사유로 멸실되면 손해를 배상하고 설정자는 전세금으로 충당한다":"불가항력으로 멸실된 부분의 전세권은 소멸하고, 잔존부분으로 목적을 달성할 수 없으면 전부 소멸을 통고하고 전세금 반환을 청구할 수 있어요.","전세권의 존속기간이 시작되기 전에 마친 전세권설정등기는 특별한 사정이 없는 한 유효한 것으로 추정된다":"존속기간이 시작되기 전에 이미 마친 전세권설정등기도 일단 유효하다고 추정합니다.","전세권이 갱신 없이 존속기간이 만료되면 전세권의 용익물권적 권능은 전세권설정등기의 말소 없이도 당연히 소멸한다. 토지전세계약이 종료되면 그 계약을 원인으로 한 전세권설정등기 절차 이행청구권도 소멸한다":"갱신 없이 기간이 만료되면 전세권의 용익물권적 권능은 말소등기 없이도 소멸하고 토지전세 종료 시 설정등기 이행청구권도 소멸해요.","전세권이 소멸한 때: 전세권설정자는 전세권자로부터 목적물의 인도 및 전세권설정등기 말소등기에 필요한 서류를 교부받는 동시에 전세금을 반환한다(동시이행)":"전세권이 소멸하면 설정자는 목적물 인도 및 말소등기 서류 교부와 동시에 전세금을 반환하는 동시이행 관계예요.","전세권자가 목적물을 개량하기 위하여 지출한 유익비는 가액의 증가가 현존한 경우에 한하여 소유자의 선택에 좇아 지출액이나 증가액의 상환을 청구할 수 있고, 법원은 소유자 청구로 상환기간을 허여할 수 있다":"전세권자의 유익비는 가액 증가가 현존할 때 소유자의 선택에 따라 지출액이나 증가액을 청구하고 법원이 상환기간을 줄 수 있어요.","전세권자가 설정계약 또는 목적물의 성질에 의하여 정하여진 용법으로 사용ㆍ수익하지 않으면 전세권설정자는 전세권의 소멸을 청구할 수 있고 원상회복 또는 손해배상을 청구할 수 있다":"전세권자가 정해진 용법대로 쓰지 않으면 설정자는 소멸을 청구하고 원상회복이나 손해배상을 청구할 수 있습니다.","전세권자는 전세권을 타인에게 양도 또는 담보로 제공할 수 있고 존속기간 내에서 목적물을 전전세 또는 임대할 수 있다. 설정행위로 금지한 때는 제외. 즉 설정자의 동의 없이 양도할 수 있다":"전세권자는 설정자의 동의 없이 전세권을 양도하거나 담보로 제공하고 기간 내에서 전전세·임대를 할 수 있으나 설정행위로 금지하면 안 됩니다.","전세권자의 유지ㆍ수선의무: 목적물의 현상을 유지하고 통상의 관리에 속한 수선을 하여야 한다":"전세권자는 목적물의 현상을 유지하고 통상의 관리에 속한 수선을 해야 합니다.","전세권 존속 중 목적물의 소유권이 이전되면 신 소유자가 전세권설정자의 지위를 승계하여 전세금반환의무를 부담한다. 구 소유자는 부담하지 않는다":"전세권 존속 중 소유권이 이전되면 새 소유자가 설정자 지위를 승계하여 전세금반환의무를 지고 옛 소유자는 지지 않습니다.","전세권 존속 중에는 전세권을 존속시키면서 전세금반환채권만을 분리하여 확정적으로 양도하는 것은 허용되지 않는다":"전세권이 존속하는 동안 전세금반환채권만 따로 확정적으로 양도하는 것은 허용되지 않습니다.","전세금을 지급하고 타인의 부동산을 점유하여 그 부동산의 용도에 좇아 사용ㆍ수익하며, 그 부동산 전부에 대하여 후순위권리자 기타 채권자보다 전세금의 우선변제를 받을 권리가 있다. 용익물권적 성격과 담보물권적 성격을 겸비한다. 농경지는 전세권의 목적으로 하지 못한다":"전세권은 전세금을 내고 타인 부동산을 사용·수익하며 후순위권리자보다 우선변제를 받는 용익물권이면서 담보물권이에요.","전세목적물의 사용ㆍ수익 권능을 배제하고 채권담보만을 위해 설정한 전세권설정등기는 무효다":"사용·수익 권능을 배제하고 채권담보만을 위해 설정한 전세권설정등기는 전세권으로 인정되지 않아 무효예요.","전세목적물의 인도는 전세권의 성립요건이 아니다":"전세권은 목적물을 인도하지 않아도 성립하므로 인도는 성립요건이 아닙니다.","전지(戰地)에 임한 자, 침몰한 선박 중에 있던 자, 추락한 항공기 중에 있던 자, 기타 사망의 원인이 될 위난을 당한 자의 생사가 전쟁종지 후 또는 위난 종료 후 1년간 분명하지 아니한 때":"특별실종은 전쟁이나 선박 침몰, 항공기 추락 같은 위난을 당한 사람의 생사가 종료 후 1년간 불분명할 때 성립해요.","전차인은 전대차계약으로 전대인에 대하여 부담하는 의무 이상으로, 또 임대차계약으로 임차인이 임대인에 대하여 부담하는 의무 이상으로 임대인에게 의무를 지지 않는다(둘 중 작은 것)":"전차인의 의무는 전대차계약상 의무와 임대차계약상 임차인의 의무 중 작은 쪽을 넘지 않아요.","전통사찰의 주지직을 거액의 금품을 대가로 양도ㆍ양수하는 약정을 알고도 묵인ㆍ방조한 상태다":"전통사찰 주지직을 거액에 사고파는 약정을 알고도 묵인한 상태를 전제로 합니다.","전후 양시에 점유한 사실이 있으면 점유는 계속한 것으로 추정한다":"앞과 뒤 두 시점에 점유한 사실이 있으면 그 사이도 계속 점유한 것으로 추정합니다.","점유개정: 양도인이 점유를 계속하는 때에는 양수인이 인도받은 것으로 본다. 목적물반환청구권의 양도: 제3자가 점유한 동산은 반환청구권을 양도함으로써 인도한 것으로 본다":"점유개정은 양도인이 점유를 계속해도 인도로 보고, 제3자 점유 동산은 반환청구권을 양도해 인도한 것으로 봅니다.","점유권, 물권은 누구에게나 주장할 수 있는 절대권이다":"점유권과 물권은 누구에게든 주장할 수 있는 절대권에 속해요.","점유권 규정은 재산권을 사실상 행사하는 경우에 준용한다":"점유권 규정은 재산권을 사실상 행사하는 경우, 곧 준점유에도 준용해요.","점유권에 기인한 소와 본권에 기인한 소는 서로 영향을 미치지 않는다. 점유권에 기인한 소는 본권에 관한 이유로 재판하지 못한다":"점유권에 기한 소와 본권에 기한 소는 서로 영향을 주지 않으며 점유의 소는 본권 이유로 재판할 수 없습니다.","점유권은 상속인에게 이전된다. 점유권의 양도는 점유물의 인도로 효력이 생긴다(간이인도, 점유개정, 목적물반환청구권 양도 준용)":"점유권은 상속인에게 이전되고 양도는 점유물을 인도해야 효력이 생깁니다.","점유물방해제거청구권(제205조 제2항)의 1년은 제척기간으로서 출소기간이다":"점유물방해제거청구권의 1년은 제척기간으로서 반드시 그 안에 소를 제기해야 하는 출소기간이에요.","점유물이 점유자의 책임 있는 사유로 멸실ㆍ훼손된 때 악의의 점유자는 손해 전부를 배상하고, 선의의 점유자는 이익이 현존하는 한도에서 배상한다. 소유의 의사가 없는 점유자(타주점유자)는 선의인 경우에도 손해 전부를 배상한다":"점유자 책임으로 물건이 멸실·훼손되면 악의는 전부, 선의는 현존이익만큼 배상하고 타주점유자는 선의여도 전부 배상합니다.","점유의 방해를 받은 때 방해의 제거 및 손해배상을 청구할 수 있다. 방해가 종료한 날부터 1년 내에 행사한다. 공사로 인한 방해는 공사착수 후 1년이 경과하거나 공사가 완성한 때에는 방해제거를 청구하지 못한다. 이 1년은 제척기간이며 출소기간이다":"점유보유는 방해 제거와 손해배상을 청구하는 소로, 방해가 끝난 날부터 1년 내에 행사하는 제척기간이 있어요.","점유의 침탈을 당한 때 물건의 반환 및 손해배상을 청구할 수 있다. 침탈자의 특별승계인에 대하여는 행사하지 못하나 승계인이 악의이면 가능. 침탈을 당한 날부터 1년 내에 행사한다":"점유를 침탈당하면 반환과 손해배상을 청구할 수 있고 침탈한 날부터 1년 내에 행사하며 악의의 승계인에게는 행사할 수 있습니다.","점유자가 시효완성 후 점유를 상실하였더라도 시효이익의 포기로 볼 수 있는 경우가 아닌 한 이미 취득한 소유권이전등기청구권이 즉시 소멸하지 않는다":"점유자가 시효완성 후 점유를 잃어도 포기로 볼 수 있는 경우가 아니면 이미 취득한 등기청구권이 곧바로 소멸하지 않아요.","점유자가 점유물을 반환할 때 점유물을 보존하기 위하여 지출한 필요비 상환을 청구할 수 있다. 점유자가 과실을 취득한 경우 통상의 필요비는 청구하지 못한다. 유익비는 가액의 증가가 현존한 경우에 한하여 회복자의 선택에 좇아 지출금액이나 증가액의 상환을 청구할 수 있고, 법원은 회복자의 청구에 의하여 상당한 상환기간을 허여할 수 있다":"점유자는 반환할 때 필요비를 청구할 수 있고, 유익비는 가액 증가가 남아 있을 때 회복자의 선택에 따라 지출액이나 증가액을 청구합니다.","점유자가 주장한 매매 등 점유권원이 인정되지 않는다는 사유만으로는 번복되지 않는다. 국가나 지방자치단체가 점유하는 경우에도 적용된다":"자주점유 추정은 매매 같은 점유권원이 인정되지 않는다는 이유만으로는 뒤집히지 않고 국가나 지자체의 점유에도 적용됩니다.","점유자가 행사하는 권리는 적법하게 보유한 것으로 추정한다":"점유자가 행사하는 권리는 적법하게 가진 것으로 법이 추정해 줍니다.","점유자는 부정한 침탈 또는 방해에 대하여 자력으로 방위할 수 있다. 침탈된 물건이 부동산이면 침탈 후 직시 가해자를 배제하여 탈환할 수 있고, 동산이면 현장에서 또는 추적하여 탈환할 수 있다":"점유자는 부정한 침탈에 자력으로 방위할 수 있고, 부동산은 침탈 직후 탈환하며 동산은 현장 또는 추적하여 탈환할 수 있어요.","점유자는 소유의 의사로 선의, 평온 및 공연하게 점유한 것으로 추정한다. 선의의 점유자라도 본권에 관한 소에 패소한 때에는 소가 제기된 때부터 악의의 점유자로 본다":"점유자는 소유 의사로 선의·평온·공연하게 점유한 것으로 추정되며 본권 소송에서 지면 소 제기 때부터 악의로 봅니다.","점유자의 승계인은 자기의 점유만을 주장하거나 자기의 점유와 전점유자의 점유를 아울러 주장할 수 있다. 아울러 주장하면 하자도 계승한다":"점유 승계인은 자기 점유만 또는 전점유자의 점유와 합쳐서 주장할 수 있고 합쳐 주장하면 하자도 승계해요.","점유자의 유익비상환청구권, 전세권자의 전세금반환채권":"유익비상환청구권과 전세금반환채권은 형성권이 아니라 청구권입니다.","점유자의 유익비상환청구권은 형성권이 아니라 청구권이다":"점유자의 유익비상환청구권은 일방적 의사표시로 효과가 생기는 형성권이 아니라 청구권입니다.","점유취득시효 완성자는 시효 완성 당시 소유자에 대하여 채권적 등기청구권을 가진다. 등기를 마치기 전에는 소유권을 취득하지 못한다":"점유취득시효를 완성한 사람은 소유자에게 이전등기를 요구하는 채권적 청구권만 있고 등기 전에는 소유자가 아닙니다.","정관으로 이사 기타 임원에게 위임한 사항 외에는 총회가 결의한다 · 통상총회는 이사가 매년 1회 이상 소집한다":"정관으로 임원에게 위임한 사항 외에는 총회가 결의하고, 통상총회는 매년 1회 이상 이사가 소집해요.","정기증여는 증여자 또는 수증자의 사망으로 효력을 잃는다. 사인증여에는 유증 규정을 준용한다":"정기증여는 증여자나 수증자가 죽으면 효력을 잃고 사인증여에는 유증 규정을 준용합니다.","정당한 이익 있는 범위 내에서 토지의 상하에 미친다. 지중의 지하수는 포함된다. 지상권자가 식재한 수목, 완성된 미등기건물, 바다는 토지소유권의 범위에 포함되지 않는다":"토지소유권은 정당한 이익이 있는 범위에서 상하에 미치고 지하수는 포함되지만 바다나 지상권자가 심은 수목 등은 포함되지 않습니다.","정신적 제약으로 사무를 처리할 능력이 부족한 사람에 대한 심판이다. 개시 시 본인의 의사를 고려한다(제9조 제2항 준용)":"한정후견은 사무처리 능력이 부족한 사람에 대한 심판이며 개시할 때 본인의 의사를 고려합니다.","정신적 제약으로 사무를 처리할 능력이 지속적으로 결여된 사람에 대하여, 본인ㆍ배우자ㆍ4촌 이내 친족ㆍ검사 등의 청구로 가정법원이 심판한다. 심판 시 본인의 의사를 고려하여야 한다":"성년후견은 사무처리 능력이 지속적으로 없는 사람에 대해 청구권자의 청구로 가정법원이 심판하며 본인 의사를 고려합니다.","정지조건부 채권(권리)은 조건이 성취된 때부터 시효가 진행한다(성취 전에는 진행하지 않음)":"정지조건부 권리는 조건이 성취된 때부터 시효가 진행하고 성취 전에는 진행하지 않습니다.","정지조건이면 그 법률행위는 무효로 한다":"불능조건이 정지조건이면 그 법률행위는 무효예요.","정지조건이면 조건 없는 법률행위로 한다":"기성조건이 정지조건이면 조건 없는 법률행위가 되어 곧바로 효력이 생깁니다.","정지조건 있는 법률행위는 조건이 성취한 때로부터 효력이 생긴다":"정지조건은 조건이 이루어진 순간부터 법률행위가 비로소 효력을 갖게 하는 조건입니다.","제1000조 제3항(태아의 상속순위)과 제1004조(결격사유)는 수증자에 준용한다. 태아도 수증자가 된다":"태아의 상속순위와 결격사유 규정이 수증자에 준용되므로 태아도 유증을 받을 수 있습니다.","제109조 제1항은 임의규정이므로 당사자의 합의로 적용을 배제할 수 있다(강행규정 아님)":"착오 규정은 임의규정이어서 당사자 합의로 적용을 배제할 수 있습니다.","제137조는 당사자의 합의로 그 적용을 배제할 수 있다":"일부무효 규정은 당사자 합의로 적용을 배제할 수 있습니다.","제148조와 제149조를 기한 있는 법률행위에 준용한다":"조건부 권리의 보호 규정은 기한 있는 법률행위에도 준용됩니다.","제213조, 제214조, 제216조~제244조(소유권 및 상린관계 규정)를 전세권자 간 또는 전세권자와 인지소유자 및 지상권자 간에 준용한다":"소유권 및 상린관계 규정은 전세권자 상호 간 또는 전세권자와 인지소유자·지상권자 사이에 준용합니다.","제214조(방해제거ㆍ예방청구), 제321조(불가분성), 제333조(순위), 제340조, 제341조(물상보증인 구상권), 제342조(물상대위)를 저당권에 준용한다":"저당권에는 방해제거청구, 불가분성, 순위, 물상보증인 구상권, 물상대위 규정이 준용됩니다.","제280조~제287조에 위반되는 계약으로 지상권자에게 불리한 것은 효력이 없다":"지상권 관련 강행규정에 어긋나는 계약 중 지상권자에게 불리한 부분은 효력이 없습니다.","제2매수인이 선의여도 등기는 무효이다":"제2매수인이 선의로 등기를 받았다 해도 그 등기는 무효예요.","제3자: 선의이기만 하면 되고 과실이 있어도 보호된다(무과실 불요). 선의는 추정된다":"통정허위표시의 제3자는 선의이기만 하면 과실이 있어도 보호되고, 선의는 추정됩니다.","제3자가 선택하기로 하는 약정은 유효하다. 선택은 채무자 및 채권자에 대한 의사표시로 하며 채권자 및 채무자의 동의 없이 철회하지 못한다. 제3자가 선택할 수 없는 경우 선택권은 채무자에게 있다. 제3자가 선택하지 않는 경우 채권자나 채무자는 상당 기간을 정해 선택을 최고할 수 있고 그 기간 내에 선택하지 않으면 선택권은 채무자에게 있다":"제3자가 선택하기로 하는 약정은 유효하고, 제3자가 선택할 수 없거나 하지 않으면 선택권은 채무자에게 있어요.","제3자가 악의이더라도 전득자가 선의이면 그 전득자에 대하여 통정허위표시의 무효를 주장할 수 없다":"제3자가 악의여도 전득자가 선의면 그 전득자에게는 허위표시의 무효를 주장할 수 없어요.","제3자는 채권자와의 계약으로 채무를 인수하여 채무자의 채무를 면하게 할 수 있다. 채무의 성질이 인수를 허용하지 않으면 제외. 이해관계 없는 제3자는 채무자의 의사에 반하여 인수하지 못한다":"제3자는 채권자와의 계약으로 채무를 인수할 수 있으나 이해관계 없는 제3자는 채무자의 의사에 반해 인수하지 못해요.","제3자도 변제할 수 있다. 채무의 성질 또는 당사자 의사표시로 허용하지 않는 때는 제외. 이해관계 없는 제3자는 채무자의 의사에 반하여 변제하지 못한다":"제3자도 변제할 수 있으나 성질상 또는 합의로 금지되거나 이해관계 없는 제3자가 채무자 의사에 반하면 안 됩니다.","제3자에 대하여 타인에게 대리권을 수여함을 표시한 자는 그 대리권 범위 내의 행위에 대하여 책임이 있다. 제3자가 대리권 없음을 알았거나 알 수 있었을 때에는 그러하지 아니하다":"대리권을 수여했다고 제3자에게 표시한 자는 그 범위 안의 행위에 책임이 있으나 제3자가 대리권 없음을 알았거나 알 수 있었다면 책임이 없어요.","제3자의 권리가 생긴 후에는 당사자는 이를 변경 또는 소멸시키지 못한다. 채무자는 계약에 기한 항변으로 제3자에게 대항할 수 있다":"제3자의 권리가 생기면 당사자는 이를 변경·소멸시킬 수 없고 채무자는 계약에 기한 항변으로 제3자에게 대항할 수 있어요.","제3자의 행위와 공작물의 설치·보존상의 하자가 공동원인이 되어 발생한 손해도 공작물의 하자에 의하여 발생한 것으로 볼 수 있다":"제3자의 행위와 공작물의 설치·보존 하자가 함께 원인이 된 손해도 공작물의 하자로 인한 것으로 볼 수 있습니다.","제580조·제581조(하자담보)에 의한 권리는 매수인이 그 사실을 안 날부터 6월 내에 행사하여야 한다. 제575조의 제한물권·등기된 임대차 등은 안 날부터 1년":"하자담보 권리는 매수인이 안 날부터 6월 내에 행사하고, 제한물권·등기된 임대차 같은 경우는 안 날부터 1년입니다.","제627조, 제628조, 제631조, 제635조, 제638조, 제640조, 제641조, 제643조~제647조에 위반하는 약정으로 임차인이나 전차인에게 불리한 것은 효력이 없다. 일시사용을 위한 임대차에는 제628조, 제638조, 제640조, 제646조~제648조, 제650조 및 제652조를 적용하지 않는다":"임대차 규정 중 임차인이나 전차인에게 불리한 약정은 효력이 없고 일시사용 임대차에는 일부 규정을 적용하지 않습니다.","제외된 채권자는 귀속권리자에게 인도하지 않은 재산만 청구한다 · 재산이 부족함이 분명하면 청산인은 지체없이 파산선고를 신청·공고한다 · 파산관재인에게 사무를 인계하면 임무가 종료한다":"제외된 채권자는 귀속권리자에게 인도 안 된 재산만 청구하고, 재산이 모자라면 청산인은 지체없이 파산을 신청합니다.","제작물공급계약에서 완성된 목적물의 인도와 동시에 보수를 지급해야 하는 경우, 목적물의 인도는 단순한 점유의 이전만으로 충분하지 않다":"제작물공급계약에서 인도와 동시에 보수를 지급해야 할 때 인도는 단순한 점유 이전만으로는 충분하지 않습니다.","제한능력자, 착오로 인하거나 사기ㆍ강박에 의하여 의사표시를 한 자, 그의 대리인 또는 승계인만이 취소할 수 있다":"취소할 수 있는 사람은 제한능력자, 착오·사기·강박으로 의사표시를 한 자와 그의 대리인 또는 승계인뿐이에요.","제한능력자가 맺은 계약은 추인이 있을 때까지 상대방이 철회할 수 있다. 계약 당시 제한능력자임을 알았던 상대방은 철회할 수 없다(선의만 철회)":"제한능력자와 맺은 계약은 상대방이 추인 전까지 철회할 수 있으나, 제한능력자임을 알았던 상대방은 철회할 수 없어요.","제한능력자가 속임수로 자기를 능력자로 믿게 한 경우 취소할 수 없다. 미성년자나 피한정후견인이 속임수로 법정대리인의 동의가 있는 것으로 믿게 한 경우도 같다. 제1항은 제한능력자 전체(피성년후견인 포함)에 적용된다":"속임수로 능력자로 믿게 한 제한능력자는 취소권을 잃으며, 이 규정은 피성년후견인을 포함한 제한능력자 전체에 적용됩니다.","제한능력자의 단독행위는 추인이 있을 때까지 상대방이 거절할 수 있다":"제한능력자가 혼자 한 단독행위는 추인 전까지 상대방이 받아들이지 않겠다고 거절할 수 있습니다.","조건은 의사표시의 일반원칙에 따라 조건의사와 그 표시가 필요하다":"조건도 의사표시이므로 조건의사와 그 표시가 모두 있어야 합니다.","조건을 붙이거나 변경을 가하여 승낙한 때 그 청약의 거절과 동시에 새로 청약한 것으로 본다":"조건을 붙이거나 변경을 가해 승낙하면 청약을 거절하는 동시에 새로 청약한 것으로 봅니다.","조건의 내용 자체가 불법이어서 무효이면 조건부 법률행위 전부가 무효다":"조건의 내용이 불법이면 그 조건만이 아니라 조건부 법률행위 전체가 무효로 돌아갑니다.","조건의사가 외부로 표시되지 않으면 조건부 법률행위로 인정되지 않는다":"조건을 붙이겠다는 마음이 겉으로 드러나지 않으면 조건부 법률행위로 보지 않습니다.","조건의 성취가 미정한 권리의무는 일반규정에 의하여 처분, 상속, 보존 또는 담보로 할 수 있다":"조건부 권리와 의무도 아직 확정되지 않았을 뿐이어서 일반 규정에 따라 처분하고 상속하고 담보로 삼을 수 있습니다.","조건의 성취로 불이익을 받을 당사자가 신의성실에 반하여 성취를 방해한 때다":"조건 성취로 불이익을 받을 당사자가 신의에 반해 성취를 방해한 경우를 말합니다.","조건의 성취로 생길 상대방의 이익을 해하지 못한다":"조건이 성취되면 생길 상대방의 이익을 해쳐서는 안 됩니다.","조건의 성취로 이익을 받을 당사자가 신의성실에 반하여 조건을 성취시킨 때다":"조건 성취로 이익을 받을 당사자가 신의에 반해 조건을 성취시킨 경우를 말합니다.","조건이 법률행위 당시 이미 성취한 것이면":"조건이 법률행위 당시 이미 성취된 경우를 기성조건이라 합니다.","조건이 법률행위 당시 이미 성취할 수 없는 것이면":"조건이 법률행위 당시 이미 성취할 수 없는 경우를 불능조건이라 해요.","조건이 선량한 풍속 기타 사회질서에 위반한 것인 때 그 법률행위는 무효로 한다":"사회질서에 어긋나는 조건을 붙인 법률행위는 그 자체로 무효입니다.","조건 있는 법률행위의 당사자는 조건의 성부가 미정한 동안":"조건 있는 법률행위의 당사자는 조건의 성부가 정해지지 않은 동안에는 의무를 집니다.","조세ㆍ공과금 기타 부담의 증감이나 경제사정의 변동으로 전세금이 상당하지 아니하게 된 때 당사자는 장래에 대하여 증감을 청구할 수 있다. 증액은 대통령령이 정하는 기준에 따른 비율을 초과하지 못한다":"조세나 경제사정 변동으로 전세금이 상당하지 않게 되면 장래에 대해 증감을 청구할 수 있고 증액은 기준 비율을 넘지 못해요.","존속기간 만료로 소멸한 때 전세권자는 원상회복하고 부속시킨 물건을 수거할 수 있다. 설정자가 부속물 매수를 청구하면 정당한 이유 없이 거절하지 못한다. 설정자 동의를 얻어 부속시킨 물건이나 설정자로부터 매수한 물건은 전세권자가 매수를 청구할 수 있다":"기간 만료로 소멸하면 전세권자는 원상회복하고 부속물을 수거할 수 있으며 설정자의 매수 청구를 정당한 이유 없이 거절하지 못합니다.","존재 여부를 당사자가 주장ㆍ증명하여야 한다(관습법과 다름)":"관습법과 달리 사실인 관습은 존재 여부를 당사자가 직접 주장·증명해야 합니다.","종기(終期) 있는 법률행위는 기한이 도래한 때로부터 효력을 잃는다":"종기가 붙은 법률행위는 기한이 도래한 때부터 효력을 잃어요.","종래의 주소나 거소를 떠난 자. 생존이 분명해도 부재자가 될 수 있다. 법인은 부재자가 될 수 없고 자연인에 한한다":"부재자는 종래의 주소나 거소를 떠난 자연인이며, 생존이 분명해도 될 수 있고 법인은 해당하지 않아요.","종류로만 지정하고 품질을 정할 수 없는 때 채무자는 중등품질의 물건으로 이행한다. 채무자가 이행에 필요한 행위를 완료하거나 채권자의 동의를 얻어 이행할 물건을 지정한 때 그때부터 그 물건이 채권의 목적물이 된다(특정)":"종류채권은 품질을 정할 수 없으면 중등품질로 이행하고, 이행에 필요한 행위를 마치거나 합의로 지정하면 그 물건으로 특정됩니다.","종류로 지정한 목적물이 특정된 후 하자가 있으면 제580조를 준용한다. 매수인은 해제·손해배상을 하지 않고 하자 없는 물건을 청구할 수 있다":"종류매매에서 특정 후 하자가 있으면 매수인은 해제나 손해배상 대신 하자 없는 물건을 청구할 수 있어요.","종물 법리는 물건뿐 아니라 권리 상호간(예: 건물 소유를 위한 지상권)에도 유추적용된다":"종물 법리는 건물 소유를 위한 지상권처럼 권리 상호간에도 유추적용됩니다.","종중 보유 부동산을 종중 외의 자 명의로 등기, 배우자 명의 등기, 종교단체 산하 조직의 부동산을 종교단체 명의로 등기한 경우로서 조세 포탈ㆍ강제집행 면탈ㆍ법령상 제한 회피 목적이 아니면 제4조~제7조를 적용하지 않는다":"종중·배우자·종교단체 명의 등기는 조세 포탈이나 강제집행 면탈 목적이 아니면 법의 일부 규정을 적용하지 않아요.","주된 권리의 소멸시효가 완성한 때에는 종속된 권리에 그 효력이 미친다":"원금 채권의 시효가 끝나면 거기에 딸린 이자 같은 종속된 권리도 함께 소멸합니다.","주무관청은 다음 경우 설립허가를 취소할 수 있다 · 목적 이외의 사업, 설립허가 조건 위반 · 기타 공익을 해하는 행위":"주무관청은 목적 외 사업, 허가 조건 위반, 공익을 해하는 행위가 있으면 설립허가를 취소할 수 있어요.","주물 소유자의 사용에 공여되더라도 주물 자체의 효용과 관계없는 물건은 종물이 아니다":"주물 주인이 쓰고 있어도 주물 자체의 효용과 무관한 물건은 종물이 아닙니다.","주물에 저당권이 설정된 경우 저당권의 효력은 설정 후의 종물에도 미친다":"주물에 설정된 저당권의 효력은 설정 후에 생긴 종물에도 미칩니다.","주물을 점유취득시효로 취득해도 그 효력은 종물에 당연히 미치지 않는다(종물을 점유하지 않았다면 종물에는 효력이 없음)":"주물을 점유취득시효로 취득해도 종물을 점유하지 않았다면 그 효력은 종물에 당연히 미치지 않습니다.","주사무소 이전은 종전 소재지 또는 새 소재지에서 3주일 내 등기한다 · 새 소재지와 이전 연월일을 등기한다 · 같은 등기소 관할구역 내 이전이면 그 이전만 등기한다":"주사무소를 옮기면 종전 또는 새 소재지에서 3주일 내에 새 소재지와 이전 연월일을 등기하며, 같은 관할 안이면 이전만 등기합니다.","주유소 건물의 주유기. 부동산도 종물이 될 수 있다. 저당목적 토지 위의 건물은 종물이 아니라 독립 부동산이다":"주유소 건물의 주유기는 종물이고 부동산도 종물이 될 수 있지만, 저당 토지 위의 건물은 독립 부동산이에요.","주채무의 이자, 위약금, 손해배상 기타 주채무에 종속한 채무를 포함한다. 보증인은 그 보증채무에 관한 위약금 기타 손해배상액을 예정할 수 있다. 부담이 주채무의 목적이나 형태보다 중한 때에는 주채무의 한도로 감축한다":"보증채무는 이자·위약금·손해배상 등 종속 채무를 포함하고 주채무보다 무거우면 주채무 한도로 줄입니다.","주채무자에 대한 시효의 중단은 보증인에 대하여 그 효력이 있다":"주채무자에 대한 시효중단은 보증인에게도 효력이 있어요.","주채무자의 부탁 없이 보증인이 된 자는 주채무자가 그 당시 이익을 받은 한도에서, 주채무자의 의사에 반하여 보증인이 된 자는 현존이익의 한도에서 배상받는다":"부탁 없는 보증인은 주채무자가 그 당시 이익을 받은 한도에서, 의사에 반한 보증인은 현존이익 한도에서 배상받아요.","중간생략등기의 합의가 있어도 중간 매수인 乙의 최초 매도인 甲에 대한 소유권이전등기청구권은 소멸하지 않는다. 甲의 乙에 대한 등기의무도 소멸하지 않는다":"중간생략등기를 합의해도 중간 매수인의 등기청구권과 매도인의 등기의무는 소멸하지 않아요.","중간생략등기 합의가 없으면 최종 매수인 丙은 乙을 대위하여 甲에게 직접 자신에게 이전등기를 청구할 수 없다(甲의 동의 필요)":"중간생략등기 합의가 없으면 최종 매수인은 중간 매수인을 대위해 매도인에게 직접 자기에게 이전하라고 청구할 수 없습니다.","중간생략등기 합의 후 甲과 乙이 매매대금을 인상하기로 약정한 경우 甲은 인상된 대금이 지급되지 않았음을 이유로 丙 명의 이전등기의무의 이행을 거절할 수 있다":"중간생략등기 합의 후 대금을 올리기로 약정했다면 매도인은 인상된 대금을 받기 전까지 이전등기 이행을 거절할 수 있습니다.","중단까지 경과한 기간은 산입하지 않고 중단사유가 종료한 때부터 새로 진행한다. 재판상 청구로 중단된 시효는 재판이 확정된 때부터 새로 진행한다":"중단까지 지난 기간은 산입하지 않고 중단사유가 끝난 때, 재판상 청구는 재판 확정 때부터 새로 진행합니다.","중단의 효력은 당사자 및 그 승계인 간에만 효력이 있다(상대적 효력)":"중단의 효력은 당사자와 그 승계인 사이에서만 생기는 상대적 효력이에요.","중요부분의 착오는 착오로 표의자가 경제적 불이익을 입은 경우에 한한다. 경제적 불이익이 없거나 사후 사정변경으로 소멸하였다면 중요부분의 착오가 아니다":"중요부분의 착오는 착오로 표의자가 경제적 불이익을 입은 경우에 한하며, 불이익이 없거나 사후에 사라지면 해당하지 않아요.","증여, 매매, 교환, 소비대차, 사용대차, 임대차, 고용, 도급, 여행계약, 현상광고, 위임, 임치, 조합, 종신정기금, 화해. 부당이득은 법정채권으로 전형계약이 아니다":"전형계약은 증여, 매매, 교환, 소비대차 등 열다섯 가지이며 부당이득은 법정채권이라 전형계약이 아닙니다.","증여는 당사자 일방이 무상으로 재산을 상대방에 수여하는 의사를 표시하고 상대방이 승낙함으로써 효력이 생긴다(낙성·무상·편무계약)":"증여는 한쪽이 무상으로 재산을 주겠다고 하고 상대방이 승낙하면 성립하는 낙성·무상·편무계약입니다.","증여의 목적인 물건 또는 권리의 하자나 흠결에 대하여 책임을 지지 않는다. 증여자가 알고 고지하지 않은 때는 책임. 상대부담 있는 증여는 부담 한도에서 매도인과 같은 담보책임. 부담부증여에는 쌍무계약 규정을 적용한다":"증여자는 목적물의 하자에 책임이 없지만 알고 알리지 않았다면 책임을 지고, 부담부증여에는 쌍무계약 규정을 적용해요.","증여자의 재산상태가 현저히 변경되고 그 이행이 생계에 중대한 영향을 미칠 경우 증여자는 해제할 수 있다":"증여자의 재산상태가 크게 바뀌어 이행이 생계에 중대한 영향을 미치면 증여자는 해제할 수 있습니다.","증인이 사실을 증언하는 조건으로 통상 용인될 수 있는 수준을 넘는 대가를 지급받기로 한 약정":"증언의 대가로 통상 용인되는 수준을 넘는 금품을 받기로 한 약정은 반사회질서에 해당합니다.","지료가 토지에 관한 조세 기타 부담의 증감이나 지가의 변동으로 상당하지 아니하게 된 때 당사자는 증감을 청구할 수 있다":"조세 부담이나 지가 변동으로 지료가 상당하지 않게 되면 당사자는 증감을 청구할 수 있습니다.","지료연체를 이유로 한 지상권 소멸청구에 의해 지상권이 소멸한 경우 지상권자는 지상물매수청구권을 행사할 수 없다":"지료 연체로 지상권이 소멸한 경우에는 지상권자가 지상물매수청구권을 행사할 수 없어요.","지배권은 소유권, 저당권 등 물권이 대표적이다":"지배권의 대표는 소유권과 저당권 같은 물권이에요.","지분의 비율로 관리비용 기타 의무를 부담한다. 1년 이상 의무이행을 지체한 때 다른 공유자는 상당한 가액으로 그 지분을 매수할 수 있다":"공유자는 지분 비율로 관리비용을 부담하고 1년 이상 지체하면 다른 공유자가 상당한 가액으로 그 지분을 매수할 수 있습니다.","지상권ㆍ전세권ㆍ질권ㆍ사용대차ㆍ임대차ㆍ임치 기타의 관계로 타인으로 하여금 물건을 점유하게 한 자는 간접으로 점유권이 있다. 점유매개관계가 있어야 한다":"임대차·질권 등의 관계로 타인에게 점유하게 한 자는 간접점유권이 있고 점유매개관계가 필요합니다.","지상권 또는 전세권을 목적으로 저당권을 설정한 자는 저당권자의 동의 없이 지상권 또는 전세권을 소멸하게 하는 행위를 하지 못한다":"지상권이나 전세권에 저당권을 설정한 자는 저당권자 동의 없이 그 권리를 소멸시킬 수 없습니다.","지상권 설정계약은 채권행위이므로 토지소유자가 아닌 자도 체결할 수 있다(처분권한은 설정등기 단계의 문제)":"지상권 설정계약은 채권행위라서 토지소유자가 아닌 자도 체결할 수 있습니다.","지상권에 저당권을 설정해 준 지상권자가 토지를 매수해도 혼동으로 지상권이 소멸하지 않는다(제3자의 권리의 목적이므로)":"지상권에 저당권이 설정되어 있으면 지상권자가 토지를 매수해도 혼동으로 소멸하지 않습니다.","지상권을 설정한 토지소유자도 불법점유자에 대하여 물권적 청구권을 행사할 수 있다":"지상권을 내준 토지소유자라도 불법으로 점유하는 사람에게 물권적 청구권을 쓸 수 있습니다.","지상권의 법정갱신은 인정되지 않는다. 갱신 시 존속기간은 갱신한 날부터 최단존속기간보다 단축하지 못한다":"지상권의 법정갱신은 인정되지 않으며 갱신해도 존속기간이 최단존속기간보다 짧아질 수 없어요.","지상권이 소멸한 경우 건물 기타 공작물이나 수목이 현존한 때 지상권자는 계약의 갱신을 청구할 수 있다(청구권). 설정자가 갱신을 원하지 않으면 지상권자는 상당한 가액으로 지상물의 매수를 청구할 수 있다(형성권)":"지상권이 소멸하면 지상권자는 갱신을 청구할 수 있고 설정자가 거절하면 상당한 가액으로 지상물 매수를 청구하는 형성권이 있습니다.","지상권이 소멸한 때 지상권자는 지상물을 수거하여 토지를 원상에 회복하여야 한다. 설정자가 상당한 가액을 제공하여 매수를 청구하면 지상권자는 정당한 이유 없이 거절하지 못한다":"지상권이 소멸하면 지상권자는 지상물을 수거해 원상회복해야 하고 설정자의 매수 청구를 정당한 이유 없이 거절하지 못합니다.","지상권자ㆍ토지임차인의 지상물매수청구권, 법률행위에 대한 동의권이 해당한다":"지상물매수청구권과 법률행위에 대한 동의권도 형성권이에요.","지상권자가 2년 이상의 지료를 지급하지 아니한 때 지상권설정자는 지상권의 소멸을 청구할 수 있다. 지상권이 저당권의 목적이거나 지상 건물ㆍ수목이 저당권의 목적인 경우 저당권자에게 통지한 후 상당한 기간이 경과해야 효력이 생긴다":"지상권자가 2년 이상 지료를 내지 않으면 설정자가 소멸을 청구할 수 있고, 저당권자가 있으면 통지 후 상당 기간이 지나야 효력이 생깁니다.","지상권자는 타인에게 그 권리를 양도하거나 존속기간 내에서 토지를 임대할 수 있다(설정자의 동의 불요). 지상권자는 지상물과 지상권을 분리하여 처분할 수 있다(지상권을 유보하고 지상물만 양도, 지상물을 유보하고 지상권만 양도 모두 가능)":"지상권자는 설정자의 동의 없이 지상권을 양도하거나 임대할 수 있고 지상물과 지상권을 따로 처분할 수도 있어요.","지역권은 20년간 행사하지 않으면 시효로 소멸한다. 불계속지역권도 소멸시효에 걸린다":"지역권은 행사하지 않은 채 20년이 흐르면 시효로 소멸하고 불계속지역권도 예외가 아닙니다.","지역권은 계속되고 표현된 것에 한하여 시효취득할 수 있다. 공유자의 1인이 지역권을 취득한 때 다른 공유자도 이를 취득한다. 점유취득시효 중단은 지역권을 행사하는 모든 공유자에 대한 사유가 아니면 효력이 없다":"지역권은 계속되고 표현된 것에 한해 시효취득할 수 있으며 공유자 한 명이 취득하면 다른 공유자도 취득합니다.","지역권은 요역지 소유권에 부종하여 이전하며 요역지에 대한 소유권 이외의 권리의 목적이 된다. 요역지와 분리하여 양도하거나 다른 권리의 목적으로 하지 못한다":"지역권은 요역지 소유권에 따라 이전하며 요역지와 분리해 양도하거나 다른 권리의 목적으로 하지 못합니다.","지역권자는 방해제거ㆍ방해예방을 청구할 수 있으나 승역지의 반환청구는 할 수 없다":"지역권자는 방해를 없애거나 막도록 청구할 수 있지만 승역지를 돌려 달라고는 못 합니다.","지연손해배상액을 예정한 경우 채권자는 예정배상액의 청구와 함께 본래의 급부이행을 청구할 수 있다":"지연손해배상액을 예정했다면 채권자는 예정배상액과 함께 본래 급부의 이행도 청구할 수 있어요.","지정충당(변제자 우선, 그다음 변제받는 자. 변제자가 즉시 이의하면 불가) → 법정충당 순서 ① 이행기 도래한 것 ② 변제이익이 많은 것 ③ 이행기가 먼저 도래한 것 ④ 채무액에 비례. 비용ㆍ이자ㆍ원본이 있으면 비용, 이자, 원본의 순서로 충당한다":"변제충당은 변제자 지정, 받는 자 지정, 법정충당 순서이며 비용, 이자, 원본의 순서로 채웁니다.","지하 또는 지상의 공간을 상하의 범위를 정하여 ‘건물 기타 공작물’을 소유하기 위한 지상권의 목적으로 할 수 있다(수목 소유를 위한 구분지상권은 인정되지 않는다). 제3자가 토지를 사용ㆍ수익할 권리를 가진 때에도 그 권리자 및 그 권리를 목적으로 하는 권리를 가진 자 전원의 승낙이 있으면 설정할 수 있다(임차권이 설정된 토지에는 임차권자의 승낙 필요)":"구분지상권은 건물·공작물을 위해 지하나 지상 공간의 상하 범위를 정해 설정하며 수목 소유용은 불가합니다.","지하의 미채굴 광물에는 토지소유권이 미치지 않는다. 지중의 지하수는 토지소유권의 범위에 포함된다":"땅속 미채굴 광물은 토지소유권이 미치지 않고, 땅속 지하수는 토지소유권에 속합니다.","직무집행정지ㆍ직무대행자 선임 가처분은 주사무소 등기소에서 등기한다 · 직무대행자는 법원 허가 없이 통상사무에 속하지 않는 행위를 못한다 · 위반해도 법인은 선의의 제3자에게 책임을 진다":"직무집행정지·대행자 선임 가처분도 등기하며, 대행자가 법원 허가 없이 통상사무 밖 행위를 해도 법인은 선의 제3자에게 책임을 집니다.","진의 아닌 의사표시 규정은 상대방 있는 단독행위에도 적용된다":"상대방이 있는 단독행위에서도 진의 아닌 의사표시의 법리가 그대로 적용됩니다.","질권설정자는 질권자의 동의 없이 질권의 목적된 권리를 소멸하게 하거나 질권자의 이익을 해하는 변경을 할 수 없다. 채권질권 설정자가 목적 채권을 양도하는 경우에는 질권자의 동의가 필요하지 않다":"질권설정자는 질권자 동의 없이 목적 권리를 소멸시키거나 질권자 이익을 해치는 변경을 할 수 없지만 채권 양도는 동의가 필요 없어요.","질권설정자는 채무변제기 전의 계약으로 질권자에게 변제에 갈음하여 질물의 소유권을 취득하게 하거나 법률에 정한 방법에 의하지 않고 질물을 처분할 것을 약정하지 못한다":"변제기 전 계약으로 질물 소유권을 취득하거나 법이 정한 방법 외로 처분하기로 하는 유질계약은 금지됩니다.","질권의 목적이 된 채권을 직접 청구할 수 있고, 금전이면 자기 채권 한도에서 직접 청구할 수 있다. 변제기가 질권자의 채권보다 먼저 도래한 때 제3채무자에게 변제금액의 공탁을 청구할 수 있다":"질권자는 질권의 목적인 채권을 직접 청구할 수 있고, 금전이면 자기 채권 한도에서 청구하며 변제기가 먼저 오면 공탁을 청구할 수 있습니다.","질권자는 질물을 경매할 수 있고, 정당한 이유가 있으면 감정자 평가에 의한 직접 변제충당을 법원에 청구할 수 있다(미리 채무자 및 질권설정자에게 통지)":"질권자는 질물을 경매하거나 정당한 이유가 있으면 감정 평가에 의한 직접 변제충당을 법원에 청구할 수 있고 미리 통지해야 해요.","질물로 변제받지 못한 부분의 채권에 한하여 채무자의 다른 재산으로부터 변제받을 수 있다":"질물로 변제받지 못한 부분만 채무자의 다른 재산에서 변제받을 수 있어요.","질물의 멸실ㆍ훼손 또는 공용징수로 설정자가 받을 금전 기타 물건에 대하여도 질권을 행사할 수 있고 지급 또는 인도 전에 압류하여야 한다":"질물의 멸실·훼손이나 공용징수로 설정자가 받을 금전 등에도 질권을 행사할 수 있으나 지급 전에 압류해야 해요.","집합채권의 양도가 양도금지특약 위반으로 무효인 경우 채무자는 일부 개별 채권을 특정하여 추인할 수 있다":"양도금지특약 때문에 무효인 집합채권 양도도 채무자는 개별 채권을 특정해 추인할 수 있습니다.","채권과 채무가 동일한 주체에 귀속한 때 채권은 소멸한다. 그 채권이 제3자의 권리의 목적인 때는 제외":"채권과 채무가 같은 사람에게 귀속하면 채권이 소멸하는 혼동이 생기고 제3자 권리의 목적이면 예외예요.","채권양도, 채무면제, 취소권의 행사, 지상권의 설정이 처분행위이다":"채권양도, 채무면제, 취소권 행사, 지상권 설정은 권리를 직접 바꾸는 처분행위입니다.","채권양도의 통지(관념의 통지), 무주물의 선점, 유실물의 습득":"채권양도의 통지, 무주물 선점, 유실물 습득도 준법률행위로 분류해요.","채권양도의 통지는 양도인이 해야 하나, 양수인이 양도인의 대리인으로서 통지에 관한 위임을 받았다면 양수인에 의한 통지도 유효하다":"채권양도 통지는 양도인이 하는 것이 원칙이지만 양수인이 양도인의 대리인으로 위임받아 통지해도 유효합니다.","채권은 10년, 채권 및 소유권 이외의 재산권은 20년간 행사하지 않으면 소멸시효가 완성한다. 소유권은 소멸시효에 걸리지 않는다":"채권은 10년, 채권과 소유권 외 재산권은 20년 행사하지 않으면 시효로 소멸하며 소유권은 시효로 소멸하지 않습니다.","채권은 양도할 수 있다. 채권의 성질이 양도를 허용하지 않으면 제외. 당사자가 반대의 의사표시(양도금지특약)를 한 경우 양도하지 못하나, 그 의사표시로 선의의 제3자에게 대항하지 못한다":"채권은 양도할 수 있으나 성질상 허용되지 않거나 양도금지특약이 있으면 못하며 선의 제3자에게는 특약으로 대항할 수 없습니다.","채권의 가장양수인으로부터 추심을 위하여 채권을 양수한 자(추심 목적 양수인), 가장소비대차에서 대주의 계약상 지위를 이전받은 자(기출 정답상 제3자 아님으로 처리)":"추심 목적의 가장채권 양수인이나 가장소비대차의 대주 지위를 이전받은 자는 제3자가 아닌 것으로 처리됩니다.","채권의 담보로 채무자 또는 제3자가 제공한 동산을 점유하고 다른 채권자보다 자기 채권의 우선변제를 받을 권리가 있다. 설정은 질권자에게 목적물을 인도함으로써 효력이 생긴다(요물계약)":"질권은 채권 담보로 제공된 동산을 점유하여 다른 채권자보다 우선변제를 받는 권리이며 목적물을 인도해야 효력이 생기는 요물계약이에요.","채권의 매도인이 채무자의 자력을 담보한 때 매매계약 당시의 자력을 담보한 것으로 추정한다. 변제기에 도달하지 아니한 채권의 매도인이 자력을 담보한 때 변제기의 자력을 담보한 것으로 추정한다":"채권 매도인이 채무자의 자력을 담보하면 계약 당시의 자력을, 변제기 미도래 채권이면 변제기의 자력을 담보한 것으로 추정해요.","채권의 목적이 성질 또는 당사자의 의사표시에 의하여 불가분인 경우 각 채권자는 모든 채권자를 위하여 이행을 청구할 수 있고 채무자는 모든 채권자를 위하여 각 채권자에게 이행할 수 있다. 불가분채권자 중 1인의 행위나 1인에 관한 사항은 원칙적으로 다른 채권자에게 효력이 없다":"불가분채권은 각 채권자가 모두를 위해 이행을 청구할 수 있고 한 사람에 관한 사항은 원칙적으로 다른 채권자에게 효력이 없어요.","채권의 목적이 수개의 행위 중에서 선택에 좇아 확정될 경우 법률의 규정이나 약정이 없으면 선택권은 채무자에게 있다":"여러 행위 중 선택하는 선택채권은 법률이나 약정이 없으면 선택권이 채무자에게 있습니다.","채권의 준점유자에 대한 변제는 변제자가 선의이며 과실 없는 때에 한하여 효력이 있다. 영수증 소지자에 대한 변제는 권한이 없어도 효력이 있으나 변제자가 권한 없음을 알았거나 알 수 있었을 경우는 제외. 그 외 권한 없는 자에 대한 변제는 채권자가 이익을 받은 한도에서 효력":"준점유자에게 선의·무과실로 변제하면 유효하고, 영수증 소지자나 권한 없는 자에게 한 변제도 일정 요건에서 효력이 있습니다.","채권자가 공탁을 승인하거나 공탁소에 받기를 통고하거나 공탁유효의 판결이 확정되기까지는 회수할 수 있다. 질권 또는 저당권이 공탁으로 소멸한 때는 회수 불가":"채권자가 공탁을 승인하거나 받기를 통고하거나 유효 판결이 확정되기 전까지 회수할 수 있고 질권·저당권이 소멸하면 회수할 수 없습니다.","채권자가 변제를 받지 아니하거나 받을 수 없는 때(과실 없이 채권자를 알 수 없는 경우 포함) 변제자는 변제의 목적물을 공탁하여 채무를 면할 수 있다":"채권자가 변제를 받지 않거나 받을 수 없으면 변제자는 목적물을 공탁해 채무를 면할 수 있습니다.","채권자가 보증인에게 이행을 청구한 때 보증인은 주채무자의 변제자력이 있는 사실 및 집행이 용이할 것을 증명하여 먼저 주채무자에게 청구할 것과 그 재산에 집행할 것을 항변할 수 있다. 연대보증인은 불가. 채권자의 해태로 변제받지 못한 경우 해태하지 않았으면 변제받았을 한도에서 보증인은 의무를 면한다":"보증인은 주채무자의 자력과 집행 용이를 증명해 최고·검색의 항변을 할 수 있으나 연대보증인은 불가하고 채권자 해태 시 그 한도에서 면책됩니다.","채권자가 상당한 기간을 정하여 이행을 최고하여도 그 기간 내에 이행하지 않거나 지체 후의 이행이 채권자에게 이익이 없는 때 수령을 거절하고 이행에 갈음한 손해배상을 청구할 수 있다":"채권자가 최고했는데도 이행하지 않거나 지체 후 이행이 이익이 없으면 수령을 거절하고 전보배상을 청구할 수 있습니다.","채권자가 이행을 받을 수 없거나 받지 아니한 때 이행의 제공 있는 때부터 지체책임이 있다":"채권자가 이행을 받을 수 없거나 받지 않으면 이행 제공이 있은 때부터 채권자지체의 책임이 생깁니다.","채권자가 채권의 목적인 물건 또는 권리의 가액 ‘전부’를 손해배상으로 받은 때 채무자는 그 물건 또는 권리에 관하여 당연히 채권자를 대위한다(일부만 받은 경우에는 소유권을 취득하지 않는다)":"채권자가 목적물 가액 전부를 손해배상으로 받으면 채무자가 당연히 그 물건·권리를 대위하고 일부만 받으면 취득하지 않습니다.","채권자가 채무자를 직접점유자로 하여 유치물을 간접점유하는 경우 유치권은 성립하지 않는다":"채권자가 채무자를 직접점유자로 두고 간접점유만 하는 경우에는 유치권이 인정되지 않습니다.","채권자가 채무자에게 채무를 면제하는 의사표시를 한 때 채권은 소멸한다. 면제로써 정당한 이익을 가진 제3자에게 대항하지 못한다":"채권자가 채무를 면제하는 의사표시를 하면 채권이 소멸하며 정당한 이익을 가진 제3자에게 대항하지 못합니다.","채권자나 채무자가 선택하는 경우 상대방에 대한 의사표시로 하며 상대방의 동의 없이 철회하지 못한다":"선택은 상대방에 대한 의사표시로 하며 상대방의 동의 없이 철회할 수 없습니다.","채권자나 채무자가 수인인 경우 특별한 의사표시가 없으면 각 채권자 또는 채무자는 균등한 비율로 권리가 있고 의무를 부담한다(원칙)":"채권자나 채무자가 여럿이면 특별한 의사표시가 없는 한 균등한 비율로 권리를 갖고 의무를 부담합니다.","채권자는 어느 연대채무자에 대하여 또는 동시나 순차로 모든 연대채무자에 대하여 채무의 전부나 일부의 이행을 청구할 수 있다":"채권자는 연대채무자 중 누구에게든, 또는 동시나 순차로 모두에게 전부나 일부 이행을 청구할 수 있습니다.","채권자는 자기의 채권을 보전하기 위하여 채무자의 권리를 행사할 수 있다. 일신에 전속한 권리는 제외. 채권의 기한이 도래하기 전에는 법원의 허가 없이 행사하지 못하나 보전행위는 예외":"채권자는 자기 채권 보전을 위해 채무자의 권리를 대신 행사할 수 있으나 일신전속권은 제외하고 기한 전에는 법원 허가가 필요합니다.","채권자의 승낙에 의하여 효력이 생긴다. 승낙 또는 거절의 상대방은 채무자나 제3자다. 제3자나 채무자는 상당 기간을 정해 승낙 여부의 확답을 최고할 수 있고 채권자가 기간 내에 확답을 발송하지 않으면 거절한 것으로 본다":"채무자와 인수인 간 계약은 채권자의 승낙으로 효력이 생기고 확답을 최고했는데 기간 내 답이 없으면 거절한 것으로 봅니다.","채권자의 승낙이 있을 때까지 당사자는 인수를 철회하거나 변경할 수 있다. 승낙은 다른 의사표시가 없으면 인수한 때로 소급하나 제3자의 권리를 침해하지 못한다":"채권자의 승낙 전에는 철회·변경할 수 있고 승낙은 인수한 때로 소급하되 제3자 권리를 해치지 못해요.","채권자의 책임 있는 사유로 이행할 수 없게 된 때 채무자는 상대방의 이행을 청구할 수 있다. 채권자의 수령지체 중에 쌍방의 책임 없는 사유로 이행할 수 없게 된 때에도 같다. 채무자는 자기 채무를 면함으로써 얻은 이익을 채권자에게 상환하여야 한다":"채권자 책임으로 불능이 되면 채무자는 반대급부를 청구할 수 있고 면한 이익은 채권자에게 상환해야 해요.","채권자취소권은 법원에 취소 및 원상회복을 청구한다":"채권자취소권은 법원에 취소와 원상회복을 청구하는 방식으로 행사하는 형성권이에요.","채권증서가 있는 때 질권설정은 증서를 질권자에게 교부함으로써 효력이 생긴다. 임대차보증금반환채권에 질권을 설정할 때 임대차계약서를 교부하지 않아도 채권질권은 성립한다(증서 교부가 필요한 채권증서가 아니므로)":"채권증서가 있으면 증서를 교부해야 질권설정이 효력이 생기며, 임대차계약서가 채권증서가 아니면 교부 없이도 질권이 성립합니다.","채권증서의 반환은 변제가 먼저 이루어진 후의 문제이며 변제와 동시이행 관계가 아니다(변제가 선이행)":"채권증서 반환은 변제가 먼저 이뤄진 뒤의 문제여서 변제와 동시이행 관계가 아닙니다.","채무가 법률행위(의사표시)를 목적으로 한 때: 채무자의 의사표시에 갈음할 재판을 청구할 수 있다(채무자의 비용으로 제3자에게 하게 하는 것이 아니다)":"채무가 의사표시를 목적으로 하면 채무자의 의사표시에 갈음할 재판을 청구하며 제3자에게 시키는 방식이 아닙니다.","채무내용에 좇은 현실제공으로 하여야 한다. 채권자가 미리 변제받기를 거절하거나 채무의 이행에 채권자의 행위를 요하는 경우 변제준비의 완료를 통지하고 수령을 최고하면 된다. 변제의 제공은 그때부터 채무불이행의 책임을 면하게 한다(채권이 소멸하는 것은 아니다)":"변제의 제공은 현실제공이 원칙이고 거절 시 준비 완료를 통지하면 되며 제공은 채무불이행책임을 면하게 할 뿐 채권을 소멸시키지는 않아요.","채무불이행에 관하여 채권자에게 과실이 있는 때 법원은 손해배상의 책임 및 그 금액을 정함에 이를 참작하여야 한다(채무자의 주장이 없어도 직권으로 참작)":"채권자에게 과실이 있으면 법원은 배상 책임과 금액을 정할 때 이를 참작해야 하며 채무자의 주장이 없어도 직권으로 합니다.","채무불이행으로 인한 손해배상청구권은 특별한 사정이 없는 한 채무를 불이행한 때부터 진행한다":"채무불이행에 따른 손해배상 청구권은 원칙적으로 채무를 어긴 그때부터 시효가 흐릅니다.","채무 없는 자가 착오로 변제한 경우 그 변제가 도의관념에 적합한 때에는 반환을 청구하지 못한다":"채무 없는 자가 착오로 변제했어도 도의관념에 적합하면 반환을 청구하지 못해요.","채무 없음을 알고 변제한 때에는 반환을 청구하지 못한다":"채무가 없다는 것을 알고 갚은 사람은 나중에 그 돈을 돌려 달라고 하지 못합니다.","채무 없음을 알면서도 자기의 자유로운 의사에 반하여 변제를 강제당한 경우 변제자는 부당이득반환청구권을 상실하지 않는다":"채무 없음을 알면서도 자유로운 의사에 반해 변제를 강제당했다면 부당이득반환청구권을 잃지 않습니다.","채무의 변제로 타인의 물건을 인도한 채무자는 다시 유효한 변제를 하지 아니하면 그 물건의 반환을 청구하지 못한다. 채권자가 변제로 받은 물건을 선의로 소비하거나 타인에게 양도한 때 그 변제는 효력이 있다(채권 소멸). 그 전에는 소유자가 반환을 청구할 수 있다":"타인 물건으로 변제한 채무자는 다시 유효하게 갚지 않으면 반환 청구를 못 하고, 채권자가 선의로 소비·양도하면 변제가 유효해집니다.","채무의 승인은 의사표시가 아니라 관념의 통지다":"채무 승인은 의사를 표시하는 행위가 아니라 사실을 알려 주는 관념의 통지입니다.","채무자, 담보가등기목적 부동산의 물상보증인, 담보가등기 후 소유권을 취득한 제3자":"채무자등에는 채무자, 물상보증인, 담보가등기 후 소유권을 취득한 제3자가 포함됩니다.","채무자가 담보를 손상ㆍ감소 또는 멸실하게 한 때, 또는 담보제공의 의무를 이행하지 않은 때 기한의 이익을 주장하지 못한다":"채무자가 담보를 손상·감소·멸실시키거나 담보제공 의무를 이행하지 않으면 기한의 이익을 주장하지 못합니다.","채무자가 담보 목적의 가등기를 설정해 주는 것은 채무의 승인에 해당하나, 가등기가 계속되는 동안 시효가 진행하지 않는다는 뜻은 아니다":"담보 목적 가등기를 설정해 주는 것은 채무 승인이지만 가등기가 있는 동안 시효가 멈춘다는 뜻은 아닙니다.","채무자가 목적물을 보관시킨 제3자가 귀책사유 없이 이를 잃어버린 경우 채권자는 그 제3자에게 손해배상을 청구할 수 없다":"채무자가 맡긴 제3자가 귀책사유 없이 목적물을 잃어버렸다면 채권자는 그 제3자에게 손해배상을 청구할 수 없습니다.","채무자가 보증인을 세울 의무가 있는 경우 행위능력 및 변제자력이 있는 자여야 한다. 자력이 없게 되면 채권자는 변경을 청구할 수 있다. 채권자가 지명한 경우는 적용하지 않는다. 채무자는 다른 상당한 담보를 제공하여 보증인을 세울 의무를 면할 수 있다":"보증인을 세울 의무가 있으면 행위능력과 변제자력이 있어야 하고 자력을 잃으면 변경을 청구할 수 있으며 다른 담보로 의무를 면할 수 있어요.","채무자가 이의를 보류하지 않고 승낙한 때 양도인에게 대항할 수 있는 사유로 양수인에게 대항하지 못한다. 양도인이 통지만 한 때 채무자는 통지를 받은 때까지 양도인에 대하여 생긴 사유로 양수인에게 대항할 수 있다(통지 전 일부 변제 등)":"이의 없이 승낙하면 양도인에게 대항할 수 있던 사유로 양수인에게 대항하지 못하고 통지만 있었다면 통지 전 사유로는 대항할 수 있습니다.","채무자가 임의로 이행하지 않은 때 채권자는 강제이행을 법원에 청구할 수 있다. 채무의 성질이 강제이행을 허락하지 않는 때는 제외. 강제이행과 별도로 손해배상을 청구할 수 있다":"채무자가 임의로 이행하지 않으면 법원에 강제이행을 청구할 수 있고 손해배상도 따로 청구할 수 있어요.","채무자가 채권자를 해함을 알고 재산권을 목적으로 한 법률행위를 한 때 채권자는 그 취소 및 원상회복을 법원에 청구할 수 있다. 수익자나 전득자가 행위 또는 전득 당시 채권자를 해함을 알지 못한 경우는 제외. 취소원인을 안 날부터 1년, 법률행위 있은 날부터 5년 내에 제기한다":"채무자가 채권자를 해함을 알고 한 재산행위는 취소와 원상회복을 청구할 수 있고 안 날부터 1년, 행위일부터 5년 내에 제기합니다.","채무자가 채권자의 승낙을 얻어 본래의 채무이행에 갈음하여 다른 급여를 한 때 변제와 같은 효력이 있다":"채권자의 승낙을 얻어 본래 채무 이행 대신 다른 급여를 하면 변제와 같은 효력이 있는 대물변제입니다.","채무자가 채무의 내용에 좇은 이행을 하지 아니한 때 채권자는 손해배상을 청구할 수 있다. 채무자의 고의나 과실 없이 이행할 수 없게 된 때에는 책임이 없다(귀책사유 필요)":"채무자가 채무내용에 좇은 이행을 하지 않으면 손해배상을 청구할 수 있으나 고의·과실 없이 불능이 된 때는 책임이 없습니다.","채무자는 상당한 담보를 제공하고 유치권의 소멸을 청구할 수 있다. 유치물 소유자(채무자가 아닌 자)도 가능하다":"채무자는 상당한 담보를 제공하고 유치권의 소멸을 청구할 수 있으며 유치물 소유자도 청구할 수 있어요.","채무자는 자기에게 과실이 없는 경우에도 이행지체 중에 생긴 손해를 배상하여야 한다. 이행기에 이행하여도 손해를 면할 수 없는 경우는 제외":"채무자는 과실이 없어도 이행지체 중 생긴 손해를 배상해야 하며 제때 이행해도 손해를 면할 수 없는 경우는 제외됩니다.","채무자등은 청산금채권을 변제받을 때까지 채무액을 지급하고 소유권이전등기의 말소를 청구할 수 있다. 단 변제기가 지난 때부터 10년이 지나거나 선의의 제3자가 소유권을 취득한 경우는 제외":"채무자등은 청산금을 받을 때까지 채무액을 갚고 등기말소를 청구할 수 있으나 변제기 후 10년이 지나거나 선의의 제3자가 취득했다면 제외됩니다.","채무자 또는 제3자가 점유를 이전하지 않고 채무의 담보로 제공한 부동산에 대하여 다른 채권자보다 자기채권의 우선변제를 받을 권리":"저당권은 점유를 넘기지 않고 담보로 제공된 부동산에서 다른 채권자보다 먼저 변제받는 담보물권입니다.","채무자 아닌 자가 착오로 타인의 채무를 변제한 경우 채권자가 선의로 증서를 훼멸하거나 담보를 포기하거나 시효로 채권을 잃은 때 변제자는 반환을 청구하지 못한다. 변제자는 채무자에게 구상권을 행사할 수 있다":"채무자 아닌 자가 착오로 갚았는데 채권자가 선의로 증서를 없애거나 담보를 포기했다면 반환을 청구하지 못하고 채무자에게 구상합니다.","채무자의 과실로 목적물이 소실된 경우 채권자는 이행불능에 따른 손해배상을 청구할 수 있다. 이미 대금을 지급한 후 불가항력으로 목적물이 소실되면 채권자는 부당이득을 이유로 대금 반환을 청구할 수 있다":"채무자의 과실로 목적물이 소실되면 채권자는 손해배상을 청구하고, 대금 지급 후 불가항력 소실이면 부당이득으로 대금 반환을 청구할 수 있습니다.","채무자의 귀책사유 없이 목적물이 멸실되면 채무는 소멸하고 쌍무계약이면 위험부담(제537조)의 문제가 된다. 채권자 소유권이전청구권도 소멸한다":"귀책사유 없이 목적물이 멸실되면 채무가 소멸하고 쌍무계약이면 위험부담 문제가 되며 채권자의 이전청구권도 소멸합니다.","채무자의 법정대리인이 채무자를 위하여 이행하거나 채무자가 타인을 사용하여 이행하는 경우 법정대리인 또는 피용자의 고의나 과실은 채무자의 고의나 과실로 본다":"법정대리인이나 채무자가 쓴 피용자의 고의·과실은 채무자의 고의·과실로 봅니다.","채무자의 일신에 전속하지 않는 작위를 목적으로 한 때: 채무자의 비용으로 제3자에게 이를 하게 할 것을 법원에 청구할 수 있다. 부작위 채무 위반 시 채무자의 비용으로 위반한 것을 제각하고 장래에 대한 적당한 처분을 청구할 수 있다":"일신전속이 아닌 작위는 채무자 비용으로 제3자에게 시키도록 청구하고, 부작위 위반은 위반한 것을 제각하고 적당한 처분을 청구해요.","채무자의 채권자가 목적물에 대한 강제경매를 신청하여 절차가 진행 중이라는 사유만으로는 채무가 이행불능이 되지 않는다":"채무자의 채권자가 강제경매를 신청해 진행 중이라는 사유만으로는 이행불능이 되지 않아요.","채무자의 책임 있는 사유로 이행이 불능하게 된 때 채권자는 계약을 해제할 수 있다. 이행불능을 이유로 해제할 때는 자기 채무(잔대금)의 이행제공이 필요하지 않다. 채권자의 귀책사유로 인한 이행불능이면 채권자는 해제할 수 없다":"채무자 책임으로 이행불능이 되면 채권자는 해제할 수 있고 자기 채무의 이행제공 없이 해제할 수 있으나 채권자 귀책의 불능이면 해제할 수 없어요.","채무자의 허위 저당권설정행위(통정허위표시)는 채권자취소권의 대상이 될 수 있다":"채무자의 허위 저당권설정은 통정허위표시이며 사해행위라면 채권자취소권의 대상도 됩니다.","책임능력 없는 자를 감독할 법정의무가 있는 자가 손해를 배상할 책임이 있다. 감독의무를 게을리하지 않은 경우(자신의 과실 없음 증명)에는 면책된다. 감독의무자를 갈음하여 감독하는 자(대리감독자)도 같다":"책임능력 없는 자를 감독할 법정의무자와 대리감독자가 배상하되 감독의무를 게을리하지 않았음을 증명하면 면책됩니다.","책임능력 있는 미성년자의 불법행위: 감독의무자(친권자)의 감독의무 위반과 손해 사이에 상당인과관계를 피해자가 증명하면 감독의무자는 일반불법행위(제750조)에 따른 손해배상책임을 진다":"책임능력 있는 미성년자의 불법행위에서는 피해자가 감독의무 위반과 손해 사이의 상당인과관계를 증명하면 감독의무자가 일반불법행위 책임을 집니다.","처마물이 이웃에 직접 낙하하지 않도록 적당한 시설을 하여야 한다":"처마물이 이웃에 곧바로 떨어지지 않도록 적당한 시설을 해야 해요.","처분문서가 존재해도 그 기재내용과 다른 묵시적 약정이 인정되면 기재내용을 달리 인정할 수 있다":"처분문서의 글과 다른 묵시적 약정이 인정되면 기재와 달리 계약 내용을 인정할 수 있습니다.","천재 기타 사변으로 중단할 수 없을 때에는 그 사유가 종료한 때부터 1월 내에는 시효가 완성하지 않는다":"천재지변 등으로 중단 조치를 못 하면 그 사유가 끝난 후 1월 동안은 시효가 완성되지 않습니다.","철회나 거절의 의사표시는 제한능력자에게도 할 수 있다":"철회나 거절의 의사표시는 제한능력자 본인에게 해도 효력이 있습니다.","청구권의 행사를 일시 저지할 뿐 청구권 자체를 소멸시키지 않는다":"연기적 항변권은 청구권의 행사를 잠시 막을 뿐 청구권 자체를 소멸시키지는 않습니다.","청산 규정에 어긋나는 특약으로 채무자등에게 불리한 것은 무효다. 단 청산기간이 지난 후의 특약으로 제3자의 권리를 침해하지 않는 것은 유효하다":"청산 규정에 어긋나 채무자등에게 불리한 특약은 무효이나 청산기간 후 제3자 권리를 해치지 않는 특약은 유효합니다.","청산금 = 통지 당시 담보목적부동산의 가액 - 채권액. 소유권이전등기를 마친 경우는 청산기간 후 청산금을 지급한 때 소유권을 취득하고, 담보가등기를 마친 경우는 청산기간이 지나야 본등기를 청구할 수 있다. 청산금 지급채무와 소유권이전등기ㆍ인도채무는 동시이행 관계다":"청산금은 통지 당시 부동산 가액에서 채권액을 뺀 금액이며, 청산금 지급채무와 이전등기·인도채무는 동시이행 관계예요.","청산인의 직무는 ① 현존사무의 종결 ② 채권의 추심 및 채무의 변제 · ③ 잔여재산의 인도이다 · 직무를 행하기 위하여 필요한 모든 행위를 한다":"청산인의 직무는 현존사무 종결, 채권 추심과 채무 변제, 잔여재산 인도입니다.","청산인이 될 자가 없거나 결원으로 손해가 생길 염려가 있는 경우다 · 법원이 직권 또는 이해관계인ㆍ검사의 청구에 의해 선임한다 · 중요한 사유가 있으면 법원이 해임할 수 있다":"청산인이 없거나 결원으로 손해 염려가 있으면 법원이 직권 또는 청구로 선임하고 중요한 사유가 있으면 해임할 수 있어요.","청산종결은 3주간 내에 등기하고 주무관청에 신고한다(감사 아님) · 청산사무가 안 끝났다면 종결등기 후에도 법인은 소멸하지 않는다":"청산종결은 3주간 내에 등기하고 주무관청에 신고하되, 사무가 남았다면 종결등기 후에도 법인은 소멸하지 않아요.","청산 중의 법인은 청산의 목적범위 내에서만 권리가 있고 의무를 부담한다 · 청산인은 해산 시(파산 제외) 이사가 된다 · 정관 또는 총회 결의로 달리 정할 수 있다":"청산 중 법인은 청산 목적 범위에서만 권리와 의무를 가지며, 청산인은 해산 시 이사가 맡는 것이 원칙입니다.","청약자가 그 기간 내에 승낙의 통지를 받지 못한 때 효력을 잃는다(계약이 성립하지 않음). 승낙의 통지가 기간 후에 도달한 경우 보통 그 기간 내에 도달할 수 있는 발송이었다면 청약자는 지체 없이 연착의 통지를 하여야 하고, 하지 않으면 연착되지 않은 것으로 본다":"승낙기간이 있는 청약은 기간 내 승낙을 받지 못하면 효력을 잃고, 연착된 승낙은 연착통지를 안 하면 연착되지 않은 것으로 봅니다.","청약자가 상당한 기간 내에 승낙의 통지를 받지 못한 때 효력을 잃는다. 연착된 승낙은 청약자가 새 청약으로 볼 수 있다":"기간을 정하지 않은 청약은 상당한 기간 내에 승낙을 받지 못하면 효력을 잃고 연착된 승낙은 새 청약으로 볼 수 있습니다.","청약자의 의사표시나 관습에 의하여 승낙의 통지가 필요하지 않은 경우 계약은 승낙의 의사표시로 인정되는 사실이 있는 때 성립한다":"청약자의 의사표시나 관습으로 승낙 통지가 필요 없으면 승낙으로 인정되는 사실이 있는 때 계약이 성립합니다.","총유는 법인 아닌 사단의 사원이 집합체로서 물건을 소유할 때이다 · 관리ㆍ처분과 보존행위는 총회 결의를 요하며 규약에 좇아 사용ㆍ수익 · 개인은 특별한 사정이 없는 한 보존 소를 단독 제기할 수 없다":"총유는 비법인사단 사원이 집합체로서 물건을 소유하는 것으로, 관리·처분은 총회 결의를 거치고 개인은 단독으로 보존 소를 낼 수 없어요.","총회는 소집통지에 목적사항으로 기재한 사항만 결의할 수 있다 · 정관에 다른 규정이 있으면 그에 의한다 · 기재하지 않은 사항의 결의는 특별한 사정이 없는 한 무효다":"총회는 통지에 목적사항으로 적은 사항만 결의할 수 있고, 적지 않은 사항의 결의는 특별한 사정이 없으면 무효입니다.","최고는 6월 내에 재판상 청구, 파산절차참가, 화해를 위한 소환, 임의출석, 압류ㆍ가압류ㆍ가처분을 하지 않으면 시효중단 효력이 없다(내용증명 이행청구도 최고)":"최고는 6월 내에 재판상 청구 등을 하지 않으면 중단 효력이 없으며 내용증명 이행청구도 최고예요.","최소한의 기둥과 지붕 그리고 주벽이 이루어지면 사회통념상 독립된 부동산으로서 건물로 인정될 수 있다":"기둥과 지붕, 주벽이 최소한 갖춰지면 사회통념상 독립된 건물로 인정될 수 있습니다.","추인은 추인권자가 그 행위가 취소할 수 있는 것임을 알고 하여야 한다":"추인은 추인권자가 그 행위가 취소할 수 있는 것임을 알고 해야 효력이 있어요.","추인할 수 있는 날부터 3년이 경과하면 법률행위일부터 10년이 지나지 않았어도 취소할 수 없다":"추인할 수 있는 날부터 3년이 지나면 법률행위일부터 10년이 안 되었어도 취소할 수 없어요.","출생 시(전부노출)부터다. 출생신고나 가족관계등록부 기재가 있어야 인정되는 것이 아니다":"권리능력은 태어나는 때, 곧 전부노출 때부터 생기며 출생신고나 등록부 기재와 상관없습니다.","출연재산이 재단법인의 기본재산인지 여부는 착오에 의한 출연행위의 취소에 영향을 주지 않는다":"출연재산이 기본재산인지 아닌지는 착오 취소 여부를 가르는 사유가 되지 못합니다.","취득시효기간 중 계속해서 등기명의자가 동일한 경우 점유개시 후 임의의 시점을 시효기간의 기산점으로 삼을 수 있다":"등기명의자가 시효기간 중 계속 같다면 점유개시 후 임의의 시점을 기산점으로 삼을 수 있습니다.","취득시효와 소멸시효의 비교: 취득시효 완성의 효력은 점유개시 시로 소급한다":"취득시효가 완성되면 그 효력은 점유를 시작한 때로 소급합니다.","취득시효의 효력은 점유를 개시한 때에 소급한다. 소멸시효 중단 규정이 준용된다. 소유권 이외의 재산권에도 준용한다":"취득시효의 효력은 점유를 개시한 때로 소급하며 소멸시효 중단 규정이 준용됩니다.","취소권은 추인할 수 있는 날로부터 3년 내에, 법률행위를 한 날로부터 10년 내에 행사하여야 한다(둘 중 먼저 도래하는 기간)":"취소권은 추인할 수 있는 날부터 3년, 법률행위를 한 날부터 10년 중 먼저 오는 기간 내에 행사해야 합니다.","취소된 법률행위는 처음부터 무효로 본다. 제한능력자는 받은 이익이 현존하는 한도에서 상환할 책임이 있다":"취소하면 처음부터 무효로 보며, 제한능력자는 받은 이익이 현존하는 한도에서 돌려줄 책임이 있습니다.","취소된 법률행위는 처음부터 무효로 본다. 제한능력자는 받은 이익이 현존하는 한도에서 상환할 책임이 있다(선악 불문, 이자 가산 없음)":"취소된 법률행위는 처음부터 무효이고, 제한능력자는 선악과 상관없이 현존이익 한도에서 돌려주며 이자는 붙지 않습니다.","취소와 원상회복은 모든 채권자의 이익을 위하여 효력이 있다. 통정허위표시로 무효인 법률행위도 채권자취소권의 대상이 될 수 있다":"채권자취소의 결과는 일부 채권자가 아니라 모든 채권자의 이익을 위해 효력을 갖습니다.","취소원인을 안 날부터 1년ㆍ법률행위 있은 날부터 5년 내에 제기한다":"채권자취소의 소는 취소원인을 안 날로부터 1년, 법률행위일로부터 5년 안에 제기해야 합니다.","취소의 원인이 소멸된 후에 하여야 효력이 있다. 법정대리인 또는 후견인이 추인하는 경우에는 적용하지 아니한다":"추인은 취소 원인이 없어진 뒤에 해야 효력이 있으나 법정대리인이나 후견인이 추인하는 경우에는 이 요건이 적용되지 않아요.","취소할 수 있는 법률행위는 제140조의 취소권자가 추인할 수 있고 추인 후에는 취소하지 못한다. 추인의 상대방은 취소와 같다(제142조 준용)":"취소권자는 취소할 수 있는 행위를 추인할 수 있고, 추인 뒤에는 취소하지 못하며 추인의 상대방은 취소와 같습니다.","취소할 수 있는 법률행위를 추인한 취소권자는 특별한 사정이 없는 한 다시 취소할 수 없다":"추인한 취소권자는 특별한 사정이 없는 한 다시 취소할 수 없어요.","취소할 수 있는 법률행위를 취소한 후에도 무효행위 추인의 요건을 갖추면 다시 추인할 수 있다(새로운 법률행위로 봄)":"취소 후에도 무효행위 추인의 요건을 갖추면 다시 추인할 수 있으며, 이는 새로운 법률행위로 봅니다.","취소할 수 있는 법률행위의 상대방이 확정한 경우에는 그 상대방에 대한 의사표시로 하여야 한다":"취소할 수 있는 법률행위의 상대방이 정해져 있으면 그 상대방에게 의사표시를 해야 해요.","취임한 날로부터 2월 내에 3회 이상 공고로 채권신고를 최고한다 · 일정 기간(2월 이상) 내 미신고 시 청산에서 제외된다고 표시한다 · 알고 있는 채권자는 각각 최고하고 제외하지 못한다":"청산인은 취임일부터 2월 내에 3회 이상 공고로 채권신고를 최고하며, 알고 있는 채권자는 청산에서 제외하지 못해요.","타인을 사용하여 어느 사무에 종사하게 한 자는 피용자가 사무집행에 관하여 제3자에게 가한 손해를 배상할 책임이 있다. 사용자가 피용자의 선임 및 사무감독에 상당한 주의를 한 때 또는 상당한 주의를 하여도 손해가 있을 경우에는 면책된다. 사용자에 갈음하여 사무를 감독하는 자도 책임이 있다. 사용자·감독자는 피용자에게 구상권을 행사할 수 있다":"사용자는 피용자가 사무집행 중 입힌 손해를 배상하되 선임·감독에 상당한 주의를 했으면 면책되며 피용자에게 구상할 수 있습니다.","타인의 기망으로 동기의 착오가 발생한 경우 사기와 착오의 경합이 인정될 수 있다":"타인의 속임으로 동기의 착오가 생기면 사기와 착오가 경합할 수 있어요.","타인의 물건 또는 유가증권을 점유한 자는 그 물건이나 유가증권에 관하여 생긴 채권이 변제기에 있는 경우 변제를 받을 때까지 유치할 권리가 있다. 점유가 불법행위로 인한 경우에는 적용하지 않는다":"타인의 물건을 점유한 사람은 그 물건에 관해 생긴 채권의 변제기가 되면 변제받을 때까지 유치할 수 있고 불법행위로 점유한 경우에는 안 됩니다.","타인의 물건을 관리하기 위한 점유, 계약명의신탁의 명의신탁자 점유, 공유자 1인이 공유부동산 전부를 점유할 때 다른 공유자 지분비율 범위의 점유, 무허가건물 부지가 타인 소유임을 알면서 건물만 매수한 자의 그 부지 점유":"남의 물건 관리 점유, 계약명의신탁자의 점유, 다른 공유자 지분 범위의 점유 등은 타주점유의 예예요.","타인의 불법행위에 대하여 자기 또는 제3자의 이익을 방위하기 위하여 부득이 타인에게 손해를 가한 자는 배상책임이 없다. 단 피해자는 불법행위에 대하여 손해배상을 청구할 수 있다. 급박한 위난을 피하기 위한 긴급피난에 준용한다":"타인의 불법행위에 대해 부득이 손해를 가한 정당방위자는 배상책임이 없고 피해자는 불법행위자에게 청구할 수 있으며 긴급피난에 준용해요.","타인의 생명을 해한 자는 피해자의 직계존속·직계비속 및 배우자에 대하여 재산상 손해 없는 경우에도 배상한다. 태아는 손해배상의 청구권에 관하여 이미 출생한 것으로 본다":"생명을 해한 자는 피해자의 직계존속·직계비속·배우자에게 재산상 손해가 없어도 배상하고 태아는 이미 출생한 것으로 봅니다.","타인의 신체·자유 또는 명예를 해하거나 기타 정신상 고통을 가한 자는 재산 이외의 손해에 대하여도 배상한다. 법원은 정기금 지급을 명하고 담보 제공을 명할 수 있다":"신체·자유·명예를 해하거나 정신적 고통을 준 자는 재산 이외의 손해, 곧 위자료도 배상하며 법원이 정기금 지급과 담보 제공을 명할 수 있어요.","타인의 채무를 담보하기 위한 질권설정자가 채무를 변제하거나 질권 실행으로 소유권을 잃은 때 보증채무 규정에 의하여 채무자에 대한 구상권이 있다(사후구상권만, 사전구상권 없음)":"물상보증인이 채무를 변제하거나 소유권을 잃으면 보증채무 규정에 따라 채무자에게 구상권이 있고 사전구상권은 없습니다.","타인의 토지를 통과하지 않으면 필요한 수도ㆍ소수관ㆍ가스관ㆍ전선 등을 시설할 수 없거나 과다한 비용을 요하는 경우 타인의 토지를 통과해 시설할 수 있다. 손해가 가장 적은 장소와 방법을 선택하고 요청에 의해 손해를 보상한다. 사정 변경 시 타토지 소유자는 시설변경을 청구할 수 있고 비용은 토지소유자가 부담한다":"타인 토지를 지나야만 수도·가스관·전선을 설치할 수 있으면 손해가 가장 적게 통과시키고 보상하며 사정이 바뀌면 시설 변경을 청구할 수 있습니다.","타인의 토지에 건물 기타 공작물이나 수목을 소유하기 위하여 그 토지를 사용하는 권리다. 지료는 요소가 아니라 지료 없는 지상권도 인정된다":"지상권은 타인 토지에 건물·공작물·수목을 소유하려고 그 토지를 사용하는 권리이며 지료는 요소가 아니라 지료 없는 지상권도 인정됩니다.","타인의 토지에 있는 건물에 전세권을 설정한 때 전세권의 효력은 그 건물의 소유를 목적으로 한 지상권 또는 임차권에 미친다. 전세권설정자는 전세권자의 동의 없이 지상권 또는 임차권을 소멸하게 하는 행위를 하지 못한다":"타인 토지 위 건물에 전세권을 설정하면 그 효력이 건물 소유를 위한 지상권·임차권에 미치고 설정자는 동의 없이 이를 소멸시킬 수 없어요.","타인의 행위 없이 객체를 직접 지배한다":"지배권은 다른 사람의 행위 없이 객체를 직접 지배하는 권리입니다.","타주점유자가 자기 명의로 소유권보존등기나 이전등기를 마친 것만으로는 소유의 의사를 표시한 것이 아니므로 자주점유로 전환되지 않는다. 점유시킨 자에 대한 소유의사 표시 또는 새 권원이 있어야 한다":"타주점유자가 자기 명의로 등기만 마쳐서는 소유 의사를 표시한 것이 아니므로 자주점유로 바뀌지 않으며 새 권원이나 소유의사 표시가 필요합니다.","태아가 불법행위로 사산된 경우 태아는 가해자에 대하여 자신의 생명침해로 인한 손해배상을 청구할 수 없다(포태 시 가해된 불법행위의 손해배상청구권도 인정되지 않음)":"태아가 불법행위로 사산되면 태아 자신의 생명침해를 이유로 한 손해배상은 청구할 수 없어요.","태아는 대습상속에 관하여 이미 출생한 것으로 본다(상속ㆍ유증ㆍ대습상속은 인정)":"태아는 대습상속에 관해서도 이미 출생한 것으로 취급됩니다.","태아는 부(父)의 생명침해로 인한 위자료청구권에 관하여 이미 출생한 것으로 본다":"태아는 아버지의 생명침해로 인한 위자료청구권에 관해 이미 태어난 것으로 봅니다.","태아는 손해배상의 청구권에 관하여는 이미 출생한 것으로 본다. 불법행위로 인한 손해배상청구권을 뜻한다(채무불이행 손해배상은 해당 없음)":"태아는 불법행위로 인한 손해배상청구권에 관해서는 이미 태어난 것으로 보며, 채무불이행은 해당하지 않아요.","태아는 증여(수증행위)에 관하여 이미 출생한 것으로 보지 않는다. 법정대리인이 태아를 대리하여 수증행위를 할 수도 없다":"증여는 태아에게 적용되는 개별 보호 사항이 아니어서 이미 태어난 것으로 보지 않고 법정대리인의 대리도 안 됩니다.","토지거래허가구역 내 토지매매계약이 유동적 무효인 경우 일방이 허가절차에 협력할 의무를 이행하지 않아도 상대방은 계약을 해제할 수 없다":"유동적 무효 상태의 토지매매에서는 일방이 허가절차 협력의무를 이행하지 않아도 상대방이 계약을 해제할 수 없습니다.","토지거래허가구역 내 토지에서 丙이 자신과 甲을 매매 당사자로 하는 토지거래허가를 받아 자신 앞으로 이전등기를 마쳤더라도 그 등기는 무효다":"토지거래허가구역에서 丙이 자신과 甲을 당사자로 하는 허가를 받아 마친 이전등기는 무효예요.","토지거래허가구역 내 토지의 매매계약에서 당사자가 이행에 착수하기 전에 토지거래허가를 받았다면 매수인은 계약금(3천만 원)을 포기하고 계약을 해제할 수 있다":"토지거래허가를 이행착수 전에 받았다면 매수인은 계약금을 포기하고 계약을 해제할 수 있습니다.","토지거래허가 전 계약은 유동적 무효 상태이며, 일방이 허가절차에 협력할 의무를 이행하지 않아도 상대방은 계약을 해제할 수 없다":"허가 전의 토지거래 계약은 효력이 정해지지 않은 유동적 무효여서 협력의무 불이행만으로 해제하지 못합니다.","토지공유자의 1인은 지분에 관하여 그 토지를 위한 지역권 또는 그 토지가 부담한 지역권을 소멸하게 하지 못한다. 토지의 분할이나 일부양도의 경우 지역권은 요역지의 각 부분을 위하여 또는 승역지의 각 부분에 존속한다":"토지공유자 한 명은 자기 지분만으로 지역권을 소멸시킬 수 없고 토지 분할 때는 지역권이 각 부분에 존속해요.","토지는 부동산이므로 동산질권의 객체가 될 수 없다":"토지는 동산이 아닌 부동산이므로 동산을 대상으로 하는 질권은 토지에 설정할 수 없습니다.","토지를 구성하는 토석(土石)은 특별한 경우를 제외하고는 토지와 분리하여 별도로 거래할 수 없다":"토지를 이루는 토석은 특별한 경우가 아니면 토지와 분리해 따로 거래할 수 없습니다.","토지를 목적으로 저당권을 설정한 후 설정자가 그 토지에 건물을 축조한 때 저당권자는 토지와 함께 그 건물에 대하여도 경매를 청구할 수 있다. 건물 경매대가에 대하여는 우선변제를 받을 권리가 없다. 저당권설정자로부터 용익권을 설정받은 자가 건물을 신축한 후 설정자가 그 건물 소유권을 취득한 경우에도 일괄경매를 청구할 수 있다":"토지에 저당권을 설정한 뒤 건물이 지어지면 토지와 건물을 함께 경매 청구할 수 있으나 건물 대가에서는 우선변제를 받지 못해요.","토지 및 그 정착물. 부동산 이외의 물건은 동산이다":"부동산은 토지와 그 정착물이고, 그 밖의 물건은 모두 동산이에요.","토지소유자가 독점적·배타적 사용수익권을 포기하여 공중의 이용에 제공한 경우 토지의 점유자를 상대로 부당이득반환을 청구할 수 없다":"토지소유자가 독점적 사용수익권을 포기해 공중이 쓰게 했다면 점유자에게 부당이득 반환을 청구할 수 없습니다.","토지소유자는 매연, 열기체, 액체, 음향, 진동 기타 유사한 것으로 이웃 토지의 사용을 방해하거나 이웃 거주자의 생활에 고통을 주지 않도록 적당한 조처를 할 의무가 있다. 이웃 거주자는 이웃 토지의 통상의 용도에 적당한 것이면 인용할 의무가 있다":"토지소유자는 매연이나 소음으로 이웃에 고통을 주지 않게 조처해야 하며 이웃은 통상의 용도에 적당한 것이면 참아야 합니다.","토지소유자는 이웃 토지로부터 자연히 흘러오는 물을 막지 못한다. 고지소유자는 이웃 저지에서 필요한 물을 정당한 사용범위를 넘어 막지 못한다. 승수의무에는 적극적으로 자연유수의 소통을 유지할 의무가 포함되지 않는다":"토지소유자는 이웃에서 자연히 흘러오는 물을 막지 못하지만 승수의무에 소통을 적극 유지할 의무까지 포함되지는 않아요.","토지와 건물을 함께 매도하였으나 토지에 대해서만 소유권이전등기가 된 때 매도인인 건물소유자, 매매로 소유자를 달리하게 되었으나 건물의 소유를 위하여 토지에 임대차계약을 체결한 경우, 담보가등기가 마쳐진 나대지에 소유자가 건물을 신축한 후 본등기가 되어 소유자가 달라진 경우":"토지만 이전등기된 매도인, 임대차를 맺은 경우, 담보가등기 나대지에 신축한 경우에는 관습상 법정지상권이 인정되지 않습니다.","토지와 건물이 동일한 소유자에 속하는 경우 그 토지나 건물에 대하여 담보가등기에 따른 본등기가 행하여진 때 건물 소유를 목적으로 지상권이 설정된 것으로 본다(존속기간과 지료는 법원이 정함). 담보가등기가 된 나대지에 소유자가 건물을 신축한 후 본등기가 되어 소유자가 달라진 경우 관습상 법정지상권은 성립하지 않는다":"본등기로 소유자가 달라지면 법정지상권이 설정된 것으로 보지만 담보가등기 나대지에 신축한 경우의 관습상 법정지상권은 성립하지 않습니다.","토지임대인이 변제기를 경과한 최후 2년의 차임채권에 의하여 지상 임차인 소유 건물을 압류한 때 저당권과 동일한 효력이 있다. 토지임대인이 임대차에 관한 채권에 의하여 임차지에 부속한 임차인 소유 동산 및 과실을 압류한 때, 건물 임대인이 부속한 임차인 소유 동산을 압류한 때 질권과 동일한 효력이 있다":"토지임대인이 최후 2년의 차임채권으로 건물을 압류하면 저당권과 같은 효력이 있고 임차인 소유 동산을 압류하면 질권과 같은 효력이 있어요.","토지임차권 등기를 하지 않았더라도 지상건물 등기로 제3자에게 대항할 수 있다":"임차권 등기가 없어도 임차인이 지상건물을 등기해 두면 제3자에게 대항할 수 있습니다.","토지임차인의 건물 기타 공작물 매수청구권에 관한 제643조는 토지의 전세권에도 유추적용될 수 있다":"토지임차인의 건물 매수청구권 규정은 토지의 전세권에도 유추적용될 수 있어요.","통상의 손해를 한도로 한다. 특별한 사정으로 인한 손해는 채무자가 그 사정을 알았거나 알 수 있었을 때에 한하여 배상책임이 있다":"손해배상은 통상의 손해가 한도이고 특별한 사정으로 인한 손해는 채무자가 알았거나 알 수 있었을 때만 배상합니다.","특별한 관습이 없으면 경계로부터 반 미터 이상의 거리를 두어야 한다. 위반 시 건물의 변경이나 철거를 청구할 수 있으나 건축 착수 후 1년이 경과하거나 건물이 완성된 후에는 손해배상만 청구할 수 있다":"특별한 관습이 없으면 경계에서 반 미터 이상 떨어져 건축해야 하고, 착수 후 1년 지나거나 완성되면 손해배상만 청구할 수 있습니다.","특별한 사정이 없는 한 장래에 발생할 특정의 조건부 채권을 담보하기 위하여도 저당권을 설정할 수 있다":"조건이 붙어 장래 생길 특정 채권도 저당권으로 담보할 수 있습니다.","특별한 사정이 없는 한 형성권적 기한이익 상실 특약(채권자의 청구 필요)으로 추정한다":"기한이익 상실 특약은 특별한 사정이 없으면 채권자의 청구가 필요한 형성권적 특약으로 추정합니다.","특별한 약정이 없으면 위임인에 대하여 보수를 청구하지 못한다(무보수가 원칙). 보수를 받을 경우 위임사무 완료 후 청구(기간으로 정한 때에는 그 기간 경과 후). 수임인의 책임 없는 사유로 위임이 종료된 때 이미 처리한 사무 비율에 따른 보수를 청구할 수 있다":"위임은 특별한 약정이 없으면 무보수가 원칙이고 보수는 사무 완료 후 청구하며 수임인 책임 없이 종료되면 처리한 비율만큼 청구할 수 있어요.","특별한 의사표시가 없으면 변제기 전이라도 할 수 있으나 상대방의 손해는 배상하여야 한다":"특별한 의사표시가 없으면 변제기 전에도 갚을 수 있고 다만 상대방의 손해는 배상해야 합니다.","특별한 절차가 필요한 행위는 기간 내에 그 절차를 밟은 확답을 발송하지 않으면 취소한 것으로 본다":"후견감독인 동의 같은 특별한 절차가 필요한 행위는 답이 없으면 추인이 아니라 취소로 봅니다.","특약으로 종물을 제외하거나 종물만 별도로 처분할 수 있다(제100조 제2항은 임의규정)":"종물 규정은 임의규정이라서 특약으로 종물을 제외하거나 종물만 따로 처분할 수 있습니다.","특정물의 인도가 채권의 목적인 때 채무자는 인도하기까지 선량한 관리자의 주의로 보존하여야 한다":"특정물채권의 채무자는 인도할 때까지 선량한 관리자의 주의로 그 물건을 보존해야 합니다.","특정인에게 일정한 행위(급부)를 요구하는 권리이다":"청구권은 특정인에게 일정한 행위, 곧 급부를 요구하는 권리입니다.","특정할 수 있는 집합물(예: 양만장 내 뱀장어 전부)에는 1개의 양도담보권을 설정할 수 있다":"뱀장어 전부처럼 특정할 수 있는 집합물에는 양도담보권을 하나 설정할 수 있습니다.","특정할 수 있는 집합물(집합동산) 전체를 하나의 재산권으로 하는 양도담보권을 설정할 수 있다(일물일권주의의 예외)":"특정할 수 있는 집합물 전체를 하나의 재산권으로 삼아 양도담보권을 설정할 수 있으며 이는 일물일권주의의 예외예요.","특정후견의 심판이 있어도 피특정후견인의 행위능력은 제한되지 않는다":"특정후견이 개시되어도 후원받는 사람의 행위능력은 그대로 유지됩니다.","파산절차참가는 채권자가 취소하거나 청구가 각하되면 중단 효력이 없다. 지급명령은 채권자가 법정기간 내 가집행신청을 하지 않아 효력을 잃으면 중단 효력이 없다. 지급명령신청은 재판상 청구에 포함된다":"파산절차참가나 지급명령이 효력을 잃으면 중단 효력이 없고, 지급명령신청은 재판상 청구에 포함됩니다.","파산채무자의 가장채권에 관한 파산관재인은 제108조 제2항의 제3자에 해당한다":"파산채무자가 가장한 채권의 파산관재인도 허위표시 규정에서 보호받는 제3자로 봅니다.","판결에 의하여 확정된 채권은 단기의 소멸시효에 해당하는 것이라도 10년으로 한다. 파산절차ㆍ재판상 화해ㆍ조정 등 판결과 동일한 효력이 있는 것으로 확정된 채권도 같다(지급명령 확정 포함). 판결 확정 당시 변제기가 도래하지 않은 채권에는 적용하지 않는다":"판결로 확정된 채권은 단기시효 대상이라도 10년으로 하고, 판결 당시 변제기가 안 된 채권에는 적용하지 않아요.","평온ㆍ공연하게 동산을 양수한 자가 선의이며 과실 없이 점유한 경우 양도인이 정당한 소유자가 아닌 때에도 즉시 소유권을 취득한다. 도품ㆍ유실물은 피해자 또는 유실자가 도난 또는 유실한 날부터 2년 내에 반환을 청구할 수 있다(금전은 제외)":"평온·공연하게 선의·무과실로 동산을 양수하면 양도인이 무권리자여도 소유권을 취득하며, 도품·유실물은 2년 내 반환 청구가 가능합니다.","표의자가 과실 없이 상대방 또는 그 소재를 알지 못하는 경우 민사소송법 공시송달 규정에 의하여 송달할 수 있다":"상대방이나 그 소재를 과실 없이 모르면 민사소송법 공시송달 규정으로 송달할 수 있습니다.","표의자에게 착오가 있었다는 사실 및 착오가 의사표시에 결정적 영향을 미쳤다는 점은 취소를 주장하는 표의자가 증명한다":"착오가 있었고 그것이 결정적 영향을 미쳤다는 점은 취소를 주장하는 표의자가 증명해요.","표의자의 실제 의사를 밝히는 해석이다":"자연적 해석은 표의자의 실제 의사를 밝히는 해석입니다.","표의자의 중대한 과실 증명책임은 취소를 저지하려는 상대방에게 있다":"표의자의 중대한 과실은 취소를 막으려는 상대방이 증명해야 합니다.","표현대리가 성립해도 무권대리가 유권대리로 전환되는 것이 아니다. 상대방에게 과실이 있어도 과실상계 법리를 유추적용하여 본인의 책임을 감경할 수 없다":"표현대리가 성립해도 무권대리가 유권대리로 바뀌는 것이 아니고, 상대방 과실을 이유로 본인의 책임을 줄일 수도 없어요.","피성년후견인의 법률행위는 취소할 수 있다. 가정법원은 취소할 수 없는 법률행위의 범위를 정할 수 있고 청구에 의해 변경할 수 있다. 일용품 구입 등 일상생활에 필요하고 대가가 과도하지 않은 법률행위는 성년후견인이 취소할 수 없다":"피성년후견인의 법률행위는 취소할 수 있지만, 일상생활에 필요하고 대가가 과도하지 않은 행위는 후견인도 취소하지 못해요.","피성년후견인이 법정대리인의 동의서를 위조하여 계약을 체결한 경우에도 성년후견인은 취소할 수 있다":"피성년후견인이 동의서를 위조해 체결한 계약도 성년후견인은 취소할 수 있어요.","피한정후견인ㆍ피특정후견인에 대한 성년후견개시 시 종전 한정후견 또는 특정후견의 종료 심판을 한다. 피성년후견인ㆍ피특정후견인에 대한 한정후견개시 시에도 종전 성년후견 또는 특정후견의 종료 심판을 한다":"성년후견을 개시하면 종전의 한정후견이나 특정후견을 끝내는 심판을 함께 하고, 한정후견개시 때도 마찬가지예요.","피한정후견인은 임의대리인이 될 수 있다":"피한정후견인도 타인의 임의대리인이 될 수 있어요.","피한정후견인이 한정후견인의 동의를 받아야 하는 행위의 범위는 가정법원이 정한다. 범위 변경은 본인ㆍ배우자ㆍ4촌 이내 친족ㆍ한정후견인 등의 청구에 의한다":"피한정후견인이 동의를 받아야 하는 행위의 범위는 가정법원이 정하고, 변경은 본인·배우자·4촌 이내 친족 등의 청구로 합니다.","피해자나 법정대리인이 손해 및 가해자를 안 날부터 3년, 불법행위를 한 날부터 10년. 미성년자가 성적 침해를 당한 경우 성년이 될 때까지 진행하지 않는다":"불법행위 시효는 손해와 가해자를 안 날부터 3년, 행위일부터 10년이며 미성년자가 성적 침해를 당하면 성년이 될 때까지 진행하지 않습니다.","필요비는 소유자에게 상환을 청구하고, 유익비는 가액 증가가 현존한 경우에 한하여 소유자의 선택에 좇아 지출액이나 증가액의 상환을 청구한다(법원이 상환기간 허여 가능)":"필요비는 소유자에게 상환을 청구하고 유익비는 가액 증가가 현존할 때 소유자의 선택에 따라 지출액이나 증가액을 청구합니다.","필요비는 즉시 상환 청구. 유익비는 임대차 종료 시 가액의 증가가 현존한 때에 한하여 임대인이 지출금액이나 증가액을 상환(법원이 임대인 청구로 상환기간 허여 가능). 점유자 유익비상환청구권과 같이 청구권이다":"필요비는 즉시 상환을 청구하고 유익비는 종료 시 가액 증가가 남아 있을 때 임대인이 지출액이나 증가액을 상환하며 이는 청구권입니다.","하자담보책임에 기한 매수인의 손해배상청구권은 제척기간 규정이 있어도 소멸시효의 적용이 배제되지 않는다. 매도인의 담보책임 권리행사기간(제척기간) 예: 타인 권리 일부 취득불능 선의 매수인은 안 날부터, 악의는 계약한 날부터 1년(제573조), 하자담보 안 날부터 6월(제582조)":"하자담보 손해배상청구권은 제척기간이 있어도 소멸시효 적용이 배제되지 않으며, 담보책임 제척기간은 안 날부터 1년이나 6월 등으로 정해집니다.","하자담보책임이 성립하더라도 중요부분 착오가 있고 중과실이 없는 매수인은 착오를 이유로 계약을 취소할 수 있다(경합)":"하자담보책임이 성립해도 중요부분 착오가 있고 중과실이 없는 매수인은 착오 취소를 할 수 있어 두 주장이 경합해요.","하자로 계약의 목적을 달성할 수 없는 때 해제할 수 있다. 단 건물 기타 토지의 공작물에 대하여는 해제할 수 없다. 완성된 주택의 하자로 목적을 달성할 수 없어도 해제할 수 없다":"하자로 목적을 달성할 수 없으면 해제할 수 있으나 건물이나 토지의 공작물, 완성된 주택은 해제할 수 없어요.","하자보수에 갈음한 손해배상청구권은 하자가 발생하여 보수가 필요하게 된 시점에서 성립한다. 하자확대손해로 인한 수급인의 손해배상채무와 도급인의 공사대금채무는 동시이행 관계다":"하자보수에 갈음한 손해배상청구권은 보수가 필요하게 된 시점에 성립하고 하자확대손해 배상채무와 공사대금채무는 동시이행 관계입니다.","하자의 보수·손해배상 청구 및 해제는 목적물의 인도를 받은 날부터 1년 내(인도를 요하지 않는 경우 일의 종료일부터). 토지·건물 기타 공작물은 인도 후 5년(석조·석회조·연와조·금속 기타 유사한 재료는 10년). 멸실·훼손된 때는 그 날부터 1년 내 행사한다":"하자 청구는 인도받은 날부터 1년, 토지·건물 등은 인도 후 5년(석조 등은 10년)이며 멸실·훼손되면 그날부터 1년입니다.","하자확대손해로 인한 수급인의 손해배상채무와 도급인의 공사대금채무는 동시이행 관계다":"하자확대손해를 배상할 수급인의 채무와 도급인의 공사대금채무는 서로 동시이행 관계에 놓입니다.","한정후견이 종료된 후에도 종료 전에 동의 없이 한 법률행위는 취소할 수 있다":"한정후견이 끝난 뒤에도 끝나기 전 동의 없이 한 법률행위는 취소할 수 있습니다.","한정후견인의 동의가 필요한 법률행위를 동의 없이 하면 취소할 수 있다. 일용품 구입 등 일상생활에 필요하고 대가가 과도하지 않은 행위는 제외된다":"한정후견인의 동의가 필요한 법률행위를 동의 없이 하면 취소할 수 있지만 일상생활 행위는 제외됩니다.","한정후견인이 이익침해 염려에도 동의를 하지 않으면 가정법원은 피한정후견인의 청구에 의해 동의를 갈음하는 허가를 할 수 있다":"한정후견인이 피한정후견인의 이익을 해칠 염려가 있는데도 동의하지 않으면 법원이 청구에 따라 동의를 갈음하는 허가를 해 줍니다.","합의해제에는 해제에 관한 제543조 이하의 규정이 원칙적으로 적용되지 않는다. 따라서 채무불이행에 따른 손해배상을 원칙적으로 청구할 수 없다(특약이 있으면 제외)":"합의해제에는 법정해제 규정이 원칙적으로 적용되지 않아 채무불이행에 따른 손해배상은 특약이 없으면 청구할 수 없습니다.","합의해지로 반환할 금전에는 별도 약정이 없는 한 받은 날부터의 이자를 더하여 지급할 의무가 없다":"합의해지로 돌려줄 돈에는 따로 약정이 없는 한 받은 날부터의 이자를 붙일 의무가 없습니다.","해산등기는 취임 후 3주일 내에 주사무소 소재지에서 한다 · 해산 사유와 연월일, 청산인 성명ㆍ주소, 대표권 제한을 등기한다 · 주무관청에 3주간 내 신고한다":"해산등기는 취임 후 3주일 내에 주사무소 소재지에서 하고, 주무관청에도 3주간 내 신고합니다.","해제권자의 고의나 과실로 목적물이 현저히 훼손되거나 반환할 수 없게 된 때 또는 가공·개조로 다른 종류의 물건으로 변경된 때":"해제권자의 고의·과실로 목적물이 크게 훼손되거나 반환할 수 없게 되거나 다른 종류로 바뀌면 해제권이 소멸해요.","해제는 소급효가 있어 계약이 처음부터 없었던 것으로 된다(장래에 향하여 효력을 잃는 것은 해지)":"해제는 소급효가 있어 계약이 처음부터 없던 것이 되고, 장래에만 효력을 잃는 것은 해지입니다.","해제로 인한 원상회복의무는 동시이행 관계다(제536조 준용)":"해제로 인한 원상회복의무는 동시이행 관계입니다.","해제와 취소는 별개다: 매도인이 매매계약을 적법하게 해제한 뒤에도 매수인은 착오를 이유로 취소할 수 있다":"해제를 했더라도 매수인은 아직 착오를 이유로 계약을 취소할 수 있으니 두 제도는 서로 별개입니다.","해제조건이면 그 법률행위는 무효로 한다":"기성조건이 해제조건이면 그 법률행위는 무효입니다.","해제조건이면 조건 없는 법률행위로 한다":"불능조건이 해제조건이면 조건 없는 법률행위로 봅니다.","해제조건 있는 법률행위는 조건이 성취한 때로부터 효력을 잃는다":"해제조건은 이미 생긴 효력이 조건이 이루어지는 순간부터 없어지게 하는 조건입니다.","해지 또는 해제는 상대방에 대한 의사표시로 한다. 이 의사표시는 철회하지 못한다(해지·해제 모두 도달 후 철회 불가)":"해지와 해제는 상대방에 대한 의사표시로 하며 철회할 수 없습니다.","해지·해제는 손해배상의 청구에 영향을 미치지 않는다. 해제 후에도 채무불이행에 따른 손해배상을 별도로 청구할 수 있다":"해지·해제는 손해배상 청구에 영향이 없어 해제 후에도 채무불이행 손해배상을 따로 청구할 수 있습니다.","행사기간을 정하지 않은 때 상대방은 상당한 기간을 정하여 확답을 최고할 수 있다. 그 기간 내에 해제 통지를 받지 못하면 해제권은 소멸한다":"행사기간이 없으면 상대방이 상당한 기간을 정해 확답을 최고할 수 있고 그 기간 내 해제 통지가 없으면 해제권이 소멸합니다.","행위 당시 상대방이 대리권 없는 행위에 동의하거나 대리권을 다투지 아니한 때에 한하여 위 규정을 준용한다":"단독행위의 무권대리는 상대방이 대리권 없는 행위에 동의하거나 다투지 않은 때에 한해 같은 규정을 준용해요.","허락받은 특정한 영업에 관하여 성년자와 동일한 행위능력이 있다. 법정대리인은 허락을 취소 또는 제한할 수 있으나 선의의 제3자에게 대항하지 못한다":"허락받은 특정 영업에서는 성년자와 같은 행위능력이 있고, 허락의 취소·제한은 선의 제3자에게 대항하지 못합니다.","허위 전세권에 저당권을 취득한 자, 가장매매 매수인으로부터 매매예약에 기한 가등기권을 취득한 자, 가장 근저당의 피담보채권을 가압류한 자, 가장 임대차보증금반환채권 양수인의 채권자로서 압류ㆍ추심명령을 받은 자, 가장채권 보유자의 파산관재인, 가장 전세권 설정계약에 의한 전세금반환채권을 가압류한 채권자, 허위 저당권 실행으로 소유권을 취득한 경락인":"허위 전세권의 저당권자, 가장 근저당 채권의 가압류권자, 가장채권 보유자의 파산관재인 등이 선의일 때 보호받는 제삼자예요.","허위표시로 무효인 법률행위에 따른 법률효과를 침해하는 것처럼 보이는 채무불이행이 있어도 손해배상을 청구할 수 없다":"허위표시로 무효인 법률행위의 효과를 침해하는 듯한 채무불이행이 있어도 손해배상은 청구할 수 없어요.","허위표시에 의한 가장행위라도 사해행위 요건을 갖추면 채권자취소권의 대상이 된다":"가장행위라도 채권자를 해하는 사해행위의 요건을 갖추면 채권자취소권으로 다툴 수 있습니다.","현실적으로 점유하고 있지 않은 불법점유자(점유를 이전한 자)를 상대로는 소유물의 인도를 청구할 수 없다":"점유를 이전해 현재 점유하지 않는 불법점유자에게는 소유물의 인도를 청구할 수 없어요.","현존하는 권리의 변동을 직접 일으키는 법률행위다":"처분행위는 이미 있는 권리를 직접 바꾸는 법률행위예요.","협의가 성립되지 않으면 법원에 분할을 청구할 수 있다. 현물로 분할할 수 없거나 분할로 현저히 가액이 감손될 염려가 있으면 법원은 경매를 명할 수 있다. 법원은 청구자가 요구한 분할방법에 구애받지 않고 지분 비율에 따라 합리적으로 분할할 수 있다":"협의가 안 되면 법원에 분할을 청구하고 현물분할이 어렵거나 가액이 크게 줄면 경매를 명할 수 있으며 법원은 청구 방법에 얽매이지 않아요.","형사사건에서 변호사가 성공보수금을 약정한 경우(2023-14 선지 1은 반사회질서에 해당하는 보기)":"형사사건에서 변호사가 성공보수금을 약정한 것은 반사회질서에 해당하는 보기로 제시됩니다.","화해를 위한 소환은 상대방이 출석하지 않거나 화해가 성립되지 않으면 1월 내에 소를 제기하지 않는 한 중단 효력이 없다. 임의출석도 같다":"화해를 위한 소환은 상대방이 오지 않거나 화해가 안 되면 1월 내에 소를 내야 중단 효력이 유지됩니다.","확정기한부 채무는 기한이 도래한 때부터 지체책임을 진다":"확정기한이 있는 채무는 기한이 오는 순간부터 지체책임이 시작됩니다.","확정기한부 채무의 기한 도래 후 기한을 유예하기로 합의한 경우 변경된 이행기가 도래한 때부터 시효가 다시 진행한다":"기한 도래 후 유예를 합의하면 변경된 이행기가 도래한 때부터 시효가 다시 진행해요.","횡령한 금전으로 자신의 채권자에게 변제한 경우 채권자가 변제 수령 시 횡령 사실을 알았거나 모른 데 중대한 과실이 있으면 채권자의 금전취득은 피해자에 대한 관계에서 법률상 원인이 없다(악의 또는 중과실 시)":"횡령한 금전으로 채권자에게 변제했을 때 채권자가 횡령 사실을 알았거나 중대한 과실로 몰랐다면 금전 취득은 법률상 원인이 없어요.","효력이 상실된 관습법의 예는 종중 구성원의 자격을 성년남자만으로 제한하는 종래의 관습법이다":"종중 구성원을 성년남자로만 제한하던 종래 관습법이 효력을 잃은 대표 예입니다.","후순위 담보권자는 선순위 담보권의 피담보채권의 시효소멸로 직접 이익을 받는 자가 아니므로 그 피담보채권의 소멸시효 완성을 주장할 수 없다":"후순위 담보권자는 선순위 채권의 시효 소멸로 직접 이득을 보는 사람이 아니어서 그 시효를 주장하지 못합니다.","후순위 저당권자가 경매를 신청한 경우 선순위 근저당권의 피담보채무 확정시기는 매수인이 매각대금을 완납한 때다":"후순위 저당권자의 경매 신청이 있으면 선순위 근저당의 피담보채무는 매각대금을 다 낸 때 확정됩니다.","흐르는 물이 저지에서 폐색된 때 고지소유자는 자비로 소통에 필요한 공사를 할 수 있다. 공작물의 파손ㆍ폐색으로 타인 토지에 손해 염려가 있으면 타인은 보수ㆍ소통ㆍ예방에 필요한 청구를 할 수 있다":"저지에서 물이 막히면 고지소유자는 자비로 소통공사를 할 수 있고 공작물 파손으로 손해 염려가 있으면 보수·예방을 청구할 수 있습니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
